    "summary": "零镜头代理，也称为无训练指标，被广泛采用，以减少神经网络评估场景（如神经架构搜索（NAS））的计算开销，因为它们不需要任何训练。现有的零拍摄指标有几个局限性，包括与真实性能的相关性较弱，以及对不同网络或下游任务的泛化较差。例如，这些指标中的大多数仅适用于 神经网络（CNN）或变压器，但不是两者兼而有之。为了解决这些局限性，我们提出了Sample-Wise激活模式（SWAP）及其衍生物SWAP-Score，这是一种新颖且高效的零点指标。SWAP-Score广泛适用于架构系列和任务领域，在大多数任务中显示出强大的预测性能。该指标测量神经网络在一小批样本上的表达能力，显示出高 与神经网络的地面真实性能相关。对于CNN和Transformer， SWAP-Score在计算机视觉和自然语言处理任务方面的表现优于现有的零点指标。例如， DARTS CNN的SWAP-Score和CIFAR-10验证精度之间的Spearman相关系数为0.93，胶水任务的FlexiBERT变压器的相关系数为0.71。此外， SWAP-Score与标签无关，因此可以应用于预训练 语言模型的阶段，以评估其在下游任务中的性能。当应用于NAS （支持SWAP的NAS）时， SWAP-NAS可以分别在CIFAR-10和ImageNet上使用大约6分钟和9分钟的GPU时间实现具有竞争力的性能。",
