    "summary": "深度神经网络（DNN）极易受到对抗性示例（AE）攻击，构成严重的安全威胁。作为一类特定的对抗性攻击，小扰动对抗（SPA）攻击由于其微妙的扰动幅度而成为对DNN的更严重威胁，使其更难被检测到。然而，仍然缺乏旨在抵御SPA攻击的具体解决方案。为了填补这一空白，我们建议 本文中用于SPA示例检测的决策边界弯曲（PDBB）。通过主动弯曲目标DNN的决策边界， PDBB可以准确区分SPA示例和良性示例。具体而言， PDBB利用示例扰动训练策略来训练目标DNN，使其能够拥有理想的弯曲决策边界。此外， PDBB还开发了基于投影的辅助测量方法， 决策边界在给定测试实例附近的凹凸度，从而使PDBB实现高检测精度。广泛的实验表明， PDBB不仅在检测SPA示例方面实现了最先进的（SOTA）性能，而且在检测一般AE （可能具有相对较大的扰动）方面实现了高性能。",
