    "link": "https://doi.org/10.1109/tpami.2026.3683057",
    "direction": "人工智能",
    "summary": "由于基数最小化在优化中的兴起，稀疏支持向量机（SSVM）最近引起了人们的广泛关注，并显示出比凸支持向量机具有一定的经验优势。导出SSVM的常见方法是将基数函数（如$\\ ell_{0} $ ℓ0-norm）添加到凸SVM的双重问题中。然而，这一过程缺乏理论依据。本文通过为这种SSVM公式开发局部对偶理论来填补空白，并探索 它与铰链损失支持向量机（hSVM）和斜坡损失支持向量机（rSVM）的关系。特别地，我们证明了导出的SSVM正好是0/1损失SVM的对偶问题，并且线性表示器定理适用于它们的局部解。SSVM的局部解决方案还为选择hSVM和rSVM的超参数提供了指导。在特定条件下，我们展示了hSVM的一系列全局解收敛到0/1损失SVM的局部解。此外， 0/1损失SVM的局部最小化器是rSVM的局部最小化器。这就解释了为什么在先前的实证研究中， SSVM诱导的局部解优于hSVM和rSVM。我们进一步对真实数据集进行了数值测试，并通过使用本文中提出的局部NICE解决方案来展示SSVM的潜在优势。",
