    "summary": "意见分歧现象在文献中得到了实证观察和报道，受到社交网络结构等多种因素的影响。网络科学的一个重要发现是，包括社交网络在内的大多数现实生活中的网络都是无标度且稀疏的。本文研究稀疏无标度社会网络中的嘈杂意见动态，揭示幂律拓扑对舆论分歧的影响。 流行的离散时间DeGroot模型，用于图表中的意见动态，其中节点的意见受到白噪声的影响。我们首先研究了许多具有无标度拓扑的现实和模型网络中的意见分歧，该无标度拓扑接近常数，表明无标度结构在意见动态中具有抗噪性。此外，现有的估计意见分歧的算法对于大规模网络来说在计算上是不切实际的，因为它们的高 为了解决这一挑战，我们引入了亚线性时间算法，以理论上有保证的误差来近似这个量。该算法有效地模拟了从节点子集开始的截断随机游走，同时保持了准确的估计。广泛的实验证明了它的效率、准确性和可扩展性。",
