    "summary": "端到端延迟预测对于智能网络管理至关重要，特别是在延迟敏感和动态环境中。虽然最近的深度学习（DL）模型显示出有希望的结果，但它们对路由路径顺序编码的依赖将泛化限制在看不见的路由方案上。在本文中，我们提出了一种基于鲁棒图神经网络（GNN）的延迟预测模型，通过引入全局路由来克服这一局限性。 表示和路由感知注意机制。该模型从统一拓扑路由映射中查询与流相关的特征，而不依赖于路由序列。此外，基于掩码的子图采样策略使模型能够从部分流交互中推断全局路由相关性，进一步增强其适应性。在四个公共数据集-TnCwD、NSFNET、GBN和GEANT2上进行了广泛的实验。结果表明，我们的模型 不仅在预测精度上优于现有方法，而且在各种路由配置中表现出强大的泛化能力。未来的工作将侧重于在更复杂和动态的路由场景下进一步验证模型。",
