    "direction": "人工智能",
    "summary": "在神经网络训练中处理吵闹的标签是根本的,因为这种噪声可以扭曲模型优化,导致性能下降.本条在节点分类上用图神经网络(GNNs)表示零,以在利用节点属性和边缘连接方面的适切性而著称. 尽管如此,GNN由于本身的特征传播和信息合并,比起传统的神经网络,它更容易被标签噪声误导。 虽然现有的强力GNN为防噪声的不利影响提供了防御,但它们往往低估了训练期间噪声标签带来的风险,或低估了强化边缘对错误聚合和噪声边缘的重要性。弥补这些差距,我们引入了一种新的强力GNN框架,即降噪GNN(英语:NomiGNN),旨在增强GNNs抗标签噪声的强性.NomiGNN估计噪声分布,并精炼损失优化,以抵消训练过程中的噪声. 此外,通过为新的预测任务设置边缘标签,我们通过同标签概率来帮助学习样本关系,减轻来自吵闹边缘的错配,并加强节点分类. 为了补充这一点,我们纳入了伪的标签和迭代学习,以弥补标签的短缺和估计的不准确。NomiGNN得到理论原理和经验证据的证实。 对5个真实世界图表的实验评价凸显了诺米GN对吵闹的标签腐败的超强韧性,表现优于8个基准GNN模型.",
