    "direction": "人工智能",
    "summary": "机器学习模型往往在数据分布不同的领域,如噪音水平不同,难以概括,导致性能退化。传统战略,如个人化培训(每个领域培训不同的模式)和联合培训(所有领域使用单一模式),在灵活性和有效性方面都有重大限制。 为了解决这个问题,我们提出了基于可解释的无滚动网络的回归任务的两个新领域适应方法——由迭代优化算法启发的深层架构. 这些模型利用选定金枪鱼参数在功能上对域变量的依赖,使得在推论期间能够进行有控制的适应. 我们的方法包括使用已知域参数进行动态调整的参数Tuntable-Domain适应(P-TDA)和直接从输入数据推断域适应(DD-TDA)。 我们验证了我们对涉及噪声适应性信号零散恢复、域适应性增益校准和域适应性相检索的压缩感测问题的方法,显示了与域特定模型的改进性能或可比较性能,同时超过了联合培训基线。这项工作突出了未滚动网络在回归环境下有效、可解释域适应的潜力。",
