    "direction": "人工智能",
    "summary": "很少的速成学习(FSL)使深层学习模型能够以最小的标注数据将普通化到看不见的类别,使它对于诸如保健等数据约束的领域至关重要。 然而,现有的FSL模型往往缺乏可解释性,模糊了预测背后的推理,限制了对部署的信任. 在这项工作中,我们引入了对比性的跨类归属(C3A),以加强FSL中的可解释性.具体地说,我们提出C3A来解释查询预测及其变体(C3A-E)来解释中枢学习.与以前为具体架构设计的可解释性方法不同,我们的方法是分类-不可知的,利用骨干网络,确保广泛适用于各种FSL范式。 此外,我们提议采用对比性地方描述法,将天真-贝耶近邻(NBNN)和费舍尔得分归属(Fisher country)结合起来,以保留精细的细节,并加强阶级间的歧视。 最后,我们综合评估了四个FSL基准的方法,显示与最先进的方法相比,方法不断改进,插入曲线以下区域的绝对收益为19.72%,删除曲线以上区域的绝对收益为25.88%。 我们的Posthoc设计确保了与各种架构的无缝融合,包括Conv64F,ResNet12,ResNet18和Vit.实验结果证实,与现有的FSL可解释性方法相比,C3A及其变体(C3A-E)提供了更稳定和可解释的解释性,更深入地洞察了零星的学习过程. 我们已在https://github.com/MountainChenCad/C3A上公布我们的代码。",
