    "direction": "信息安全",
    "summary": "联邦不学习组织最近成为从训练有素的模型中删除客户数据的一个有希望的范例,使联邦学习系统能够维护隐私和遵守监管规定。 然而,现有的后续方法主要侧重于数据清除的效率,使安全弱点基本上没有得到探讨。 在本文中,我们提出FedUBA,一个联邦学习激活的BackdoorAttack,它利用不学习过程本身来偷偷触发后门行为.与传统的后门攻击在学习过程中通过直接数据中毒的方式嵌入后门不同,FedUBA利用训练后不学习的过程暗中嵌入后门行为.FedUBA的核心在于误导全球模型为后门标本解析更多与有影响力的标本相关的信息,从而对后门标本产生不利影响. 为了实现这一目标,FedUBA采用了原则性的三阶段框架,这涉及到产生隐蔽的后门触发器,通过黑匣子灵敏度分析来选择对后门样本预测影响最大的有影响力的样本,以及精心策划恶意的不学习请求,以诱导全球模型激活后门行为. 通过这样做,我们可以通过启动恶意的不学习请求,大大改变后门样本上的预测. 对五个现实数据集的广泛实验表明,FedUBA在后门采样上有效实现了80%的攻击成功率,只触发了0.5%的恶意失学请求.",
