    "summary": "由于智能机器之间日益需要合作,合作性多代理强化学习(MARL)更加重要。 然而,一种占主导地位的合作性MARL方法依赖于单调值分解,从而能够实现可扩展的分散执行,但限制了可代表的联合行动价值类别。 然而,现有的补救措施偏向于高价值样本的学习目标,在有条理的回报下,这些样本可能很脆弱,因为乐观的强调可能会扩大幸运但不够理想的轨迹。 为了解决这一挑战,我们提出目标转型,将非模拟和结构化的学习目标映射成一个单一的、能代表的代词,同时保持最佳的联合行动。 基于这一想法,我们开发了基于价值和政策的不确定-意识目标转变(UT2),将不确定性估计器和最佳个人协调信封结合起来。 关于多种合作的MARL基准的实验表明,UT2在强基线上既能提高性能,又能提高稳定性,随着非通知性和花样性的增长,收益更大。",
