    "summary": "最近,图表快速学习越来越受到重视,为下游图表学习任务调整了经过预先培训的GNN模型。 然而,现有的作品一般会在所有的图元素(如节点,边缘,节点属性等)上进行提示,这是次优的,显然是多余的. 为了解决这一问题,我们建议利用稀有的表达理论来进行图表提示和目前的图表示意图。普惠制旨在适应和稀少地选择最佳要素(例如,某些节点属性),以实现紧凑,促进下游任务。具体地说,我们提出了两种普惠制模式,即图样特性提示(GSFP)和图样特性多元提示(GSmFP)。GSFP和GSmFP都为调整任何经过预先培训的具体的GNN提供了总体计划,这些GNN可以选择一些理想的属性,通过使用Sparsity制导的即时学习来推动.已经设计了一个简单而有效的算法来解决GSFP和GSmFP模型. 关于16个广泛使用的基准数据集的实验验证了拟议全球供应链的有效性和优势。",
