    "summary": "分散的联邦学习由于培训速度加快、隐私保护以及通信间接费用减少,已成为集中式建筑的替代办法。 在分散通信中,Centralized Fool Learning中的服务器聚合阶段转移到客户端,这意味着客户端以对等方式相互连接. 然而,与集中模式相比,分散式联邦学习中的数据异质性将导致汇总模型之间的较大差异,导致培训的趋同速度缓慢,测试中的通用化表现不佳. 为了解决这些问题,我们引入了催化加速法,并提出了名为DFedCata的加速分散联邦学习算法。 它由两个主要部分组成:莫雷欧信封功能,主要处理数据异质性导致的客户端参数不一致,以及内斯特罗夫的推算步骤,这加速了聚合阶段.理论上,我们证明了算法的优化误差约束和概括误差约束,提供了对算法性质的进一步理解,以及对超参数选择的理论视角. 从经验上讲,我们在CIFAR10/100和Tiny-ImageNet上用各种非二维数据分布来显示拟议算法在趋同速度、计算成本和归纳性能方面的优点。 此外,还进行了广泛的实验来验证DFedCata的理论性质,显示出理论与经验观测之间的强烈一致性.",
