    "summary": "时间序列中的域通用(DG)由于域位转移,尤其是严格DG设置下,培训期间没有目标域数据,因此构成重大挑战. 为了解决这一问题,我们提议采用AFM-CIR,即一个统一框架,将语义-同义-导调傅里叶混合法(AFM)与Causality-Inspired Reression(CIR)相结合。具体地说,我们构筑了一个域-不变量的定序-保留制导嵌入式,驱动基于类似性的振幅混合的适应性调制和最短角相扰动,从而产生与标签一致和因果一致的增强样品。 然后,CIR通过关联性因子化来强制进行偏移和跨维独立,而因果充足性则通过对抗性遮盖来鼓励. 我们还在相互信息分析和Lipschitz-光谱规范界限的支持下,为相位干预的可控性提供了理论保障。 对四套广泛使用的基准工业数据集进行的广泛实验表明,AFM-CIR一贯实现最先进的性能、优于强有力的机构风险管理、一般总干事和特定任务的总干事基线。",
