    "direction": "人工智能",
    "summary": "最近广泛探索了3D检测领域改造. 前作主要使用无监督域适应(UDA)来解决域差异. 尽管取得了显著的改进,但由于传感器不同和不断变化的环境造成更大的域间隙,它们的性能在很大程度上仍然跟随了经过充分说明目标数据培训的模型。 在本文中,我们探索了自主驱动情景的关键特征,包括相似场景和类平衡分布,并探索了名为活动域适应(ADA)的新任务,用于3D对象检测,该任务选择部分但重要的目标数据进行注释,以进一步提高目标域的性能. 这种设置更好地反映了实践中的实际部署,即对所有目标域点云的注释过于昂贵,而有限的标签可有效地指导适应工作。 为此,我们提出混合双域积极学习策略Bi3D++,从源域和目标域中抽取有价值的数据,并将源域知识转移至目标域.Bi3D++ 通过测量域之间的场景级和实例级相似性,避免不相关的源数据的干扰,首先样本目标类源数据. 然后,混合活性目标采样策略通过联合考虑稀有类相似性,框架内多样性,以及框架间多样性来选择目标数据,使得有不同情况的各种框架能够同时强调稀有类. 关于多个跨域设置的实验,包括跨波束和跨位置的实验显示,Bi3D++优于最先进的UDA方法,只有1%的标注目标数据,并随着目标说明的增加而不断提高性能.",
