    "direction": "人工智能",
    "summary": "本文提出ABIGX(Aversarial floor reconstruction-Based Integrated Gradument eXplaination),为可解释的断层检测和分类(FDC)的统一框架.ABIGX基于既定断层诊断方法的基本原则,包括贡献地块(CP)和基于重建的贡献(RBC),同时将其应用范围扩大到一般的FDC模型并改进断层解释结果.ABIGX的中心是逆差断层重建(AFR)方法,它从对抗攻击的角度重新思考断层重建,引入了适用于断层探测和分类任务的新故障指数. 在断层检测中,我们通过证明CP和RBC是ABIGX的线性规格,在理论上将ABIGX与常规断层诊断方法连接起来. 关于过失分类,我们处理过失分类的挑战,这是一个固有问题,可以模糊准确的解释。 我们表明,ABIGX有效缓解了这一问题,比目前基于梯度的解释方法表现得更好。 这些实验通过定量度量和直观的插图来评价FDC的解释.调查结果证实了AFR的笼统性和准确性,并表明ABIGX在各种FDC模型中提供了更加全面和准确的解释,与现有方法相比,提供了重大的改进。",
