    "direction": "人工智能",
    "summary": "对行人运动的准确预测对自主驾驶至关重要,特别是在路径规划和避免碰撞应用方面。 目前大多数方法都集中在从历史轨迹中提取的spatiotemporal特征参数(如速度连续性,社会力参数,和姿势)上,以模拟行人运动. 然而,这些方法未能充分捕捉行人的意图,也没有动态地说明行为异质性,导致与现实世界观测的重大差异. 为了解决这一问题,提出了动态行人意向理解(DPIU)框架,将未来意向与历史经验联系起来。DPIU框架基于源于人类生理的认知决策机制,目的是通过推断内在的运动意图来预测行人的运动. 为了确立一个全面的历史视角,采用了一个多尺度详细特征模块,其中包含一个基于时间尺度的轨迹划分战略,以加强行人国的代表性。 随后,采用了一个目标意图预测模块,使用概率模型来估计行人对预定目标空间范围的倾向。 本单元评估了当前场景与历史经验的相似性,从而优化了对时间断裂信息的利用. 最后,开发了一个动态优化模块,该模块叠加意向点概率,并采用基于贝叶斯语的密度估计方法,以确保预测结果与现实世界的行为紧密一致. 对斯坦福无人机(SDD)、ETH-UCY和AporoScape数据集的实验评价表明,拟议的DPIU框架在预测未来轨迹和优化多式联运预测结果方面比现有方法要好。这种方法大大提高了动态情景中的预测性能,为自主驱动应用提供了宝贵的工具.",
