    "direction": "人工智能",
    "summary": "气象雷达反射图像在可靠的天气监测和预报中发挥着关键作用. 然而,诸如地面混凝土、海上混凝土和电磁干扰等内在因素经常将非降水回声带入这些数据,对准确探测降水构成重大挑战。 一个有希望的解决办法是利用深层学习网络利用卫星观测来识别和清除国家设备。 为了提高这些模型的实用性,最近重新参数化技术的进步显示出减少计算复杂性的潜力。 然而,现有的方法侧重于平行的多分支再平衡;将多个转录融合成单一等效的转录,称为多分支再平衡,目前仍未探索. 在这项研究中,我们提议建立一个新型的重新参数化的NPE清除网络(RepNPE-Net),目的是利用地球静止气象卫星的多通道亮度温度观测,识别和去除雷达反射数据的NPE.重制的NPE移除网络(RepNPE)-Net包含两个创新的双流分流结构模块,包括重制的双流分流模块(RepDCM)和重制的注意力双流分流模块(RepADCM),它们将标准与深度分化(DS)剩余分流块协同起来,以提高特征提取和表达能力. 在RepADCM模块内,设计了一个定位高效的局部关注(PELA)块,以使网络能够专注于空间显著的位置特征,并提高模型的准确性. 此外,为了增强拟议的RepNPE-Net的实际应用能力,我们引入了混合转录重聚技术(HCR),将多分支和多转录操作(如深度(DW)和点性(PW)在推论阶段的转录)整合为单一等效的转录,在不损害网络性能的前提下,大大减少了计算的复杂性.实验结果表明,RepNPE-Net在除去NPE的准确性和计算效率方面都超过了现有方法,突出了其提高雷达数据质量和推进气象研究和应用的潜力。",
