    "direction": "人工智能",
    "summary": "强力的深假探测模型必须能够概括到超越训练数据而不断演变的操纵技术.一项有希望的战略是,通过在线合成的、包含广泛通用的文物的假图像来增加培训数据。 然而,在深假检测方面,令人惊讶的是,关于原始和在线合成伪造品的联合培训可能导致性能退化。 这与下述共同看法相矛盾:纳入更多的源域数据应可提高检测的准确性。 通过经验分析,我们追踪到这种退化在反向传播过程中的梯度冲突,这迫使源域精确度与目标域通化之间作出权衡。 为了克服这一问题,我们提议建立一个冲突后应对的深假探测(CS-DFD)框架,通过两个协同模块明确缓解梯度冲突。 首先,一个更新矢量搜索(UVS)模块在初始梯度矢量附近搜索一个替代更新矢量,以调和原始和在线合成的伪造物的差异. 通过进一步将搜索过程转化为极端优化问题,UVS产生独特的更新矢量,最大限度地减少每个数据类型的同时损失。 第二,一个减少冲突梯度模块通过一个新的 \" 冲突导致的损失 \" 执行一个嵌入空间的低冲突特征。 这一损失惩罚了错位梯度方向,并指导了用一致的、非冲突的梯度来学习表示。UVS和CGR的协同作用减轻了参数优化和表现学习中的梯度干扰. 对多个深假基准的实验表明,CS-DFD在域内检测精度和跨域通用方面都实现了最先进的性能.",
