    "summary": "联邦在低地球轨道卫星星座上的学习面临一个基本的安全挑战。卫星间断的可见度导致标准客户日程安排方法系统地排除某些地理区域,产生零召回的地面站,使整个人口对安全关键事件探测看不见。这项工作表明,现有排程器,包括随机选择、基于损失的优先顺序安排,以及最大可见度和地域多样性等操作弹性,在现实的轨道动态下经常产生这种灾难性故障模式,但当只报告汇总度量时,故障仍然隐蔽。标准评价完全依靠总的衡量标准,如平均测试准确度和趋同速度,掩盖了按节点安全衡量标准分类的灾难性局部故障。 为了大幅度降低这一故障,采用了一个名为Graph Centric Protect Scheduling(GCPS)的图谱调度框架.GCPS通过联合优化对费德勒向量的贡献和节点度之间的核心,参与多样性,eigenvector,通过仅通过验证的多武装强盗探索七个帕雷托最佳重量配置,来保持训练子图的代数互联互通.中央调查结果确定,GCPS将5次试验中的零召回节点大幅降低到0次(0%),而5次试验中的5次(100%)用于地域多样性安排,5次试验中的2次(40%)用于最先进的公平方法,即不可知联邦学习(AFL)和q公平联邦学习(q-FFL)。 这一重大改进与九种基准方法中的任何一种方法都无法相匹配,而GCPS也大大减少了假负率(美元和lt;0.01美元相对于地域多样性,图加权抽样,q-FFL,AFL,和Oort),保持了竞争性的标准准确性,并显示出地形不匹配、差异性隐私噪声和标签翻转攻击的强烈性。 除了具体的卫星领域外,这项工作认为,每个节点的最低限度性能保障必须成为安全关键FL的主要评价标准,因为总的测量值掩盖了灾难性的局部故障,图谱表表具有独特的位置来防止这种故障。事实还表明,常用的公平指数,Jain QQ8217;所有方法的指数超过0.98,衡量参与公平而不是业绩公平,因此未能发现零召回失败,这是安全关键部署的关键区别。",
