    "summary": "这项工作解决了在矢量数据库中混合搜索的问题,该数据库将矢量与一些属性一起存储. 鉴于一个包含向量的查询以及对其属性的一些限制,我们希望为查询获取近似邻向量,同时确保符合上游条件,例如特定向量属性属性上的点或范围过滤器.这一挑战由于需要平衡两个相互竞争的要求而变得更加复杂:一方面,通过利用一个独立于具体属性的基于相似性的指数来确保矢量搜索的高准确性,使其能为所有查询服务;另一方面,为每个属性或上游条件复制这样一个结构是不切实际的。 为了应付这些挑战,我们建议在近距离邻(ANN)搜索中,利用基于图表的向量索引结构的效率,为上游过滤提供一个不可知的、属性化的受欢迎度认识解决方案。 我们的方法首先在基础图结构内将节点集群,并为上游构筑轻量级的模拟草图. 在查询处理过程中,搜索仅在必要的时候才有选择地采用双跳转盘策略,以被识别的集群内属性的受欢迎度为指导.5个基准数据集的实验评价表明,我们的做法一贯优于最新方法。",
