    "direction": "人工智能",
    "summary": "我们介绍了AI Harmonics(AIH),这是一种新颖的衡量标准,旨在量化受AI系统影响的利益攸关方群体的危害集中程度.与依赖任意数字分配到正数严重性水平的传统方法不同,AIH提供了一个基于不平等理论的原则框架,将概念从基尼指数扩展到纯粹的正数数据. 该衡量尺度评估了损害如何在利益攸关方之间分配,并了解了严重影响是集中在特定群体中还是分布更为均匀。 对附加说明的事件数据的实验表明,拟议的衡量尺度显示出与临界指数(CI)的强烈单调关系,保持了危害类别排名,同时捕捉了浓度模式的其他变化。 该方法表现出高度稳健性,斯皮尔曼在重度扰动下排在0.97以上,稳定优先级甚至不到80%的随机数据清除.政治和身体伤害始终是集中程度最高的,这表明需要紧急缓解。政治伤害侵蚀了公众的信任,而身体伤害则构成严重、甚至危及生命的风险,突出了我们的做法与现实世界的相关性。AIH衡量标准特别适合决策和风险管理,因为只有普通评估,因此能够更知情地确定缓解战略的优先次序。",
