    "direction": "人工智能",
    "summary": "在模型选择过程中过度依赖验证性能可能导致验证过度适应(VO),其中模型在开发过程中显得有效,但在测试时失败.这个问题在低数据制度和分布转移中进一步扩大,验证信号变得不可靠。 虽然综艺学习被广泛用于提高稳健性和通俗性,但大多数综艺建筑管线严重依赖验证分数,使其易受VO的影响,并限制了其在现实世界部署情景中的可靠性. 为了解决这个问题,我们提出基因网络eXperts(GeNEXs),这个框架减轻了模型生成和综艺建设阶段的验证过度适应. 在生成阶段,GeneX采用双向策略:梯度式训练与遗传模型演化相结合.泉外网络是通过训练有素的父母的交叉而创建的,促进结构多样性和重量级再生而无需依赖验证反馈. 这就产生了一批坚固、不适应的候选模式。 在综艺建设期间,候选网络通过预测行为集群,以识别互补的模型空间. 在每一组中,采用稳健性和代表性等标准挑选多种不同的专家,并在重量一级加以融合,形成紧凑的原型网络。最终的综艺集成这些原型,通过顺序四极编程(SQP)优化预测,实现输出级协同. 为了严格评价VO的复原力,我们采用了VO-感知评价协议,通过强制执行培训与测试子集之间的分布差异,模拟现实的部署情景. 关于四个真实世界影像分类任务的实验(皮肤癌,深假检测,植物疾病,肺炎)表明,GENEX在有限数据和转向感知条件下持续超越最先进的综艺,以最小VO差距实现强通化.",
