    "direction": "人工智能",
    "summary": "部分标签学习(PLL)研究的分类有模棱两可的监督,其中每个实例都由包含未知真实标签的候选标签集附加注释. 虽然PLL已经被广泛调查,但现实世界的注解管道往往提供比无序集更丰富的结构:注解者或检索系统可能暗中给候选人排位,产生更可能正确的首选标签,错误的选取模式可以依赖阶级而非统一. 此外,实用的候选套件有时可能因人为错误或上游模型不完善而错过真实的标签. 在这些意见的推动下,我们提出了一个新的弱监督范式,在一V全景(PLL-OVA)中首选的标签PLL,在每个培训场景中,都配有一组候选人和一组中首选的标签. 我们通过一种灵活的、包含对称和不对称误选机制的噪声通道来模拟首选标签的生成,我们进一步纳入了缺失的真实标签方案,以更好地反映现实的注释噪声。 基于这一提法,我们通过风险重写制定原则性的经验风险最小化程序,在一般渠道下确定可识别性要求,并得出以统计为基础的实际学习目标。 为了在无偏见重写所固有的负风险效应下改善优化稳定性,我们引入了风险校正功能(如纠正线性单位(ReLU)/绝对值校正功能(ABS)类型校正),显著增强稳健性和经验性能.有关基准数据集的广泛实验表明,PLL-OVA在标准PLL基线上不断改进,特别是在候选人模糊度大或选错时不统一,验证了拟议框架的有效性和实用性.",
