    "summary": "在跨公司语音情感识别(SER)任务中,虽然基因方法在缓解目标域标本的稀缺性方面显示出一定的潜力,但生成的标本往往与目标域的声学特征缺乏精确的配合. 这导致质量不均匀的假样,甚至引入噪音,从而削弱了转移学习的有效性. 为了解决现有方法中伪样品质量控制不足的问题,我们提议采用动态过滤多阶段扩散模型(DFMDM)。拟议的DFMDM模型建立了一个“Generation – Filtering–Enhanment”的三阶段迭代优化过程。 在第一阶段,有条件的传播模型以对抗性域分类器为指导,生成具有目标域特性的伪样本。 在第二阶段,提出了动态滤波模块,以消除明显偏离目标域特征的低质量伪标本. 在第三阶段,被过滤的伪标本与源域标本混合,再利用以再生目标式伪标本. 这样,就构建了一个渐进的基于扩散的增强循环,通过迭代生成和动态调整相似性阈值来提高样本质量. 关于CASIA、EmoDB、eNTERFACE和IEMOCAP的实验结果显示,拟议的DFMDM模型比现有的先进技术(SOTA)方法有了显著的改进,充分显示了其在跨公司的语音情感识别方面的应用潜力和实际价值。",
