    "summary": "联邦学习使协作模式培训得以进行,同时保持数据隐私,但集中和分散的方法在可扩展性、安全性和更新验证方面都面临挑战。 我们提出ZK-HybridFL,这是一个安全的分散式FL框架,将定向的循环图分类账与专用侧链和零知识证明(ZKPs)相结合,用于隐私保存模型的验证.该框架使用事件驱动的智能合同(EDSC)和一个甲骨文辅助的侧链,在不暴露敏感数据的情况下验证本地模型更新.内置挑战机制高效检测对抗行为. 在图像分类和语言建模任务的实验中,ZK-HybridFL比Blade-FL和ChainFL实现更快的趋同,更高的精度,更低的迷惑度,并降低耐久性. 它对大量敌对和闲置的节点保持强大,支持用高效的天然气进行二级链上核查,并防止无效更新和孤儿院式攻击。这使得ZK-HybridFL成为不同环境中分散的FL的可伸缩和安全的解决方案.",
