    "link": "https://doi.org/10.1016/j.neunet.2026.108949",
    "direction": "人工智能",
    "summary": "由于产品类别在现实世界工业环境中不断演变的性质,逐步发现异常现象已变得十分重要。 然而,现有的内审司方法通常依赖于一个共享的模型参数空间,在引入新的类别时,这个参数空间容易被灾难性地遗忘。 为了从根本上解决这一问题,本文提出了动态可扩展框架(DEF),这是一个新颖的架构,旨在实现明确的阶级间脱钩和参数隔离. 该方法融合了三个关键组成部分:1)历史加权特征选择(HWFS),选择具有代表性的反常敏感通道来缓解特征冲突;2)一个分类专家混合层(CS-MoE),该层为每类指定专用参数,以防止知识覆写;3)动态对比运行网络(DCRN),在推论期间能够准确选择专家. 此外,T-SNE可视化结果在质量上验证了拟议的脱钩机制的有效性,表明DEF大大缓解了脱钩层内部的阶级间干扰. 关于MVTec-AD和VisA基准的广泛实验表明,DEF达到了最先进的(SOTA)性能.具体来说,在MVTec\"3-3带4个步骤\"设置中,DEF将平均精确度(ACC)提高4.8%,与目前的领先方法相比,将忘却措施(FM)降低2.15. 我们的方法还保持了较高的计算效率,只需要3.52G FLOP和4400MB的训练记忆,为现实世界的工业部署提供了最佳的平衡.",
