    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tnnls.2026.3661083",
    "direction": "人工智能",
    "summary": "船舶在合成孔径雷达(SAR)图像中的自动目标识别(ATR)在海事领域意识中发挥着至关重要的作用. 然而,海扰干扰可能使模型无法专注于信息化的船舶目标区域以获得认可。 所有现有的SAR飞船ATR型号都使用整个SAR飞船图像作为输入. 但搜索和救援舰船图象中的并非所有区域都为识别做出了积极贡献。 然而,班级内的多样性和班级间的相似性使搜索救援船ATR任务更具挑战性. 在这项研究中,我们提出一个基于变压器的新建筑,以解决两个核心挑战,命名为前信息符号选择(ITS-ShipFormer).ITS-ShipFormer选择并引导该模型关注该船目标区域的信息符号.ITS-ShipFormer由早期的多头动态局部电流(MHDLC)区块,后期装有海聚压制舱(SCSM)的变压器区块,以及区别性杂交损失.SCSM通过两个精心设计的策略,自动区分了信息化的船舶代币和无用的海杂代币.为应对另一个挑战,MHDLC旨在增强特征提取能力,并提议混合式歧视损失,以同时增加CLS令牌和信息令牌的限制. 关于基准数据集的实验结果 OpenSARShip 和 FUSAR-Ship 联合验证了我们设计的有效性.与以前在ITS-ShipFormer中引入变压器结构的工程不同,它利用变压器结构被忽略的内在和独特的优势来应对我们的挑战.",
