    "summary": "多视图分组(MvC)旨在整合来自不同观点的信息,以增强模型捕捉基础数据结构的能力.MvC中广泛使用的联合培训范式可能无法充分利用多视图信息,因为所有视图的统一学习目标导致的视图特性不平衡且不尽人意. 例如,在联合培训模式中,带有更多歧视性信息的特定观点可能支配学习过程,导致其他观点不够理想。 为了缓解这个问题,我们首先分析联合培训范式中的不平衡现象,即从每个特定视图特征提取器的梯度下降角度,将多视图组合在一起。 然后,我们提出一种新颖的平衡多视图群集法(BMvC),它引入了针对特定视图的对比性规范化(VCR)来调制每个视图的优化.具体来说,VCR保留了从联合特征和视图特异性特征中捕获到的样本相似性,与视图特异性特征相对应的集群分布,以加强视图特异性特征提取器的学习过程. 此外,还提供了一项分析,以说明VCR可适应性地调整梯度的大小,以更新视图特定特征提取器的参数,从而实现平衡的多视图学习程序。 通过这种方式,BMvC在利用视点特异性模式与探索视点偏差模式之间实现了更好的权衡,以充分学习集群任务的多视角信息. 最后,还进行了一系列实验,以核实拟议方法与8个基准的MvC数据集和2个空间解析的转录组数据集的先进方法相比的优越性。",
