    "direction": "人工智能",
    "summary": "在3D视觉和计算机图形中,密集的重建和不同的渲染是基本紧密相连的操作.最近的神经隐含表达表明,在重建忠贞性和差异性方面,与传统离散表达(如网状、点云和花瓶)相比,具有令人信服的优势。 然而,许多神经内含模型,如神经辐射场(NERF)和签名的距离函数(SDF)网络,由于需要沿着每个相机射线进行多个查询,因此渲染效率低下. 此外,NERF和高斯镀层方法提供了令人印象深刻的光度重建,但往往需要认真监督,以实现准确的几何重建.为应对这些挑战,我们提议采用名为签名方向距离函数(SDDF)的新表述.与SDF和NERF相似,SDF有一个位置,视方向为输入.与SDF和NERF不同,SDF直接提供到观测到的表面的距离,而不是沿视线融合. 因此,SDDF实现了准确的几何重建以及高效的可变方向距离预测. 为了有效地学习和预测场景级SDDF,我们开发了一种不同的混合代表,结合了显性椭圆前身和隐性神经残基.这使得模型能够有效处理障碍边界周围的距离不连续现象,同时保持密度高的真伪距离预测能力. 通过对照最先进的表示进行广泛的评价,我们显示SDDF实现了(一)竞争性的SDDF预测精度,(二)比SDF和NERF更快的预测速度,(三)与NeRF和高斯白板相比,具有更高的几何一致性.",
