    "direction": "信息安全",
    "summary": "隐私保存神经网络(PPNN)利用安全多方计算(MPC)等密码技术,在保持数据保密性的同时,进行协作模型培训. 然而,PPNN并不涉及数据内容安全,使其容易受到后门攻击,恶意制作的数据样本引入了操纵模型行为的触发器.现有的后门防御机制通常依赖于基于计算密集梯度的优化或要求高计算精度,使其在MPC背景下不切实际. 为了应对这些挑战,我们为PPNN提出一个新的后门防御机制,称为CIPHERBD.CIPHERBD不依靠计算密集的梯度优化和模型再培训,而是利用私人最大操作和适用于小子类后门样本的低成本添加来重建后门触发器. 为了减轻在通过样本级特征差异分析识别后门样本时对高精度计算法的依赖,我们提出了像素独立触发近似法. 这一技术旨在重建一个近似触发器,而不是由对手嵌入的原始触发器。 为了提高确认后门存在的效率,我们采用了特征强度测试,减少了检测所需的私人推论查询数量. 这种优化降低了计算的复杂性,从四进制到与类数相关的线性,从而在多类设置中提高了可扩展性. 此外,我们优化了触发近似方法的核心运作,引入了安全最大/最低计算的新范式。与传统模式相比,这种做法减少了外部安全通信的约46%。 我们利用三个不同的神经网络架构和三个基准数据集来评价CIPHERBD,以证明它相对于三个突出的后门攻击策略的有效性.",
