    "direction": "数据工程",
    "summary": "在高维Euclidean空间中近邻(ANN)近邻搜索是各种数据科学和AI应用中的一个关键问题. 在处理大规模数据时,传统的内存ANN方法的性能由于主内存的大幅扩张而急剧下降. 最近,磁盘居民ANN方法引起了相当的注意,使得ANN能够进行大规模搜索. 然而,尽管情况有显著改善,但由于一/O费用高昂,他们仍然处于高查询延迟状态。 在本文中,我们提出ANN-CACHE,这是一个I/O高效缓存-意识的ANN框架,它利用skew在查询工作量中的杠杆作用来降低I/O成本. 据我们所知,我们是第一个正式研究 探索缓存的人,以加速基于磁盘的ANN搜索。ANN-CACHE由两个部分组成:(一)一个歧视者,检查一个查询的ANN点是否被缓存. 如果是的话,会触发缓存中的内存查询;否则,会在磁盘-居民索引中进行查询;以及 (二)基于LSH的缓存存储历史查询及其结果,以支持高效的ANN搜索.考虑查询 q,如果缓存中包含类似于q及其ANN的历史查询,我们可以在不访问磁盘-居民索引的情况下从这些查询的结果中获取q的结果.实验结果表明,通过在10M大小的数据集上引入不到50 MB的额外内存管理费,我们的框架实现了3×-9×的加速,同时保持了与基线一致的更高的准确性。",
