    "summary": "本文调查了AI驱动的反馈中毒攻击下网络化工业系统的弹性安全控制. 这种攻击利用反馈渠道和时间规律来降低闭路性能,同时仍然难以发现。数据驱动的中毒模型以现实世界的WWAT数据集为基础构建,能够模拟超出理想化假设的对抗性反馈操纵.采用了一种承认(ACK)捆绑机制,通过将ACK汇总在一个可捕捉的时间窗口内来规范反馈传输.捆绑窗口Tb通过梯度降级(GD)进行适应性调整,有利于在对抗环境中在控制性能和通信效率之间实现灵活权衡。 此外,还开发了轻量级的Lyapunov Krasovskii功能(LKF),以便在存在通信延迟和有毒反馈的情况下建立闭环稳定性.网络无人驾驶水面飞行器平台的模拟结果显示,在有限的通信条件下,跟踪性能和抵御反馈中毒的能力都有所提高。 这些结果表明,拟议的框架为安全联网的工业控制提供了切实和有效的解决办法。",
