    "summary": "先进的持续威胁(APT)和零天攻击逃避了由签名驱动和充分监督的入侵探测,促使开发异常探测器,将其普遍化为看不见的行为,同时在高吸积操作中仍可解释。现有的时间图神经网络(GNN)探测器往往依赖于重建目标,并且提供有限的透明度,这可以削弱新威胁的分离性,降低分析师的信任度. 我们提出CTGAD-X,一个可解释的自我监督的框架,用于在时间图上检测零天的威胁.CTGAD-X从良性交通中学习出一种歧视性的普通嵌入空间,使用基于距离偏差的基于普通参考集的对比性学习和旗帜异常. 为确保时间正确,我们针对原始的PCAP数据包时间戳引入了因果认识重叠的流切分和经验证的窗口级归属,达成了强烈的一致(Pearson$r=0.943美元;字节的相对误差中位数为3.2%,包的相对误差为2.0%)。 在UNSW-NB15中,CTGAD-X在因果感知切片下实现ROC-AUC$=0.9908美元和F1-分数=0.9888美元。 在零天休假一号评估中,在可部署的低假警报(固定门槛)中,被搁置的爆炸从大约88.8美元增加到100美元,以更高的敏感性。 同样,Generic也从65.5美元增加到100.为支持业务透明度,CTGAD-X集成了一个多层次的XAI模块(意向归属,输入扰动,以及全球振动的重要性),并通过特性成像和扰动测试验证解释. 我们进一步评估了多个基准数据集的跨数据集通用情况,利用的是一种转让学习,但适应程度极低。CTGAD-X为轻量级(16,320个参数),并实现每个序列的3.94ms编码器推论,使得能在高通量环境下实际部署. 最后,CTGAD-X统一了时间上一致的图表构造,对比性表现学习,以及可靠的解释,以便可以进行可靠的零天检测.",
