    "summary": "人群计数是计算机视觉中一个重要的研究领域,在确保拥挤环境中的公共安全方面发挥着至关重要的作用. 尽管研究取得了显著进展,但由于严重隔离、大规模差异和在密集场景中个人重叠,准确的人群计数仍然具有挑战性。本文提议建立一个新型的多尺度金字塔聚变与重叠密度关注网络(MSPF)来应对这些挑战。拟议的框架包括三个专门模块:一个多尺度金字塔聚变模块,一个重叠密度关注模块,以及一个特征浓缩模块. 这些组件协同增强模型处理重叠个体和在高密度人群场景中尺度变化的能力.最初,编码器的提取物以多个可接受字段大小的特性表示. 然后,重叠密度关注模块通过有选择地注重信息特征,强调重叠和非重叠区域。 随后,金字塔聚变模块适应性地融合了多尺度特征,而特征浓缩模块则进一步完善了最相关的空间信息. 最后,网络生成一个准确的密度图,用于人群估计. 对拟议的高包集数据集和四个具有挑战性的基准数据集进行的广泛实验表明,与最先进的方法相比,MSPF在准确性、稳健性和效率方面表现优异。",
