    "direction": "信息安全",
    "summary": "使用平等测试(IBEET)的基于身份的加密扩展了基于身份的加密,以支持信息在与不同身份相关的两个截然不同的密码文本中的比较. 尽管如此,几乎所有之前的IBEET计划都存在这样的问题:一旦陷阱门被送到云端服务器,它就会变得无法控制. 同时,解决这一问题的唯一现行IBEET计划,即IBEET基于日期戳的授权(IBEET-DBA)存在以下缺陷。(1) 陷阱门仅表示单一的时间间隔,该时间间隔是无法表达的。(2) 之所以不灵活,是因为只支持有限类型的授权。(3) 随机甲骨文模型只是证明它是安全的,它已经指出,它可能在实际操作上造成安全风险。 考虑到上述问题,我们提议建立一个具有灵活时间授权(IBEET-FTBA)计划的IBEET,支持通配符,并对授权类型不设任何限制. 我们证明我们的计划是安全的 在标准模型的适应性 选择密码攻击。 随后,我们详细分析了IBEET-FTBA的构造和现存的主要IBEET. 此外,我们实施我们的和IBEET-DBA建筑作为基准,并进行许多实验。这两项结果都表明,我们在多个时间间隔的假设中表现较好。",
