    "summary": "为了获得医疗旅游最合适的推荐服务,患者通常会向服务供应商提交病历,服务供应商进行类似的计算,以推荐定制的医疗旅游选项. 为了保持数据隐私,患者应当上传加密的病历,使服务提供者能够在密码文本上进行相似性的计算. 然而,医疗记录一般是高维的和稀少的,使加密的相似性计算效率降低,准确性降低. 在本文中,我们提出一个保护隐私的个性化医疗旅游推荐服务,命名为P3RS-MT. 拟议办法采用加权的田本系数(WCC),以便进行高效和准确的相似性计算,同时采用某种同质的加密(SHE),以保护医疗记录不接触服务提供者。 由于SHE并不在本土上支持对WTC的要求的分区操作——我们用牛顿的迭代近似方法来解决这个限制.理论分析和实验性评价显示,P3RS-MT是安全的,准确和高效的.",
