    "direction": "信息安全",
    "summary": "车辆边际计算(VEC)能够提供车辆服务,但仍难以在高度动态和资源紧张的条件下实现安全而高效的任务卸载。 为了解决这个问题,我们开发了一个安全的任务卸载框架,任务车辆(电视)在窃听车辆试图截获敏感数据的同时,确定卸载决定。联合优化卸载比,频谱分配,以及传输功率,被建模为合作的多代理马可夫决策流程(MDP),能捕捉到移动驱动的通道变异和资源竞争. 然后,我们设计了一个基于“深度决定性政策梯度”的安全任务卸载(DSTO)计划,以解决这一持续控制问题。DSTO将车辆状态编码为紧凑的表达方式,并使用演员-批评(AC)架构来学习适应性策略.角色输出持续卸载和动力控制动作,而批评者则在综合安全,延迟和能量限制下评价长期效用.安全是通过安全率明确纳入的,反映了合法链接相对于窃听链接的优势.利用DDPG在高维连续空间的能力,DSTO强力适应动态车辆条件,平衡安全与系统性能.广泛的实验表明,DSTO大大减少了任务拖延和能源消耗,与基线方法相比,综合效用提高了12.7%。",
