    "title": "Randomization Mechanism Based on Elliptical Distributions for Location Privacy in Geo-Indistinguishability",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Dependable and Secure Computing",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "partial",
    "contentNote": "已完成本地开源模型英译中，六段式其余部分待人工全文核验",
    "doi": "10.1109/tdsc.2026.3698496",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tdsc.2026.3698496",
    "direction": "信息安全",
    "summary": "Geo-indistinguishable(GI)作为位置隐私的正式概念,通过使用随机噪声扰动用户的准确位置来实现. 对于对位置敏感的情景,例如本地化和导航,采用随机噪声会减少数据效用。 在本文中,我们调查了替代的随机化机制,这些机制可以提供比常用的Planar Laplacian机制更高的数据效用,同时保持相同的隐私性能.具体地说,我们调查了利用椭圆分布来增加数据效用的情况. 首先,我们得出两个充分而必要的条件,以确定随机化机制是否满足GI.利用这些条件,我们验证椭圆形分布对于实现GI的可行性,并发现除了Planar Laplacian,学生的美元分配也可以满足GI. 第二,我们将学生的美元分配纳入随机化机制,以实现GI,并在隐私水平和数据效用方面量化其性能. 为了在实际应用中优化学生美元分配的数据效用和隐私水平,我们提出了两个优化问题:一个是在一定的隐私水平下实现数据效用最大化,另一个是在数据效用的制约下实现隐私保障最大化. 在两个典型的基于位置的应用中进行了广泛的实验,包括基于指纹的室内局部化和基于位置的广告.理论分析和实验结果都评价了学生美元分配的性能,并通过比较学生美元机制与拉普拉西安机制,提供了对不同情景下随机化机制选择的洞察力.",
