    "direction": "数据工程",
    "summary": "合作子图的开采得到了广泛的研究,并发现了许多图解开采应用,如链接农场识别、社区检测和产品推荐。 在各种具有凝聚力的子图结构中,以三角形为基础的强大的结构凝聚力特别突出。 然而,古典的$k$-trius问题旨在找到拥有最大数量顶点的$k$-trius,这在实践中常常是极其庞大和复杂的. 为了充分利用美元三角洲的好处,我们认为一个叫做最低美元三角洲问题的新问题,它试图用最低的圆顶数确定一个美元三角洲,其中2美元是正整数。 我们首先正式证明问题不难解决。 然后我们设计一个基于顶点计数的基线算法MTEnum 和一个计算上限的热力学方法。 尽管做出了这些努力,MTEnum仍然面临着实际的效率问题,这可能是由于美元-特鲁斯缺乏世袭财产。 为了解决这一问题,我们开发了一个新的以分解为基础的框架DSA,它把问题巧妙地转变为一系列问题,这些问题都基于一种新的、具有凝聚力的子图模型,称为“以美元为单位的复杂美元”($-eplex)。 由于世袭财产为$-eplex,我们设计了一个分公司和捆绑的算法,为新制定的问题设计了几种定制技术。广泛的实验证明了我们所研究的问题的有效性以及我们提议的算法DSA的效率.特别是,DSA跑得比基线MTEnum快达5个数量级.",
