    "direction": "信息安全",
    "summary": "移动云计算(MCC)通过利用多种网络和坚固的云服务器,优化了资源有限的移动设备的存储和计算. 然而,将本地数据外包到云端服务器也可能是恶意的,这也引起了对数据隐私的担忧. 作为获取外包数据的突出解决方案,服务器辅助的可撤销属性基于加密(SR-ABE)在支持轻量级用户吊销的同时,对加密数据实施精细的访问控制. 然而,由于以下原因,现有的SR-ABE计划实际上在挣扎。 首先,他们依赖一个完全信任的密钥生成中心来管理属性,并发布长期的转换和解密密钥. 第二,它们要求设置固定数量的数据用户,而忽略了属性撤销。 第三,它们包含基于时间的撤销机制,假设在基础网络中同步,但在实践中并不总是如此。本文为MCC提出了一个安全和实用的SR-ABE计划,支持分散生成长期用户密钥,同时整合国家触发的用户和属性撤销机制.拟议的SR-ABE计划可以容纳无限数据用户,通过懒惰的撤销将密钥和密码文本更新的大小最小化,并确保可核查的外包解密. 我们正式证明,拟议的SR-ABE计划是适应性安全的,并进行了广泛的实验来证明它的实用性.",
