    "link": "https://doi.org/10.1016/j.neunet.2026.108908",
    "direction": "人工智能",
    "summary": "可变形的医疗图像登记对于纵向诊断、外科手术规划和定量解剖分析至关重要,然而,实现准确和有力的对齐仍然具有挑战性。传统的基于优化的方法在计算上是密集的,对参数设置高度敏感.相比之下,最近许多深入的学习方法未能有效捕捉不同解剖结构之间的空间对应,与多尺度特征聚变进行斗争,缺乏可解释性. 为了解决这些问题,我们提议采用分级交叉式登记法(HCA-Morph),这是一种新型的无监督登记框架,明确模拟空间对齐,并适应性地融入分级特征。HCA-Morph由两个专门模块组成:空间通信-软件模块(SCAM),该模块学习从局部到全球的移动图像和固定图像之间的可解释空间对接,以及跨规模的注意模块(CSAM),该模块动态地将多层次特征与内在可解释性结合,以提高代表性一致性。 在两个公共脑磁共振数据集上的实验——图像研究的开放存取系列(OASIS)和图像的信息电磁学(IXI)——证明HCA-Morph在OASIS和IXI数据集上分别取得了0.845和0.834的Dice分数,优于目前最先进的模型,同时也取得了更好的HD95分数(OASIS为1.365分,IX为1.725分).值得注意的是,只有2.05 MB参数 -- -- 在所有比较方法中最小 -- -- HCA-Morph的精确度是可比的或优越的,同时保持了最低的内存消耗(OASIS的4.08 GB,九一的9.02 GB),并产生更合理的变形场,折叠区域较少(XQ J ≤ 0|:OASIS的1.77 × 10− 4,九十一的5.39 × 10− 6)。对比研究证实,SCAM和CSAM为OASIS提供了补充性贡献,将协同效应结合起来,使总的改进达到0.030.便携性实验进一步表明,这两个模块可以成功融入包括CNN, Transformer,以及基于曼巴的模型在内的多种现有架构,在不同骨干之间实现一致的性能改进.总体来说,HCA-Morph在精度,效率,解剖学上对可变形脑核磁共振登记有很强的平衡.源代码和预先培训过的模型可在https://github.com/importes/HCA-Morph上公开查阅。",
