    "summary": "联邦学习使各医院、临床中心和医疗器械能够开展协作模式培训,同时维护数据隐私。 然而,各种数据特征——包括阶级不平衡、说明有限和非IID分布——导致大量通信间接费用,从而限制了联邦保健系统的可扩展性和效率。为应对上述挑战,本条引入了联邦学习算法,将合成数据增强纳入联邦医疗数据集,以提高诊断准确性,减少分布式保健环境中的通信间接费用。 通过将合成数据生成嵌入FL过程,拟议的算法可以减轻数据异质性,增强模型泛化,并减少在薄弱的监管和不平衡的数据条件下趋同所需的通信回合数量. 在两个生物医学数据集——心脏疾病和糖尿病——上评价了拟议的算法,并表明在水平非IID环境下,其性能始终优于标准的FL基线。",
