    "direction": "信息安全",
    "summary": "班级不平衡是机器学习网络入侵探测系统(NIDS)面临的主要挑战之一,特别是在识别稀有但高风险的攻击类型时。传统的超采样技术,如随机超采样和SMOTE,往往会破坏数据固有的多面结构,并在阶级界限附近引入噪音,从而降低少数群体阶层的检测性能. 为了解决这一问题,本文件采用了ADEO框架——一种适应性的DBSCAN-增强的超采样方法,通过将深度强化学习与了解边界的几何模型相结合,有效地缓解了这些问题。该框架利用一个深Q-Network(DQN)自动优化DBSCAN参数,从而能够准确识别各种入侵数据集中的自然集群结构。 在这一基础上,ADEO采用诸如对流船体、最小的椭圆或轴对齐的边框等方法构建精确的类边界功能。 然后,它在这些受限的安全区域内产生样品,保留真正的地形结构,同时避免靠近决定边界的噪音。 此外,本文还引入了等级级绘图策略和针对攻击的特征工程,以提高框架对不同攻击家庭的适应性.NSL-KDD、UNSW-NB15和CICIDS2017基准数据集的实验结果显示,ADEO在精度、准确性、召回、F1分数、FPR和AUC方面都超过了主流抽样方法。 对 \" 后门 \" 和 \" 心血 \" 等极端少数群体的改善尤其显著,这证实了拟议框架在实用的NIDS应用中的有效性和效率。",
