    "direction": "人工智能",
    "summary": "定向图的链接预测是一项关键的任务,具有多种现实世界的应用。嵌入方法和图表神经网络(GNNs)的近期进展显示有希望的改进. 然而,这些方法往往缺乏对其表达方式的透彻分析,而且缺乏进行公平评价的有效基准。 在本文中,我们提出了一个统一的框架,以评估现有方法的表达性,强调双重嵌入和解码器设计对定向链接预测性能的影响. 为了解决目前基准设置的局限性,我们引入了DirLink Bench,这是一个具有全面覆盖面、标准化评价和模块扩展性的强有力的新基准。 关于DirLink Bench的结果显示,目前的方法难以实现强性能,而DiGAE的绩效总体上超过了其他基线. 我们进一步重新审视DiGAE理论,在未定向的双面图上显示其图解与GCN一致。 在这些见解的启发下,我们提出了一部小说Spectral Directed Graph Auto-Encoder SDGAE,在DirLink Bench上实现最先进的平均性能. 最后,我们分析影响直接联系预测的关键因素,并强调这一领域的公开挑战。",
