    "direction": "人工智能",
    "summary": "梯度下降(GD)的古典分析根据损失的最大基值(常称为锐度)确定了稳定性阈值。 当学习率低于这一阈值时,培训是稳定的,损失是单调的。 然而,现代深层网络往往在这一制度之外取得最佳业绩。 我们表明,这种不稳定性导致在GD中隐含的偏好,将参数推向损失地貌的优美地区,从而改进概括。关键机制是Eigenvectors(RPE)的旋转极性(RPE),这是一种几何现象,黑森人的主要hegenvectors在训练不稳定期间进行旋转. 这些轮换随着学习率的提高而增加,促进了探索,并可以证明是受宠若惊的小型轮换。 这种理论框架延伸到了有条不紊的GD,其中不稳定驱动的平整现象持续存在,其经验效应超过小批量噪音. 最后,我们表明,恢复亚当的不稳定性进一步改善了一般化。 这些成果共同确立和理解了培训不稳定性在深入学习中的建设性作用。",
