    "summary": "由于神经激活导致的功能连接(FC)异常,深入学习被广泛研究开发自闭症谱系障碍(ASD)的计算机辅助诊断方法. 然而,FC的连通性在大脑的有限区域出现,大型数据集的复杂性使得通缩性和变异性也造成了异质性的增加. 因此,分类框架的关键挑战是确定和巩固能够提升等级分离的独特特征。 为了解决这一困境,我们提议建立一个双重关注的多种精神学习框架,用于诊断自发症及其亚型。DAMILF包含四个模块: (一)识别功能磁共振成像(fMRI)中的特定区域, (二)用于提取和加强基于补丁的局部歧视性特征的补丁级关注子网络, (三)用于平衡每个补丁的相应份额和为整个大脑产生全球特征空间的注意-意识特征图, (四)用于补充性全脑全球特征学习和ASD相关标签预测的主体级子网络. 我们提议的DAMILF是根据从自闭症脑成像数据交换库(ABIDE-1)的408个自闭症和476个典型控制主体收集的大规模FMRI基线数据进行评价的,与若干最新方法相比,它表现出了更好的诊断性能和更好的概括能力。",
