    "summary": "企业面临日益复杂的钓鱼和采摘证书活动,利用基因人工智能(AI)产生符合具体情况和高度说服力的诱饵,扩大了这些活动的规模。 虽然雇员的认识和培训仍有必要,但广泛的实证证据表明,他们的保护作用不大,寿命短,而且高度依赖适合的工作流程。本文认为,可持续保护企业通信需要通过摩擦最小化、社会-技术协调将安全措施直接纳入日常工作。 我们综合了最近关于人类易感性、组织动态和攻击者战术的跨学科研究结果,我们提出了严格的、系统强化的、无密码的第一安全模式。这种方法结合了防钓多要素认证(MFA),设备验证,基于风险的连续核查,以及特定角色的赋能,辅以可衡量的关键业绩指标和分阶段实施闸门. 通过从依靠人类的警惕性转向决定性的、系统强制的控制,拟议的模式大大减少了基于证书的妥协,并为AI驱动的威胁时代的企业通信安全提供了一个具有复原力的基础。",
