    "direction": "人工智能",
    "summary": "视觉导航是自主家庭辅助机器人的基本能力,能够执行物体搜索等长视距任务. 虽然最近的方法利用了大语言模型(LLMs)来纳入常识推理和提高探索效率,但其规划过程仍然受到文字表述的制约,因为文字表述无法充分反映空间占用或场景几何关键因素,从而无法作出知情的导航决定。 在这部作品中,我们探索Visual-Langage Models(VLMs)能否仅使用机载RGB/RGB-D流实现无映射视觉导航,解锁其空间感知和规划的潜力. 我们通过开发想象力驱动的导航框架ImagineNav++来实现这一点,这个框架在宝贵的机器人视图中想象未来的观测图像,并将复杂的导航规划过程转化为一个相当简单的VLM最优的图像选择问题.具体地说,我们首先引入了一个未来展望想象模块,该模块将人类的导航偏好提炼出来,以产生具有高度勘探潜力的富有意义的候选观点。 然后,这些想象中的未来观点成为虚拟资料清单确定最翔实观点的视觉提示。 为了保持空间一致性,我们开发了一个选择性的滤泡内存机制,它通过一个稀疏至密集的框架,分层次地整合了关键框架的观测,从而构建了长期空间推理的紧凑而全面的内存. 这种综合办法有效地将挑战性的面向目标的导航问题转变为一系列可牵引的点目标导航任务. 对开放-vocabulary对象和实例导航基准的广泛实验表明,我们的ImagineNav++在无地图设定中实现了SOTA性能,甚至超过了最繁琐的基于地图的方法,揭示了场景想象力和场景记忆在基于VLM的空间推理中的重要性.",
