    "direction": "人工智能",
    "summary": "本文聚焦于被称为非平行支持矢量分类器(NPSVCs)的特定分类器群.与典型的分类法不同,核动力源价值链的培训涉及将多重目标降到最低程度,从而引起对特征不优化和阶级依赖性的潜在关切。 因此,没有制定有效的学习计划,通过代表学习,特别是深入学习,提高核动力源价值链的性能。 为了打破这一瓶颈,我们在多目标优化的基础上开发了核动力源VC++,从而能够无缝地学习核动力源VC及其特征。 通过追求Pareto优化,核动力源VC++在理论上确保不同类别之间的优化特征,从而有效地克服了上述这两个问题。提出了通过二重性优化的一般学习程序,在此基础上,我们提供了两个适用的例子,K-NPSVC++和D-NPSVC++. 此外,还提供了拟议算法的趋同分析。 这些实验表明它们优于现有方法,并核查了核动力源VC++的功效。",
