    "direction": "人工智能",
    "summary": "基础模型(FM)通过大型、多样数据集的大规模预训,在各种机器学习领域取得了显著成功。 然而,由于数据分布严重不匹配,对这类数据集进行预先培训带来了重大挑战,时间序列数据尤其突出。 在本篇文章中,我们通过在变压器结构中提出一个具有域意识的适应性正常化战略来解决这一问题。具体地说,我们用一个原型制导的动态正常化机制(ProtoNorm)来取代传统的TyerleNorm,其中所学的原型囊括了不同的数据分布,样品到原型的亲和性决定了适当的正常化层. 这种机制有效地捕捉了TS特性的异质性,使预先训练过的表示与下游任务一致. 通过全面的经验评价,我们证明,我们的方法在各种下游任务中大大超过常规的预训技术,同时有效地减轻了预训期间分配转移的不利影响。加入ProtoNorm和替换单行码一样简单. 对各种现实世界TS基准的广泛试验证实了我们的方法的稳健性和通用性,推动了多种语言TS调频的开发。",
