    "direction": "人工智能",
    "summary": "在变形器中,位置嵌入(PES)显著影响长度通用(LG)性能,但其基本作用仍不明确. 在这项工作中,我们查明了项目执行单位在实现LG方面的两个根本限制:除了培训数据之外,无法获得新的操作员;无法处理不同尺度的相同职位的计算作用不一致的问题。 为了正式确定这些限制,我们引入了计算代表的复杂性,用以衡量一项任务所需的不同单位操作员的数量,以及条形概念,这一概念的特征是操作员-位置的一致性,因为规模不同。 我们证明,对于其计算代表复杂性随规模增加的绘图来说,PE不能达到LG,对于非卡通的绘图也不能达到LG. 我们进一步表明,在这两种失败模式缺失时,PEs可以实现LG. 在这种情况下,可以通过一个PE来实现LG,其位置关系函数是计算代表的特征. 为了增强非冠状图的LG,我们引入了缩放提示,允许灵活的实例缩放. 我们还提出了一个基于学习的立场嵌入框架,自动学习立场关系。 我们的工作为改进变形器中的LG提供了理论洞察力和实际战略.",
