    "direction": "人工智能",
    "summary": "从表层电学(EMG)中连续的手指位置估计,使得人机界面中的直觉控制比离散手势分类更平滑,更直观. 然而,准确的回归需要有效的时间模型和适应用户的可变性。 我们把反复出现的神经网络,时间演化网络(TCNs),变形器作为基准,并在Ninapro数据库中首次将神经普通微分方程(NODEs)作为基准. 每个模型的可接受域(RF)系统地从EMG自动对调,以确保公平比较. 我们进一步引入了具有外部输入的非自主的NODE变体,以代表手指运动作为动态系统.为解决跨主体概括问题,我们探索适应性学习范式,多任务,转移,一阶元学习,并调整LORA和适配器层等轻量级微调方法,用于时间生物信号回归. 在Ninapro DB8上,TCN在多任务和转移学习上达到5.4以下的先进绝对差错(MAEs),在2发元学习上达到6.47. 这些发现推进了EMG对皮肤学的回归,并为假肢、虚拟现实(VR)和远程操作的个性化实时控制提供了实用的解决方案。",
