    "direction": "人工智能",
    "summary": "在多观点分组领域,潜在的代表方法因其能够从原始数据的基本结构中提取可靠的特征说明而吸引了很多关注。 然而,现有的潜在表达方法往往依赖预先设定的参数设置来选择潜在空间的维度,而潜在空间缺乏坚实的理论基础. 此外,这些方法通常未能充分利用各种观点之间的高序关系,忽略了个人观点中的结构特征。为解决这些局限性,本文提出用常态化的超曲面词典(DLRL-NHTR)进行维度适应性Lateent Representation学习,用于多视图集成. 首先,引入了利用零空间预测的新的潜在代表框架,有效地消除了以往方法对人工维度选择的依赖。 此外,我们建议采用经改进的常态化双曲十进制(NHTR)方法,以更好地捕捉不同观点之间的高序关系。 同时,我们还引入了弹性结构规范化(ESR)术语,在个人观点中有效捕捉多层次的结构信息,从而增强整体代表能力. 对10个不同类型和尺度的基准数据集进行了广泛的实验,12种最新方法的比较结果表明,我们的方法在组合性能方面具有优越性。",
