    "link": "https://doi.org/10.1109/tkde.2026.3694421",
    "direction": "数据工程",
    "summary": "序列建议(Seqrec)旨在通过从用户的历史互动中捕捉顺序模式来预测下一个项目,在许多现实世界的推荐者系统中发挥关键作用. 然而,现有方法主要采用直接向前的计算范式,其中序列编码器的最终隐藏状态充当用户代表. 我们辩称,这种推论范式由于计算深度有限,在模拟用户偏好复杂的演化性质方面挣扎,对长尾项缺乏细微的理解,导致性能不尽人意. 为了解决这一问题,我们提议ReaRec,这是推荐者系统的第一个推论时间计算框架,通过隐含的多步骤推理来增强用户的表示.具体地说,ReaRecautore regressive将序列中最后一个隐藏状态反馈到顺序推荐器中,同时加入特殊推理位置嵌入,将原项编码空间从多步推理空间中解开. 此外,我们引入了两种轻量级推理学习方法,即“综合理性学习”(ERL)和“渐进理性学习”(PRL),以进一步有效利用ReaRec的推理潜力。 对5个公共现实世界数据集和不同SeqRec架构的广泛实验显示了我们提议的ReaRec的概括性和有效性.值得注意的是,事后分析显示,ReaRec将多个相继推荐主干线的性能上限大幅提升了大约30%。 因此,我们认为,这项工作可以为今后进行推论时间计算研究提供一条新的、有希望的渠道,供依次提出建议之用。源代码见https://github.com/TangJiakai/ReaRec.git.",
