    "direction": "人工智能",
    "summary": "视频理解要求智能代理人超越单纯的视觉事实识别,理解人类行动背后的内在意图——常被称为社会智能的\"暗物质\". 为了弥合视觉观察和意向推理之间的差距,我们引入了一个新任务IntentQA,并贡献了一个专门为此设计的大规模VideoQA数据集. 然而,我们认识到,由于数据集偏差,标准衡量标准可能高估能力,因此我们超越了简单的准确性,严格评价模型的稳健性。 我们通过大语言模型(LLMS)生成五套不同的对比度,并引入一个\"复合性能下降\"(Contrast Performance development)的度量衡来增强基准. 我们提出X-CaVIR(可解释背景-感知视频的意向推理)框架,该框架利用三种类型的\"认知背景\"加强视频分析: (一)通过跨模式视频查询语言(VQL)模块的情景背景, (二)通过对比学习模块的矛盾背景, (三)通过常识推理模块的常见背景.至关重要的是,为了克服传统模式缺乏透明度的问题,我们通过采用一个透明的管道,将视频字幕与VQA模式产出协同起来,完善了LLMs在X-CaVIR中的整合.这种办法不仅通过有效利用丰富的常识知识提高了业绩,而且使推理过程可以明确解释。广泛的实验证明了我们组件的有效性,X-CaVIR优于最先进的基线,以及它相对于对照套上的扰动的稳定性.",
