    "direction": "信息安全",
    "summary": "数据隐藏对于数字媒体的安全通信至关重要,最近深神经网络(DNNs)的进步为有效嵌入秘密信息提供了更好的方法. 然而,以往的音频隐藏方法在恢复秘密音频时往往导致质量不尽人意,因为它们在时间频率关系的建模方面有着内在的局限性. 在本文中,我们探索了这些局限性,并引入了基于DNN的新方法. 我们利用流源性的不可逆神经网络,在stego音频,封面音频,以及秘密音频之间建立直接的联系,增强嵌入和提取消息的可逆性. 为了解决在恢复过程中降低秘密音频质量的时间频率转换产生的共同问题,我们对时间域信号实行时间频率损失.这种做法不仅保留了时间频率限制的好处,而且提高了电文回收的可逆转性,这对于实际应用至关重要。 我们还增加了一种加密技术,以保护隐藏的数据不被未经授权的访问. 关于VCTK和LibriSpeech数据集的实验结果表明,我们的方法在主观和客观的衡量标准方面比以前的方法要好,并显示出对各种噪音的强烈性,这表明它在有针对性的安全通信情景中的效用。",
