    "direction": "人工智能",
    "summary": "合作多剂强化学习(MARL)被广泛应用于许多实际应用中. 尽管MARL取得了成功,但在MARL中出现了一个根本问题,即代理商面临两难处境,即是选择最佳行动以获得最大回报,还是通过探索由于部分可观察性而产生的新奇状态/行动来集体获取更多信息。 为了解决这一问题,现有方法将勘探和开发方法合并。 然而,这些方法总是不尽人意,可能导致完成任务失败。 在本条中,我们从理论上证明存在一种潜在的状态,能够保证最佳的个人和全球政策。 此外,我们证明,这种潜伏状态可以通过当地观察大致获得。 根据分析,我们提出一种方法,命名为统一的MARL(UMARL),这是一种加权价值函数要素化方法,将开采和勘探统一在一个框架内。 具体而言,我们设计代理代理代表网络(ARN)和个人加权网络(INNs),以学习代理商的统一表述和信用权重. 此外,还设计了一种潜在的状态调节器(LSR),以鼓励代理商的表述接近潜在的状态.广泛的实验显示,UMARL可以实现优异的性能,相比于在$m$-step矩阵游戏,基于水平的饲料(LBF),StarCraft II,以及Google研究足球(GRF)上的12个最先进的方法.源代码见:https://github.com/CrazyBayes/UMARL。",
