    "direction": "人工智能",
    "summary": "左捆的分支块(LBBB)和右捆的分支块(RBBB)是两种典型的心律失常类型.由于其相似的心电图(ECG)特征,传统的视觉检查(ECG)策略一直具有挑战性.以MetaFormer为动机,我们调查了一种小说MetaFormer类似模型,它既包括位置感知圆形演化(PerC)作为新的Token混合器和简单的注意机制,具有双向长期内存(SimAM-BLSTM)作为新的通道MLP,称为PerC-SimAM-BLSTM,用于自动LBBB和RBBB检测. 这个框架不仅继承了变形器的全球特性提取能力,而且增强了PerC的全球-局部特性获取能力.实验结果表明,比现有战略有更好的改进,从实验经验的角度来看,在业绩和复杂性之间也取得了更好的平衡。数学趋同证明确保模型培训从理论角度稳定地与理论优化解决方案趋同. 我们的PerC-SimAM-BLSTM在2018年中国生理信号挑战赛和MIT-BIH心律失常数据库(MADBs)中实现了超过99.1%的精度,显示出轻量级设备的巨大潜力.",
