    "summary": "扩散模型(DM)深刻地改变了基因模型领域,提供了非凡的图像生成质量. 然而,所生成的图像中残留物仍然是不可避免的挑战,这些残留物是沿着预先培训的模型模型的实际取样轨迹积累的模型设计错误造成的。 为了减少这种情况,我们提议在参数化的校正功能基础上建立一个新的剩余学习框架,旨在通过剩余校正改进建模工作。 最显著的是,我们的框架显示出显著的可转移剩余校正能力,使一个校正功能得以优化,用于在特定数据集上经过预先培训的特定管理部,以提高在同一数据集上接受过培训的其他管理部的性能。 为了进一步改进我们的框架,我们采用了一种高级培训方法,设计一个ODE采样器库,以完善残余模拟,并纳入一种记分一致性维持技术,以加强模型的趋同。 在这种方法的基础上,优化的校正功能在剩余校正方面取得了实质性的改进. 在四个广泛使用的数据集和多个预先训练好的模式模式上进行了广泛的实验,验证了我们剩余学习框架的有效性和优越性。",
