    "summary": "确保高压电气设备的安全性和可靠性,需要建立健全和准确的在线监测系统,以检测开关中的部分排放(PD)。 然而,在这类系统中传输和储存数据引起了对数据安全和隐私的严重关切。 为了解决这些问题,联邦学习(FL)通过在不分享原始数据的情况下在客户之间提供协作模式培训而获得了人们的欢迎。与以往完全根据个别客户业绩计算模型汇总权重的方法不同,我们提议采用新的FL框架,利用基于最大多样性和最小冗余度的战略来评价客户模型,从而形成一个信息更加丰富,更具代表性的全球模型. 此外,还引入了一个空间-逻辑对接模块,以加强本地数据的客户模型个性化,并通过新的知识蒸馏机制加强空间对接。 拟议框架的特点是由叶客户端,分支客户端,以及中央服务器组成的混合架构. 这种结构允许分支客户从汇总的全球知识中受益,同时在孤立客户中保持隐私.利用客户端的边缘计算可以确保快速数据处理和低相关性决策,从而提高其监测能力。 我们用一个定制的PD数据集和三个公共数据集验证我们的框架。实验结果显示,我们的方法优于最先进的方法。",
