    "direction": "人工智能",
    "summary": "现有的基于对比性语言-图像预训(CLIP)框架的视频异常检测(VAD)方法主要依赖于空间-时态特征和标签提示,经常会俯瞰高层次语义信息,如对异常行为的文字描述. 此外,虽然通常使用数据扩增技术来扩展视频帧,但在整个培训过程中,文本输入通常保持不变,将不同文本的曝光限制在同一图像上. 在本文中,我们提出一个基于文字重写的CLIP模型,称为TrCLIP-VAD. 它首先生成每个视频的源标题描述,然后利用大型语言模型(LLM)的内语学习(ICL)能力来重写这些标题,从而增强语义表达. 随后,我们随机选择一个标题,并用视觉特性将它引信,以检测异常现象. 此外,我们介绍了地方-全球多规模的Mamba(LGM-Mamba)模块。LGM-Mamba模块旨在捕捉帧序列的局部-全球时间依赖性,并促进视觉和字幕特性的深度融合,以提高检测性能.实验结果显示,TrCLIP-VAD在XD-暴力与UCF-Crime这两个广泛使用的数据集上实现了最先进的性能. 具体而言,TrCLIP-VAD在XD-violence数据集上取得了86.05%的AP分,在UCF-Crime数据集上取得了88.59%的AUC分. 该代码发布于https://github.com/vpsg-research/TrCLIP-VAD.",
