    "direction": "人工智能",
    "summary": "计算机视觉中无人监督的开放设置域名适应(UOSDA)被广泛研究. 然而,由于数据的非固定属性和分布在不同操作条件下的转移情况复杂,增加了负转移的风险,因此设计时间序列的UOSDA算法仍然具有挑战性. 为了解决这一问题,建议在时间序列分类中为UOSDA采用新颖的两阶段特征对齐(TSFA)方法. 首先,一个时间频率特征提取器旨在有效学习域-不变量和歧视性的类间表示. 随后,提出了分两个阶段的多边形特征调整框架。具体来说,通过最小化相似性分布 en(SDE)实现全球对齐,鼓励两个域的类似样品在特征空间中汇合,从而缩短所有目标样品的类内距离. 然后,通过在目标伪标签的指导下进行自我监督的学习来进行局部对齐,增强目标共同样本的阶级间区别性. 此外,设计了一个最佳相似性分配矩阵(OSAM),以获得更准确的普通样本伪标签,同时采用了一个适应性决定边界,以有效拒绝基于目标域统计的私人样本。 最后,关于三个现实世界数据集的广泛实验结果表明,拟议方法的绩效超过了最新方法。",
