    "direction": "人工智能",
    "summary": "在帕金森氏症(PD)的深脑刺激(DBS)手术中,精确的手术内识别关键核(如亚脑核(STN))对于确保治疗疗效至关重要. 然而,目前的做法在很大程度上依赖于专家的说明,分类任务通常仅限于对STN和非STN区域进行二进制区分。 这种限制妨碍了在与PD有关的DBS程序中实时识别复杂多样的神经解剖结构. 为了克服这一挑战,我们提出了微电极记录信号(MER)的三等分类战略,以有效区分Zona incerta(Zi),STN,和substantia nigra(SN).这种方法将有监督的特征选择与无监督的集群整合:区分特征首先使用随机森林算法进行选择;然后将这些特征输入模糊的c-means(FCM)集群进行初步分类;最后,低自信分数的样本进行人工审查. 这一策略形成了高效,可核查的标签生成机制,提高了分类精度,增强了临床应用性.实验结果显示,拟议的\"分组+审查\"标签框架实现整体分类精度92.71%,只有约10%的样本需要人工验证,与专家标签的准确度接近92.97%,显著提高标签效率. 此外,所有三个核子(Zi、STN和SN)的ROC-AUC值都超过了0.97,证实了该模型的强烈歧视性能。 通过结合受监督的和不受监督的技术,拟议的MER信号的多核分类框架不仅确保了高精度,同时大大减少了人工注释的成本,而且还为快速神经信号标签提供了可伸缩和高效的解决方案.这种方法特别适合实时应用,如DBS期间的操作内目标本地化,并显示出很强的临床翻译潜力.",
