    "pdf": "papers/incremental_4b360d1e5370.pdf",
    "link": "https://doi.org/10.1109/tpami.2026.3689721",
    "direction": "人工智能",
    "summary": "人类每天参与一些程序活动,如烹饪食谱或修整自行车,这可以被描述为在某些订单限制下,以目标为导向的按键步骤序列. 从视频或文字描述中挖掘出来的任务图最近越来越受人欢迎,因为它是人可读、整体地代表程序活动,将部分命令编码在关键步骤之上,并显示出支持下游视频理解任务的希望。 虽然之前的作品一般依靠手工制作的程序从视频中提取任务图表,但本文引入了基于梯度的边缘权重最大概率优化的方法,这种方法可以用来直接估计一个辅助矩阵,也可以自然地插入更复杂的神经网络架构中. 我们验证拟议方法在CaptainCook4D和EgoPER数据集上生成准确任务图的能力。 此外,我们还将验证分析扩展到EgoProcel数据集,我们用任务图表对数据集进行人工注释,作为补充贡献。三个数据集共同构成任务图学习的新基准,我们的方法比以往的方法分别得到+14.5%、+10.2%和+13.6%的改进。 由于拟议框架的不同,我们还采用了一种基于特征的方法,从关键步骤的文字或视频嵌入中预测任务图,显示新兴的视频理解能力。 除此之外,通过我们的方法学到的任务图在Ego-Exo4D程序理解基准中获得了最高的性能,包括5个不同的下游任务,收益率分别达到+4.61%,+0.10%,+5.02 %,+8.62%,以及+15.16%,以发现前一个关键步骤,可选关键步骤,程序错误,缺失关键步骤,和未来关键步骤。 最后,我们显示出在程序自负式视频中在线发现错误这一艰巨任务有了显著的加强,与最新技术相比,在Assembly101-O和EPIC-Tent-O数据集中分别取得了+19.8%和+6.4%的显著收益。复制实验的代码见https://github.com/fpv-iplab/ Differentiable-Task-Graph-Learning。",
