    "summary": "确保防止基于任何敏感属性的潜在偏见的公平模式,对于关键应用中人工智能的社会接受至关重要。 在各种公平概念中,反事实的公平性由于基于因果推论而得到重视。这一概念要求个人在原始世界的预测与在敏感特征值被修改的反事实世界的预测保持一致. 在本条中,我们的目标是通过因果干预来减少模型的反事实偏差。 具体而言,我们首先通过提出因果推断表式基因对抗网络(CITGAN)架构来实现有效的因果干预和反事实生成.与以前基于变异自编码器(VAEs)的方法不同,由于同时生成而内在缺乏结构因果模型(SCM)的忠实性,CITGAN严格通过端到端的地形生成过程强制实施因果一致性. 通过将外来变量推论与相继生成相结合,CITGAN确保功能依赖性在结构上得到保存. 在CITGAN的基础上,我们提出CIRCUS框架,这是一个基于因果干预的框架,旨在直观地加强训练有素的分类者的反事实公平性。CIRCUS以梯度和特征贡献为导向,通过因果干预产生反向歧视性样本,随后对其标签进行偏差更正预处理,用于分类者再培训.实验结果显示,CIRCUS在保持稳健的分类性能的同时,有效地增强了反事实的公平性.具体来说,对于深神经网络(DNN)模型, $\\ text {MMD}_{\\\\ text {L}}$ 和 $\\ text {MMD}_{\\ text {K}}$ $$ 平均分别减少39.7%和40.4%, 与第二好的结果相比.剩余网络(ResNet)模式的削减率分别为56.7%和54.5%。",
