    "summary": "之前的作品已经表明,增加基于变形器的图像超分辨率模型(如SwinIR)的窗口大小可以显著改善模型性能. 然而,当窗口规模逐渐扩大时,计算间接费用也相当大。 在本文中,我们介绍了SRFormer,一种简单但又新颖的方法,它可以享受大窗口自觉的好处,但引入的计算负担甚至更少. 我们的SRFormer的核心是穿透的自觉性(PSA),在自觉性的通道和空间信息之间达成适当的平衡. 没有铃声和哨声,我们显示我们的SRFormer在Urban100数据集上实现了33.86 dB PSNR分数,比SwinIR高0.46 dB,但使用参数和计算较少. 此外,我们还试图通过进一步扩大窗口大小和频道号码来扩大模型,以探索基于变形器的模型的潜力.实验显示,我们这个被命名为SRFormerV2的缩放模型可以进一步改善结果,实现最先进的水平. 我们希望,我们的简单有效的方法能够有助于今后对超分辨率模型设计的研究。",
