    "summary": "对话框状态跟踪(DST)是面向任务的对话(TOD)系统的重要组成部分.现有的几率DST模型在有效利用与集合相关的信息方面面临挑战,对对话情景的适应性有限。 为了应付这些挑战,建议采用双师双时速的DST(DDP-DST)模式。 具体而言,通过增强关键语义信息和合成结构,构建了双师模型,从互补的角度生成伪标签.利用自我培训来进一步改善国家价值的产生。 此外,考虑到槽和状态值生成任务的内在对称性,还设计了双速微调策略.建造一个动态快速池,以适应性地生成提示。重建错误(REs)被反馈到DDP-DST模型中,导致DST的精度提高.MultiWOZ 2.1数据集的实验结果表明,DDP-DST比SM2-3b,DS2,SVAG等基线模型的绩效要高于联合目标精确度(JGA)的平均水平为4.3%,2.4%和2.0%.值得注意的是,在不到10亿个参数的情况下,DDP-DST在几发环境中实现竞争性表现,甚至有多达100亿个参数的优于模型.",
