    "direction": "人工智能",
    "summary": "恶意探测系统越来越多地受到多态对抗战术的挑战,这些战术利用线程和过程之间任务分工的变化。接受过单体、单过程检测模式培训的传统检测模式,为普及这些战术而挣扎。 我们提出一个防御框架,将两个互补战略结合起来:通过行为分解来抵御逃逸的强力和通过基于模型聚变的学习来强化建筑. 我们的方法采用了一种基于 en的分割策略来分解系统调用日志,同时通过一种意识到侵权的惩罚机制来明确保存时间和语义上的依赖性. 我们的划分方案反映了现实的多形态行为,确保功能在分区之间得到保存.该框架通过聚变得到进一步加强,结合了在多种对抗分裂配置下训练的多个子模型. 我们评价关于ADFA-LD基准数据集、其多流程扩展、ADFA-LD-MP以及真正恶意软件的BarogTrace数据集的拟议方法。实验表明,我们的框架大大改进了探测性能,特别是在传统模型退化的高分化制度下。分层意识训练,加上模型聚变,提高了F1分数,并增强了对各种对抗条件的概括性。",
