    "summary": "多视图3D重建,即结构-从动,然后是多视图立体声,是3D计算机视觉的一个基本组成部分.一般来说,多视图3D重建受到未知尺度模糊的影响,除非场景中存在已知大小的参考对象. 在本篇文章中,我们显示使用双像素(DP)传感器捕获的多视图图像可以自动解决尺度模糊问题,而不需要参考对象或事先校准.具体地说,DP图像中观察到的去焦模糊,提供了足够的信息,在与从多视图3D重建中恢复的深度地图(上至比例)配对时,可以确定绝对尺度. 基于这一观察,我们开发了一个简单而有效的线性方法来估计绝对尺度,然后是强度优化阶段,通过使用交叉视图模糊的内核将左右DP图像向后移动来对准.实验显示,拟议办法在用不同相机和镜头拍摄的不同场景中具有效力。",
