    "contentNote": "已完成本地开源模型英译中，六段式其余部分待人工全文核验",
    "doi": "10.1109/tkde.2026.3701263",
    "arxiv": "",
    "pdf": "papers/incremental_51634dd70d66.pdf",
    "link": "https://doi.org/10.1109/tkde.2026.3701263",
    "direction": "数据工程",
    "summary": "作为转移学习中的一个基本问题,模型选择旨在对现成的预先训练的模型进行排位,并为新的目标任务选择最合适的模型.现有的模型选择技术在范围上往往受到限制,往往忽略模型和任务之间的细微关系。 在本文中,我们提出了一个务实的框架Fennec,探索了多样化的、大规模的模型存储库,同时仔细考虑了任务与模型之间的复杂联系。关键洞察力是将所有模型和历史任务映射到一个与转移相关的子空间,其中模型矢量和任务矢量之间的距离代表可转移性的规模. 一个大的视觉模型作为代用,推断出一个新的任务在转移空间中的表示,从而规避了大量前传和依赖标签的计算负担. 我们还调查模型内在的诱导性偏见对转移结果的影响,并提出一种称为archi2vec的新方法,以编码模型的复杂结构。转录分数通过直截了当的矢量算法计算,每个模型推论持续的时间复杂性为O(k)(其中k是潜在空间的维度). 最后,我们通过公布一个包括105种不同模式的全面基准,对外地作出了重大贡献。 我们通过对两个基准进行严格的测试来验证芬纳茨的有效性. 我们的框架在两个基准上都取得了最佳的评价准确性。 在PARC基准上,特性提取时间比同一级别的基线快6.5×,推断时间比最快的基准快5.7×. 在更大的基准上,业绩收益更为明显,特征提取时间比最快的基准快52.3×,推断时间比最快的基准快1.8×,显示出显著的业绩效率. 该守则已在https://github.com/Fay-why/Fennec上公布。",
