    "direction": "人工智能",
    "summary": "等效的图形神经网络(GNNs)在各种科学应用上取得了显著的成功. 然而,现有方法在缩放到大几何图形时面临严重的效率挑战,在输入图被抽筋用于计算可移动性时,其性能严重退化。 为了克服这些局限性,我们引入了FastEGNN和DistEGNN,这是两个用于大规模几何图形的等效GNNs的新增强.FastEGNN 采用了密钥创新:一套小型的顺序虚拟节点,有效近似真实节点的大型无序图. 具体而言,我们针对不同的虚拟节点实施独特的信息传递和汇总机制,以确保相互的独特性,并尽量减少虚拟和真实坐标之间的最大平均差异,以实现全球分布。 这种设计使得FastEGNN能够保持高精度,同时高效地处理大规模稀疏的图表. 对于极大规模的几何图形,我们提出DistEGNN,这是一个分布式扩展,虚拟节点作为不同设备中子图之间的全球桥梁,保持一致性,同时大幅降低内存和计算间接费用. 我们从四个挑战领域全面评估我们的模型:N-身体系统(100个节点)、蛋白质动力学(800个节点)、水-3D(8 000个节点)和我们新的Fluid113 K基准(113,000个节点)。成果显示,效率和业绩优异,在大规模等效图表学习中建立了新的能力。",
