    "summary": "与Graph神经网络有关的广泛采用和重大开发成本增加了模型盗窃攻击的可能性,对知识产权构成严重威胁。第三方所有权核查提供了一个有效的机制,在确保公正核查的同时保护模式所有者的知识产权。目前的GNN指纹验证方法提出了不切实际的要求,要求获取内部的模型指纹(如节点嵌入)或关于模型盗取攻击的详细信息. 在本文中,我们提出加那利,一个黑盒第三方GNN所有权基于指纹的核查协议,其中核查者只访问模型预测后缀,不需要知道对手模型偷袭.具体来说,我们通过尽量扩大阴影代位模型与阴影独立模型之间的对数距离,有效揭示其后期概率差异,生成子图输入作为决定边界指纹.跨越6个数据集的实验显示,加那利有效检测到10种型号偷盗攻击,实现了35.68%的负级F1-分数高于最先进的灰盒方法Grove,同时保持了抵御7种逃避攻击的稳健性.",
