    "link": "https://doi.org/10.1109/tdsc.2026.3696769",
    "direction": "信息安全",
    "summary": "集成电路(IC)供应链的全球化,在时间到市场和成本的考虑的驱动下,使得IC易受硬件特洛伊(HTs)的影响. 针对这种威胁,一种有希望的方法是使用基于机器学习(ML)的侧通道分析,这种分析的优点是是一种非侵扰性的方法,同时在黄金芯片无设置下有效检测HT. 在本文中,我们质疑基于ML的HT检测通过侧通道分析的可信赖性. 我们采用了HT模糊法(HTO)方法,允许HTs绕过这种检测方法.与其通过模拟对抗性痕迹在理论上误导模型,我们方法的一个关键方面是设计和实施对抗性噪音作为电路的一部分,与HT并列. 我们详细介绍了ASICs和FPGA的HTO方法,并利用TrustHub基准评估我们的方法。有趣的是,我们发现HTO可以用一个单一的晶体管执行ASIC设计,生成对抗性功率痕迹,可以100%的效率欺骗防御. 我们还利用两种不同的变体,即(一) DSP切片法和(二) 环-振荡器法设计法,高效率地实施了关于Spartan 6 Xilinx FPGA的方法。 此外,我们评估光谱域分析等对策的效率,我们显示适应性攻击者仍然可以通过使用光谱噪声预算限制设计来设计回避HTO. 此外,虽然对抗性训练(AT)提供了防止规避性HT的更高保护,但AT型号却遭受了相当大的公用事业损失,有可能使它们不适合这种安全应用。 我们认为,这项研究是在硬件安全背景下理解和利用ML脆弱性的一个重要步骤,我们在网上公开提供所有资源和设计:https://github.com/beomidi/HW-Trojan-UAP-Generation。",
