    "direction": "人工智能",
    "summary": "必须从数量上分析冠状动脉血管造影图象,以便进行冠状干预程序,因为这些图象是评估动脉硬化的黄金参考标准。 然而,正因为专家附加说明的数据不足和难以统一定义血管分支,主流方法无法提取不同的血管分支. 为解决这一问题,本文提出一个新颖的框架,用简单的注释分析多分支船体,首先将血管分支的端点本地化,然后根据端点提取相应的船体部分. 考虑到目前以图像为基础的方法很难区分稀疏的船键点,我们建议建立一个跨模式语言强化终点检测网络,通过提供临床医生获得的语言知识,实现更好的性能。建立了医疗术语表,将谈话内容转换为标准文本。 此外,我们设计了双层船分离(TS-Seg)算法,根据灰色水平特征和检测到的终点划分各种血管分支。 此外,允许临床医生手动添加新的终点,并单独应用TS-Seg算法来分析之前没有定义过的任何变体血管分支. 对两个内部数据集和一个公共数据集进行的广泛实验始终表明拟议框架的有效性和优越性。 此外,根据临床前的知识提供了综合船只分析报告,以协助手术前的手术规划和术后治疗评估,显示出提高临床工作流程效率和准确性的巨大潜力。",
