    "summary": "随着基于扩散的恶意图像操纵日益盛行,现有的主动防御方法在未知条件下为保护图像不被篡改而挣扎. 为了解决这一问题,我们建议采取预防性防御办法,实现由三个新单元组成的保护。 首先,我们采用了多层次的深层特性提取器,以从扩散消音过程中获得复杂的特性,提高保护效力。 第二,我们设计一种多尺度、语义保存数据增强技术,以加强对抗性扰动在未知条件下的可转移性。 最后,我们提出了一个基于选择的分配偏差优化战略,以加强保护,防止受各种随机种子的操纵。 对InpaintGuard Bench和CelebA-HQ的广泛实验表明,在未知条件下,抗Inpaint在扩散的基础上有效防印剂. 此外,我们的做法表明,与各种图像净化方法和不同传播模型版本之间的可转让性相比,是强有力的。",
