    "direction": "人工智能",
    "summary": "现有角色扮演代理(RPAs)由大型语言模型提供动力,主要通过静态的,只用文字的,dyadic的对话来评价,这没有充分反映出涉及多个对话者和多模式交流的现实的人类互动的复杂性. 为了弥补这一差距,我们提出OmniCharacter++,这是在联合文本-语音背景下评价多特征互动的第一个基准。具体来说,OmniCharacter++贡献了:(1)一个大型数据集,包含10,287个字符,118,017个多回合对话,以及跨越8个开放世界主题和31个子域的100多万个音频响应,涵盖多种多模式角色扮演情景;(2)一个用于对话理解,生成质量和知觉自然的综合评价套件;(3)UniCharacter-7B,一个统一文本语音模型,在这个数据集上培训,以管理复杂的多特征动态,确保角色特异的声忠性和跨参与的语义一致.实验结果表明,UniCharacter-7B在吸引力和一致性两方面都实现了更现实,更一致的角色扮演反应,同时强调OmniCharacter++对最先进的模型提出了巨大的挑战,为未来的研究指明了一条明确的道路.",
