    "summary": "图表神经网络(GNNs)是处理图表结构数据的关键,在关键领域有广泛的应用. 在高额假设中越来越多地使用全球网络网络需要强有力的解释性,以确保决策中的信任和透明度。解释GNNs的一个常见方法是识别子图,a.k.a. 这对模型预测有重大影响。 然而,由于从最初的训练图到解释子图的分布转变,这项任务具有挑战性,这个因素在现有的研究中基本上被忽视了. 这些转动之所以出现,是因为GNNs是接受原始图表训练的,而解释子图往往在节点数或结构图案等属性上有所不同. 因此,GNNs可能难以以与其培训数据不同的分布来概括解释子图. 在本文中,我们通过理论分析和实证研究,系统地调查了分送(OOD)问题. 为了应对这一挑战,我们首先制订了一个理论框架,通过充分性和最低标准,使解释子图的概念正规化,确保预测保全和结构紧凑。 我们的分析揭示了解释子图和原图之间的根本分布差异,导致了本作中提出的代用图的新概念.代用图保持基本的解释性信息,同时通过参数化和非参数化优化方法的结合,符合原始数据分布. 对各种数据集的实证评价表明,我们的方法提高了GNN解释的质量和可靠性,推动了GNN解释性领域.",
