    "summary": "本文对多稳定神经网络(MSNNs)的多同步性进行了调查。 首先,构建了MSNN多稳定神经网络(SNN)模型,既受到时间变化的延迟,又具有参数不确定性,它准确描述了现实环境中的神经动力学. 随后,为了降低控制成本,为了研究MSNN系统中的多同步问题,采用了组合冲动控制策略. 通过开发适当的Lyapunov功能并利用平均冲动间隔概念,可以产生足够的条件,使在固定和切换地貌下被认为的SNN实现多同步。 最后,拟议控制计划的有效性通过数字实例加以核实。",
