    "direction": "人工智能",
    "summary": "时间变化的四重奏节目问题可被视为在广泛的工程应用中具有挑战性的问题,经常包括平等、不平等和约束性限制。 通过整合非线性互补问题(NCP)配方,可以将神经网络零化(ZNNs)普遍化,以这样一套完整的制约有效解决TVQP问题. 然而,有三个问题可能限制其计算效率和实际应用:(1) 处理平等/不平等和边界限制的国家CP功能的内在制定大大扩展了系数矩阵/变量和溶液-空间变量的维度;(2) 常规的ZNN(CZNN)框架必然需要为实时解决方案进行矩阵反转操作;(3) 防止噪声干扰的强度不足,在实际执行中损害解决方案的准确性。 为了克服这些问题,促进解决方案的绩效,本条开发了一个更低维度的NCP低复杂度(LCC)ZNN(ELNCP-LCCZNN)模式,以时间变化中的平等,不平等和可变的边界限制来解决TVQP问题.设计了ELNCP功能以减少模型的矩阵/源系数,LCCZNN模型用于构建一个新的动态模型,消除溶液中矩阵反转的必要性. 此外,还涉及一种非线性激活功能,以保证预先确定的时间趋同,并加强对噪声的强性。拟议的ELNCP-LCCZNN模型的理论性质通过数字模拟和机器人操纵器动能控制实验得到验证.分析结果证实了分析,并表明与现有方法相比,计算效率有所提高,噪音更强,实际可行。",
