    "link": "https://doi.org/10.1109/tdsc.2026.3701041",
    "direction": "信息安全",
    "summary": "私人智能合同(PSCs)旨在解决区块链上敏感数据的隐私保护问题(a.k.a,在链上的数据),同时继承一般智能合同的计算功能. 然而,大多数现有的PSC侧重于安全的计算,忽略了对链上数据的安全和灵活的管理,因此难以高效支持灵活的用户许可模式. 此外,虽然已经提出了几个管理区块链数据的链上数据管理办法,但它们对数据必须由具有不同特权水平的管理人员同时管理的各种设想提供了不足的支持。本文提出MISC,这是一种新颖的解决办法,它以高效和灵活的数据管理能力为特点,管理私人智能合同中的链上数据. MISC通过一种新型的Double Trapdoor Hommorphic Proxy Re-centration(DT-HPRE)计划与信任执行环境,确保(1)对链上数据进行低管理、灵活许可控制,(2)为特权和受限制的管理人员建立一个和谐的机制。 我们根据通用编译能力框架证明了国际空间协调的安全性,以表明其数据保密保障、用户撤销和计算完整性。 此外,我们实施国际空间信息协调,业绩评价显示,在使用其离链设计的情况下,在5.8s(特权管理人员)和9.7s(受限制管理人员)实际上实现了100个数据点的链上数据访问。",
    "question": "待人工补全。",
