    "summary": "在本篇文章中,提出了高斯-牛顿时间差(GNTD)学习方法,以解决美元Q$ - 非线性函数近似的学习问题. 在每次迭代中,我们的方法都采取一个高斯-牛顿(GN)步骤,以优化平均方位贝尔曼误差(MSBE)的变体,其中采用目标网络来避免双重采样. 对不准确的GN步骤进行了分析,以便人们能够安全有效地通过廉价的矩阵迭代来计算GN更新. 在温和条件下,各种非线性函数的无症状有限-抽样汇合到全球最佳的美元功能。特别是,对于具有reLU激活的神经网络参数化,GNTD实现了$\\tilde \\ mathcal {O}}(\\varepsilon {1})$的改进样本复杂性,与 $\\mathcal {O}}(\\varepsilon {2}) 现有的神经时间差错(TD)方法的样本复杂性相对应.$\\tilde \\ mathcal {O}}(\\varepsilon ^{-1.5}) $ 的 GNTD 样本复杂度也被确定为一般平滑函数近似值。 我们通过对若干强化学习基准的广泛实验来验证我们的方法,在这些基准中,GNTD比TD类方法表现出更高的回报和更快的趋同.",
