    "summary": "时间序列异常检测通常用于识别与正常数据有显著偏差的数据,常显示基础系统中的断层或故障,从而有利于系统稳定性和安全性. 大多数现有方法侧重于发现异常现象发生后,而预测未来异常现象的研究仍然很少。 在异常现象显现之前,往往有细微偏离正常行为的前体,反应时间和强度不一.接下来,设置的特征往往是缺乏标注数据,这使得模型培训复杂化. 为了应对这些挑战,我们提出了一个时间序列异常预测框架,即技术咨询方案。它可以灵活地适应不同变量中异常前体的不同反应时段,使用一个具有时间意识的多尺度模块,并且能够通过结合重建和对比性学习的双分支框架,加强前体与正常序列的区分.对比分支在多尺度补丁中采用可控生成策略,生成多种硬负性样品,用于前体识别.重建处通过评估波动幅度来补充这一点,以确保对微妙变化的敏感性。 我们报告关于来自不同领域的8个数据集的实验,发现与异常检测和预测的基线方法相比,TAP具有竞争力或优越性能.",
