    "summary": "最近在完成多模式知识图(MKGC)方面所作的努力表明,通过对比性学习,取得了令人印象深刻的进展。 然而,一种非常识的观察表明,单纯追求跨模式共识可能会意外地使MKGC的性能恶化,因为不可信的辅助模式的结合。这种行为在此被称为模式退化,无意中削弱了对比性学习与MKGC之间的协同作用. 在本文中,我们引入了结构指导的 \" 弹性共识学习 \" 框架。 它从可信赖的多式联运实体代表处获得跨模式共识。具体地说,为了减少CLIP衍生的多式联运表述中观察到的语义偏差,在SECL中采用了一种结构指导的多式联运表述统一方法。 由于不同实体的结构背景是协调者,这种方法有选择地压制了CLIP衍生的多式联运表述中无关紧要的特征,从而促进了它们之间的语义一致性。 为了监督这一统一进程,提出了弹性对比性学习方法。 它引导模式优化,优先调整对硬实体的多式联运代表,从而缓解了对跨模式共识的探索不足。 对基准数据集的广泛实验表明,SECL显示了模式的演变,而不是退化,比最先进的方法大有改进。",
