    "summary": "深层次的学习方法在医学影像分化方面表现出显著的进步. 然而,实现高准确性仍然是一项突出的挑战。 在本文中,我们提出了一种名为VGM-UNet的新架构,通过引入结构化的状态空间质量算法,将Graph神经网络,稀有的注意力,和Mamba-2合并到U-Net中,从而在性能和表达性上改进U形的分区模型,并产生这些设计的最佳效果. 我们通过三项主要修改来完成这项工作:我们首先采用了一种新颖的方法,建造了一个2D状态空间模型和一个八向多扫描模块,从而创建了Vision Mamba-2,作为建立可直接应用于图像补丁的图形结构的层次视觉骨干的基础. 然后,在快速Fourier变换的基础上,我们构建了一个Feed-Forward Network模块,作为Mamba的一个补充,用于模型化通道内容,提高捕获小物体的精度. 此外,在模块架构的基础上,我们构建了一个简单而强大的U形混合网络,简化了模型设计,增强了模型的表达力. 这些变化缓解了传统U形架构在精度改进方面的局限性,并取得了令人印象深刻的成果. 我们通过广泛的实验验证VGM-UNet,证明我们的模型在突触和ACDC基准数据集的分化精度方面,比现有最先进的模型要好.实验结果还表明,可方便地将视觉图形状态空间模块应用于各种医疗图像分区任务。",
