    "summary": "数据集蒸馏(DD)旨在合成一个比原始数据集更紧凑的数据集,并且对其培训的模型预计将具有与原始数据集相同的概括化能力.以往通过基因模型(GM)完成的工作面临若干限制. 第一,全球机制由于缺乏限制,难以生成有代表性的样本。 第二,它忽略了生成样品之间的关系,限制了其有效性。 本文件提出了一个新的基于全球机制的不受限制的DD框架。 在蒸馏阶段,引入了适应性匹配系数,将生成的图像与代表性类元素对齐,并扩展了MiniMax损失功能,以减少优化难度. 在部署阶段,每个基因图象的特征通过梯度比对的DD来组合。 基于McDiarmid不平等的理论分析表明,拟议的组件可以减少原始基准方法的概括性错误. 我们还深入了解生成的图像作为DD的有效代用数据集的潜力。 例如,在ImageWof数据集上,每类有50个蒸馏图像,使用6层ConvNet进行评估,生成的图像比原始图像的25%、50%和75%高出8.4%、6.3%,蒸馏性能高出8.3%。 我们的方法有效地处理低分辨率和高分辨率的数据集,对11个基准的实验显示了它的功效。",
