    "summary": "深神经网络(DNNs)在多个领域都没有实现表级进步. 然而,他们仍然容易受到侧通道袭击,这些袭击使他们面临模式盗窃,对安全构成重大威胁。使用DNN混淆法缓解SCA的现有对策往往涉及不切实际的硬件修改,或者由于需要在目标平台上进行耗时的部署,因此其可扩展性较差。 我们介绍CLOb-DNN(DNNs的Contrastive Learning Obfusation),这是一个新的对比性学习基础框架,既能提高DNN对SCA的混淆的效率和强烈性. 通过利用三胞胎网络,我们有效地减少了重复实际部署的需要,大大提高了疏漏效率,同时确保疏漏的DNN满足暂时性的限制. 我们的框架整合了架构层面和调度层面的歧义,以增强稳定性,避免对后端源代码进行代价高昂的修改. 我们利用多种最新攻击模式进行广泛的评价,以显示我们对付各种威胁的有力方法。实验显示,我们的方法将模糊时间缩短了约90%,达到了优越的防御能力,并成功满足了各种延迟要求,从而为保护DNN IP针对SCA提供了实用有效的解决方案.",
    "question": "待人工补全。",
