    "summary": "不确定性是人类知识的一个基本方面,广泛存在于医学、生物学和金融等各个领域。不确定的知识图补全(UKGC)的任务既包括联系预测,也包括信心预测. 然而,由于无法获得高质量知识,导致知识图稀少,许多实体所显示的邻里相对稀少。 这种麻痹严重妨碍了几弹的UKGC模型的性能,这些模型一般依靠邻里聚合来增强实体的表示. 在这项研究中,我们提出一个Meta relationslation-aware Metric学习框架,为几发UKGC设计,命名为MMUC. 为了缓解邻居的麻痹,MMUC引入了一种以关系为中心的范式,从背景图中脱钩表达增强,通过可学习的信心学习者整合一种由不确定性驱动的相似性措施,以实现强力的非线性聚变,以进行联合联系和信心预测.跨越多个基准的广泛评价通过严格的关联和信心预测、衰减研究和痉挛性分析,显示了MMUC的优异业绩,在几发不确定的KG中突出了其对邻居筋挛性的特殊复原力。源代码可在https://github.com/sienna-wxy/MMUC访问.",
