    "summary": "交通流量预测是智能交通系统的核心技术之一.其根本挑战是有效模拟复杂的时空依赖。 尽管在这一领域进行了广泛的研究,但目前方法的局限性限制了其准确预测的有效性。 对于时间依赖性,基于反复出现的神经网络的现有方法只关注局部依赖性,而忽略了全球依赖性. 对于空间依赖性,现有方法使用预先定义的或适应性的辅音矩阵,无法准确反映真实流量流之间的关系. 为了克服这些局限性,我们提议建立一个动态空间-时态聚变图演化网络(DSTFGCN). 在时间方面,我们引入了有门的膨胀因子演化法,以捕捉本地的依赖和节点独立的时间图演化法,以捕捉每个节点特有的全球依赖性. 在空间方面,我们提出一个动态图解块。 它可以根据输入数据的特点构建动态图表,并汇总局部和全球的空间依赖性. 对6个现实世界数据集的实验表明,DSTFGCN超越了目前的主流方法. 这些代码见https://github.com/SYLan2019/DSTFGCN。",
