    "summary": "神经发育障碍的特点是认知、交流、行为和适应功能方面的缺陷,对基于神经成像的诊断的保健资源造成越来越大的压力。 虽然基于深层学习的计算机辅助诊断系统提供了潜在的解决方案,但功能性磁共振成像(fMRI)数据所固有的复杂的瞬间动力学使特征表示极易受到噪音和混淆因素的影响,大大限制了诊断效果. 在这里,我们提出使用fMRI进行NDD诊断的共性-认知转移学习(CATL)框架.CATL引入了一个增强的表达生成网络,将转录学习与伪标签融合在一起,将任务相关的时间特征与fMRI数据中混淆的图案区分开来,然后通过编码器-解码器架构进行特征重建. 这些精细的表示法随后被分类使用轻量级的演化神经网络(CNN)来构建CAD模型.关键是,CATL通过统一的半监督转移学习范式,明确模式共享NDD共性背后的神经生物学途径,为跨疾病神经动力学提供新的机械学洞察力. 在基准数据集上,CATL的自闭症谱系障碍的诊断速率平均为77.34%,注意力不足/过度活跃症的诊断速率为73.28%,表现优于最新水平的转移学习方法的诊断速率分别为7.86%(ASD)和0.66%(ADHD)。",
