    "summary": "分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布式分布 为了更好地实现OO通化,目前的方法越来越注重从零开始设计更复杂的因果推论模型培训,而不考虑现有预先训练的模型的潜力,增加计算的复杂性. 在本文中,我们提出一个高效的框架(EGOG),这个框架利用对经过预先训练的GNNs的即时学习,从输入图数据中提取因果子图,以增强经过预先训练的GNNs的通化能力.具体来说,我们设计了一个图因果即时模块,以提高预训GNN的通化能力. 首先,我们使用带有因果特征生成器的图表即时学习,使预先训练的GNN能够将因果特征与图表节点中的假特征脱钩. 然后,考虑到图的结构也受到分布转移的影响,我们进一步设计了一个因果结构生成器,它重新利用预先训练过的GNN来分析图的结构,将因果亚结构与假的亚结构脱钩.这种方法提高了GNN经过预先培训后从节点和结构两个角度解析因果子图的能力. 与此同时,我们利用梯度反转层和信息瓶颈来鼓励我们的方法更准确地将因果子图从虚假子图中分离出来.实验结果表明,EGOG可以被应用到预先训练的GNN上,以获得通俗化能力.与最先进的基线相比,EGOG显示两个合成数据集的平均相对改善率为2.73%,而只使用平均4.38%的可列车参数.",
