    "summary": "本文为动态未知的非线性二阶多剂系统(MAS)设计了最佳编组封装安全跟踪控制协议.人类操作员可以与MAS的跟踪头目互动,在障碍加固的环境中,通过MAS网络提高安全性并与其他特工进行交流. 主要利用适应性神经网络来识别未知的非线性动态参数,并确保识别状态误差不对称地汇合. 此外,优化的安全控制设计还采用了基于加固学习(RL)的演员-批评建筑,以近似于汉密尔顿-雅各布比-贝尔曼(HJB)方程式的非线性MAS. 这种对MAS的分布式安全控制,仅使用局部连通性信息就实现了最佳的跟踪. 最后,在未知的障碍环境中,用多个无人驾驶飞行器系统对MAS安全编队-闭塞控制的拟议最佳算法进行核查。",
