    "summary": "后门攻击深层模型因其隐蔽性和破坏性而越来越受到研究者的关注,导致提出了众多攻击方法. 在这些攻击方法中,清洁标签攻击显示出更好的隐蔽性和实用性,因为它们可以绕过人工检查。 然而,目前的清洁标签触发器通常独立于原始图像,并依赖于简单的图案,使其易于检测和识别. 为了解决这些问题,我们提出一个新的清洁标签后门攻击框架,通过风格转移网络系统解开风格和内容,利用风格特征作为隐形触发器,实现语义一致性并逃避先进的防御机制.具体来说,我们利用一种风格预测器网络来实现图像样式的精确提取和有效分离,仔细训练了一种风格触发器,将它与预先定义的样式特征和图像内容结合起来,从而构建样式触发器与图像高度相关. 为了进一步增强攻击的侵略性和隐蔽性,我们引入了由风格损失和内容损失组成的一致性约束,它鼓励中毒图像具有与风格触发器相似的风格和与干净图像相同的内容. 对标准基准数据集的全面实验表明,我们的风格后门攻击在中毒样品上取得了近乎完美的成功率,对良性样品的准确性影响最小,并且能够绕过几乎所有最先进的后门防御.",
