    "summary": "基于传感器的人类活动识别(HAR)领域主要使用惯性测量单位(IMU)的姿势,运动和上下文数据来识别日常活动. 尽管在以学习为基础的方法方面取得了进步,但从时间角度进行信息聚合是一项挑战,因为混合各种传感器数据和建立长期环境关联十分复杂。本文提出了适合HAR的新型三光谱聚变框架. 首先,我们开发一种适应性互补的抑制噪声的过滤技术,并将每个IMU的传感器组织成姿态和运动方式节点. 鉴于IMU节点构成一个动态的多样化图,我们然后在图Fourier域内进行适应性过滤,以合并同质和多样化的节点信息。 此外,还采用了适应性波幅频率选择方法,以抑制上下文冗余和缩短特性长度。这种方法既加强了基于时间戳的图表汇总,也加强了长期背景的关联性。 我们的框架在傅里叶、图傅里叶和波浪域采用适应性过滤,从而能够实现有效的多传感器聚变和上下文关联。 对10个基准数据集的广泛试验表明,我们的框架表现优异。",
