    "direction": "信息安全",
    "summary": "从集中身份结构向分散身份结构的过渡,对用户数据的隐私保护带来了深刻的转变。 然而,随着分散身份的不断成熟,今天的在线服务仍然绝大多数依赖于建立在OpenID Connect(OIDC)之上的集中和联合身份管理解决方案,作为最广泛的解决方案. 因此,为了保护用户的个人数据,并保持遵守诸如《一般数据保护条例》等监管框架以及诸如电子识别、认证和信托服务等信托框架,确保保护隐私的OIDC部署至关重要。 然而,OIDC目前的生态系统缺乏一套连贯的隐私最佳现行做法(BCPs),并缺乏一项关于这些增强隐私特征在现实世界部署中被广泛采用的研究。 为此,这项工作在两个方面弥补了上述差距。 首先,我们提出一套结构化的隐私BCP,由OIDC官方规格和当前执行趋势产生,找出易于部署的增强隐私的特征,加强OIDC部署的基线隐私,而不改变协议或损害互操作性。 此外,碱性氯化石蜡还有助于实现GDPR的隐私原则,如数据最小化、保密和不相联。 其次,这项工作对野外的OpenID提供商(OPs)进行了全面调查,以查明私营和公共部门(即国家)OPs在保护隐私配置方面的差距。这项研究采用了一种双重方法:第一,在2022年进行了一次人工审查;随后,在2025年进行了一次自动化合规分析,对全世界10 000个业务方案数据集进行了调查。结果显示,私营业务方案缺乏加强隐私的特点,私营业务方案与国家业务方案之间差距很大,后者平均提供高得多的基线隐私。 我们还发现,普遍存在不遵守国际开发部规格的OPs,导致OPs配置不当,妨碍了互操作性,有时也妨碍了安全。该文件强调必须采用可采取行动的业务流程控制程序,以改善基线隐私,并表明需要有一个自动化框架,用于在OIDC生态系统中持续进行隐私合规性评估。",
