    "summary": "人类活动识别(HAR)越来越多地在微控制器上执行,以满足隐私,耐久性和能量限制,然而大多数部署的TinyML模型在面对看不见的行为,放置移位,或感官异常时仍然保持封闭的设置和过度的自信. 我们提出Tuny-HAR,一个资源效率高的管道,它统一了一个内置的时序主干线,有一个蒸馏的信托头和一个轻量级的流线条。统一头部产生校准的班级概率,以及从教师信号(logits和原型机/Mahalanobis距离的能量)中吸取的紧凑的分数外分配(OOD)代位分数,而整齐层则保持微小的在device quantiles,以强制实施覆盖控制接受阈值. 当证据不足时,设备会弃置,并可能使用32–64D特征草图可选升级,避免原始信号传输. 根据关于UCI HAR、PAMAP2和WISDM的假期一主体协议进行了评估,这些协议具有多种OD压力(未见分类、安置转移、注入异常),TrustTiny-HAR在分配宏观-F1(如UCI HAR的93.8)上匹配了强整8基线,同时大幅度改进校准(ECE 2.4%)和OD稳健性(AUROC 0.96,未见的FPR@95 0.22,安置转移)。 作为一个选择性的分类者,它只从128-512个窗口的缓冲器中获得了90%的预期覆盖率,但风险是保守的(例如6.1%)。NRF52840/STM32L4上的系统剖面显示https://github.com/Ism-ail11/TrustTiny-HAR.",
