    "summary": "集群是机器学习和数据挖掘中的一项基本任务.深层学习的成功,特别是深层的基因模型,催生了下一代群集——以大规模高维数据群集能力为特色的深层无监督群集. 一个典型的例子就是高斯混合变异自编码器(GMVAE),其潜在变量的前身是高斯分布体(GMM)的混合物. 然而,GMVAE中手工给出的混合物号对最终集群性能有极大影响,也限制了新集群出现时的适应能力. 为了解决这个问题,我们提出一个无限高斯混凝土自动编码器(IGMVAE),用无限高斯混凝土分布来取代VAE之前的平原高斯混凝土. 我们的方法从数据中适应性地学习了混合物的数量,克服了GMVAE中人工设定的局限性,并动态地扩展了新类群.三个数据集的实验结果显示,我们提议的IGMVAE的集群精度比GMVAE高5.5~14.25%. 此外,我们的模型能够以完全不受监督的方式生成高质量的数据。",
