    "summary": "随着全球空气污染的恶化,空气质量预测受到越来越多的关注。spatiotemporal图神经网络因其能够捕捉空气质量指数(AQI)数据中复杂的空间和时间动态而成为领先的范式. 然而,由于长期时间依赖性模型化薄弱和气象因素整合不足,现有方法仍然受到限制。 根据全国范围公开的八年空气质量数据集,我们提议建立一个气象学-大气分解-瞬间演化网络,联合处理长时段模型和气象环境聚变问题。MADGCN包括一个基于Granger因果关系的动态因果关系发现模块,它捕捉了气象条件与AQI动态之间时间变化的因果关系.推断的因果结构进一步指导了一个因果图解模块和一个PatchMixer模块,使有效的空间互动模型和多尺度的时间依赖性学习成为可能. 针对16个强基线进行的广泛实验表明,MADGCN在长距离空气污染预测方面实现了竞争性的性能,并在高污染制度下得到了普遍应用。",
