    "summary": "神经网络的穿梭使得大型神经网络更加便携,较小的神经网络更容易被解释,而预测精度的丧失也最小. 我们提出一种推算方法,将神经元网络LASO问题作为标准加权回归或分类问题与LASO惩罚重构. 我们从一个密集的神经网络结构开始应用这个方法,这个结构包括所有可能的作为子网络的向导网络. 这有效地消除了大量冗余。 为了进一步完善网络,我们制定了第二个步骤,即对所有剩余链路进行循环,一次一次一次地进行循环,去除那些不能充分改进模式的链路。 我们在四项模拟研究中展示了我们处理回归和分类问题的方法的有效性和稳定性。 我们的方法与最初的密集神经网络相比,以及采用最先进的神经网络推波助澜的方法,提高了预测性和可解释性. 我们的方法在10个真实的数据例子(5个回归和5个分类)中也超过了最先进的方法。",
