    "direction": "信息安全",
    "summary": "分散金融(DeFi)的迅速增长推动了创新,但也使区块链系统面临严重的安全威胁。 截至2025年11月,区块链安全事故累计损失已超过368.9亿美元.快速贷款袭击占报告案件的135起,在所有袭击方法中排名第四。现有的检测方法要么分析许多已部署合同没有的合同源代码,要么采用适合具体情景的交易模式,因此无法普遍应付多种多样的闪存贷款攻击。 在本文中,我们介绍了FlashShield,一个基于Hypergraph神经网络(HGNNs)的一般闪存贷款攻击检测框架. 我们构建了包含跨越多个链条的攻击和良性交易的全面数据集,并系统分析沿着四个DeFi协议层的闪存贷款攻击机制:代码执行,业务逻辑,经济机制,以及交叉协议交互. FlashShieldre代表每个交易作为传输动作和语义关系的超度图,并使用一个混合结构,将光谱,空间,原始特征与节点级别和图表级别表现结合在一起.实验显示,FlashShieldimproves对领先方法的回想起率达29%,并确定了43项先前未知的恶意或可疑活动(18项经证实的与闪存贷款有关的剥削和25项疑似地址中毒事件),表明其对于自动DeFi安全监测的有效性和可扩展性.",
