    "title": "Spatiotemporal Decoupled Learning for Spiking Neural Networks",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Neural Networks and Learning Systems",
    "year": "2026",
