    "direction": "人工智能",
    "summary": "Spiking神经网络因其具有促进节能人工智能(AI)的潜力而获得极大关注. 然而,对南方国家网络进行有成效和高效率的培训仍然是一个尚未解决的挑战。 虽然通过时间进行反射(BPTT)具有很高的准确性,但会产生大量的内存间接费用。相比之下,生物上可信的局部学习方法更具有内存效率,但难以与BPTT的准确性相匹配. 为了弥补这一差距,我们提议进行零散的脱钩学习(STDL),这是一种新颖的培训框架,将空间和时间的依赖性脱钩,为南方国家网络实现高精度和培训效率。 具体而言,为了实现空间脱钩,STDL将网络分割成较小的子网络,每个子网络都使用辅助网络独立训练. 为了解决空间脱钩导致子网络之间协同作用减少的问题,STDL通过在内存限制下从随后的网络层中选择最大的子集层,构建了每个子网络的辅助网络. 此外,科学、技术和工艺服务使相互依存关系跨时间步骤脱钩,从而能够有效地进行在线学习。 对7个静态和基于事件的视觉数据集的广泛评价表明,STDL一贯优于本地学习方法,并实现了与BPTT方法的可比较准确性,并大大降低了GPU内存成本.值得注意的是,在ImageNet数据集上,STDL比BPTT实现了4\\time$的GPU内存减少. 因此,这项工作为具有记忆效率的SNN培训开辟了一条很有希望的道路。代码见https://github.com/ChenxiangMA/STDL.",
