    "direction": "数据工程",
    "summary": "在城市道路网中传播的拥挤现象遵循潜在的模式,受到道路网物理地形的限制,并受到人类行动行为的影响。探索和利用这些模式可以为交通管理部门提供决策支持。 然而,现有方法通常假定产生独立的拥堵效应,忽略拥堵传播的相继影响,无法捕捉蔓延过程中的长期依赖性。 为了克服这些局限性,我们建议采用新的强化学习式拥堵传播模式采矿方法(称为GRL_CPP)。这种方法将拥堵传播正式化为马尔科夫决策过程(MDP),并使用强化学习算法持续优化决策,在拥堵传播序列中自动学习长期依赖性.借助强化学习的探索机制,GRL_CPP可以积极识别复杂交通环境中最具有歧视性的传播模式,同时避免不切实际的假设. 对现实世界和合成数据集的广泛实验表明,我们的方法大大超过了最先进的基线,在现实世界的双向拥塞分析中实现了超过41%的平均改进,在各种数据溅射假想中实现了74%的改进,在F1-分数中实现了真正的传播图重建。",
