    "summary": "K-意指一种强大的无监督的集群方法,用于定期结构化的数据,从根本上依赖于几何集群中心. 然而,将这一范式扩大到图表结构数据仍然具有挑战性。 我们提议采用“K图中心”——一种通过“图中心”来定义图群的新方法,即将图群内加权地形距离之和最小化的一维矢量。 我们引入了高效的电传动方案,以计算图表中心: 1. 通过正常的相邻矩阵来传播亲和性; 2. 通过逐行盘片化来强制实施垃圾邮件化.集群任务来源于交汇的图表中心,类似于K-意指.K-Graph Centers方法比传统的光谱法显示的计算复杂度和快速汇合速度要低得多.实验结果以通用指标验证其时间效率和集群性能。",
