    "summary": "深层基于学习的网络侵入探测系统(NIDS)的功效受到高质量标签数据的提供的严重制约. 在现实世界环境中,数据集往往受到混合标签噪声的影响——既包括闭合噪声,也包括开合噪声——这明显扭曲了决策界限,并导致先前未知攻击的临界安全缺失。 对已知的交通进行严格的分类,同时准确发现这种混合噪音带来的未知威胁,仍然是一项关键挑战。 在本文中,我们介绍了Sieve,这是一个强健的框架,旨在对混合噪声条件下的未知加密恶意交通进行精细的检测和分析.Sieve由三个协作模块组成:(一)一个有噪声的标签校正模块,使用邻接一致度量和基于信心的子集扩展来过滤混合噪声;(二)一个使用马哈拉诺比斯距离在纯洁,紧凑的特征空间中识别未知流量的后热检测模块;以及(三)一个未知的流量标签模块,利用半监督集群来方便数据集的有效更新. 对四个公共数据集的实证评价表明,Sieve在已知类别分类和未知威胁检测方面都大大超过最新方法。值得注意的是,在50%噪声条件下的Mal_TLS2023数据集上,Sieve保持强性能,精度和F1分数超过94%.进一步的理论分析证实了锡耶夫框架的优越性. 该代码可在:https://github.com/niebikong/Sieve查阅.",
