    "direction": "信息安全",
    "summary": "图像编辑方面的新发展对多媒体数据的可靠性提出了重大障碍,促进了对伪造图像探测的探索。复制移动伪造是一种流行的篡改技术,其定义是将一个图像的一个区域(源区域)复制到同一个图像的另一个区域(标区域). 因此,来源和被篡改的区域数据分布相同,对同时发现和区分它们构成巨大障碍。由于缺乏事先明确的限制,特别是在相同的数据分布下,现有的歧视性方法难以区分来源和篡改区域。 为了克服这一局限性,我们提出了一个新的基因框架,即PD2Net,它将这一任务拟订为以可学习的原型为指南的角色限制代表构建过程,从而能够对源头和被篡改的地区进行端到端的检测和区分。具体地说,采用了两个独特的原型作为源头和篡改区域的前身,并通过原型-特异性互动进行迭代优化,以逐步完善角色限制表述. 这种机制缓解了相同特征分布造成的困难,并使得区分更加稳定. 此外,我们提议采用疑似区域选择(SS)和疑似区域重新识别(SR)模块,通过消除假正像素,在原型指引下获得对象级精度目标. 对USC-ISI、CASIA v2.0和CoMoFoD数据集的广泛试验证实了我们在复制移动伪造图像检测和区分领域拟议框架的有效性和稳健性。",
