    "summary": "非正常的Theta波段(4-8 Hz)皮质振荡已被确认为阿尔茨海默氏病(AD)中的病理学标志,可以通过高频电刺激(ES)进行抑制. 然而,它们的神经起源和机械基础仍然鲜为人知. 在这部作品中,我们开发了一个数学模型来描述与AD相关的皮层切变特征. 通过生理模型的线性等效转化和描述函数分析,我们阐明了这些病理振荡背后的网络机制.结果显示,快速抑制性间神经元到金字塔神经元种群的突触抑制作用减弱,促使皮质网络形成病理低频(theta band)振荡状态.振荡频率和振幅可以从模型线性元件的Nyquist曲线与非线性元件描述函数的负反向曲线之间的交叉点直接确定.反之,由外部刺激驱动的这些曲线之间的分离可视化地代表刺激如何使皮质网络远离异常的Theta振荡.描述函数分析不仅为异常振荡提供了一种机械解释,而且能够准确预测抑制病态神学活动的有效刺激参数。这部作品为揭示AD的\"推拉\"网络效应提供了一个新颖的框架,提供了对皮质刺激机制的直观理解,以及优化AD神经调节策略的定量方法.",
