    "direction": "信息安全",
    "summary": "通过社交网络分享照片已成为日常生活的一部分。 然而,这种做法可能无意中导致侵犯隐私,特别是在未经照片中不知所措的个人同意的情况下,即称为未经同意的分享照片问题。现行战略,如互动计划和基于政策的机制,往往无法有效确定照片中的个人是否在知情的情况下被捕获。 为了解决这个问题,我们提议Perspicio,一个在用户的图像被无意捕捉时保护用户隐私的新系统.Perspicio不仅确保增强隐私,而且准确检测照片中捕获的个人的不知情情况。 为此,首先综合了个人身份识别的更具体特征,并引入了动态加权法,根据不同情景和个人特征调整这些特征的意义. 第二,它利用一项新的协议,既加强授权,又与更高一级隐私分享。 最后,我们进行了广泛的评价,并表明它取得了出色的业绩。与识别照片中未识别个体的先进水平相比,珀斯皮西奥将预测精度提升了高达13.2%,同时在在线和离线阶段分别加快了862×和1,425×的处理速度.",
