    "direction": "人工智能",
    "summary": "图形神经网络(GNNs)经常与异构图(heterophilic graphics)发生斗争,相邻的节点在现实世界网络中往往有不同的标签——一种常见的情景.本文通过一个称为ConSM(基于信任的子图匹配)的两阶段框架来解决这一限制. 首先,我们引入了一个信心感知子图匹配模块,通过利用最佳迁移来比较2-hop邻里的结构相似性来估计边缘系数.这一进程根据可捕性信任比率确定与任务无关或误导性的边缘。 其次,我们将这些边缘系数纳入一个信号-意识标签传播机制中,这种机制因地制宜地鼓励或阻止基于边缘信心传递的信息,从而增强GNN在异性条件下的稳健性。与我们之前的会议版本[1]相比,本手稿提供了(一)更清楚地说明基于子图的推理等关键设计选择,以及使用2-hop的邻里,(二)在不进行人工搜索的情况下调和置信率的适应策略,(三)涵盖近期异性导向基线和更大,无渗漏数据集的广泛的新实验.经验结果显示,ConsM可以提高分类精度,缓解过度流畅,在同位素和异位素制度上仍然有效.",
