    "summary": "多式联运数据的指数增长促进了多式联运分类技术的显著进步。 大多数多式联运分类算法将不同模式的信息汇总为统一的表示,以获取整体信息. 然而,现有的聚变机制过度依赖高质量的数据,这损害了模型的稳健性. 同时,聚变过程可能由于固有的模式差异而导致模式特定信息的丢失. 在这项工作中,我们提出了一种值得信赖的循环渐进聚变方法,用于多式联运分类,命名为TCPFMC. 为了增强稳健性和减少对高质量数据的依赖,我们设计了一个模式能量分数,以评估每种模式的信心,量化模式的信息性。 此外,为了高效整合模式特定信息,我们提出一种新型的循环渐进式聚变方法,将模式信息结合到精细分量的水平,提高模式的整体性能. 对六个多式联运数据集的广泛实验表明,TCPFMC的绩效超过了最先进的方法。原始代码见https://github.com/aoli-hrbust/TCPFMC.",
