    "direction": "数据工程",
    "summary": "联邦学习(FL)是一种以隐私为动机的对深层学习模式进行分布式培训的范式,因为它使大量客户能够合作训练一个共享的全球模式,而无需集中他们的私人数据. 自其以Fond Averaging为首个服务器聚合算法的首发式以来,许多FL算法被提出来提高性能. 然而,这些算法很少在相同的开源框架和控制配置下进行基准和比较,其性能主张在公平和可复制的研究中可能难以证实. 在本文中,我们评价在同一开放源码基准框架中整理的、具有代表性的FL算法集,以便以可复制的方式公平地比较这些算法。 为了实现这一目标,我们提出Plato,这是我们从零开始设计和实施的开放源代码FL研究框架.与Plato一起,我们评价和比较跨越:(1) 服务器聚合;(2) 客户培训定制;(3) 在同步和同步环境下选择客户;(4) 个性化联合学习;以及(5) 通信效率和有效载荷处理。 在各种试验设想(任务、客户群和数据分布)中,我们报告调查结果和实际见解,包括不认真报告可能导致误导性结论的陷阱和困惑因素。 在我们的统一实验设置和时间模型下,随机选择客户的联邦分析仍然是强有力的基线,往往与更复杂的替代品具有竞争力。",
