    "direction": "数据工程",
    "summary": "空间时空轨迹载有识别信息,容易发生侵犯隐私事件。现有研究主要集中在空间领域。时间方面仍然没有得到充分探讨,隐私风险得不到解决。本文通过引入新的轨迹比对模型ST-ATT来强调这些风险,该模型利用了关注增强的长期短期内存(LSTM),以有效捕捉轨迹中的时空关联.ST-ATT在识别类似轨迹方面表现优异. 为了防范连结攻击斯皮提奥-时空轨迹, 包括ST-ATT等先进模式, 我们透露,每个空间点的隐私预算和侵犯概率明确取决于较早的时间戳。隐私预算可以灵活地在空间和时间领域之间重新分配,而不损害总体隐私。 这种机制符合DP,即使由于扰动而重新排列时的spatio-timperal 点.实验显示,ST-ATT能够准确识别受现有DP方法扰动的溅射-时空轨迹,仅将噪声添加到空间域.拟议的Spatio-temporal DP机制抵制ST-ATT,强调需要考虑Spatio-temporal关系,以确保Spatio-temporal轨迹中强有力的隐私保护.",
