    "summary": "虽然光谱图神经网络(GNNs)在理论上在光谱域中是有根据的,但它们对多诺近似性的实际依赖意味着与空间域有着深刻的联系. 由于以往的研究很少从空间角度对光谱GNN进行考察,因此其空间领域可解释性仍然难以捉摸,例如,空间领域的光谱GNN基本上编码了哪些信息? 在文章中,为了回答这个问题,我们调查了光谱过滤和空间聚合之间的理论联系,揭示了一种内在的相互作用,光谱过滤隐含地将原始图引向一个经过调整的新图,明确为空间聚合计算.理论调查和经验调查都表明,经过调整的新图表不仅显示不所在地,而且还包含签名的边重,以反映各节点之间的标签一致性。 这些发现突出了光谱GNN在空间领域可解释的作用,并激励我们重新思考超出固定顺序多诺米的图谱滤波器,这限制了有效的传播范围,阻碍了它们捕捉远程依赖的能力. 根据理论结论,我们重新审视最先进的光谱GNN,并提出一个新的空间适应性过滤框架(SAF),该框架通过光谱过滤利用经过调整的新图表进行辅助性非局部聚合。值得注意的是,我们的苏丹武装部队从全球角度全面模拟了节点的相似性和差异性,从而缓解了与长距离依赖和异形图有关的全球无核国家长期存在的缺陷。13个节点分类基准的广泛试验表明,我们提议的框架优于最先进的方法。",
