    "summary": "高斯工艺(GP)是非参数模型化的强大工具,但其对外部器的敏感度限制了其对具有重尾的数据分布的适用性.学生-t工艺(TPs)为重尾模制作提供了强有力的替代方法,但它们缺乏GP对实际应用所必需的大数据集的可扩展性发展. 我们提出的是零星的变异贸易点,这是第一个将稀有的诱因点方法延伸至贸易点的原则框架。 我们开发了两种新颖的推论算法,即SVTP-UB和SVTP-MC,具有理论保证,并得出一种自然梯度优化,利用多变量学生-t分布的费舍尔信息矩阵与β函数(\"β链接\")之间先前未使用的连接. 关于UCI和Kaggle数据集的实验表明,当数据含有异常值和重尾巴时,SVTP显著超过稀疏的GP,在保持超过20万个样本的数据集的计算效率的同时,实现了高达3\\时间的快速汇合和40%的低预测误差.",
