    "direction": "信息安全",
    "summary": "垂直联邦式学习(VFL)允许多个方面合作训练模型,同时保持其局部特征的私密性,但其抵御后门攻击的坚固性仍然不为人所知. 为横向联合学习而开发的现有后门技术基本上不适用于VFL,因为VFL中的对手无法访问标签,并且严格限于在服务器侧监督下操纵本地特征表示. 这提出了一个根本性的问题:在这种限制下,在VFL能否发动有效和隐蔽的后门攻击? 在本文中,我们通过探索输入空间和潜伏空间中的攻击表面,对VFL的后门攻击进行系统调查. 我们首先提出一个输入空间攻击,利用在训练期间交换的梯度信息来潜伏本地输入并重塑输入-标签相关性,从而绕过无法访问的标签而不依赖于代号模型. 然后我们设计一种潜在的空间攻击, 对抗性地引导本地嵌入物向目标级的表示。 为确保实际的不可察觉性,我们把统一的隐蔽规范化战略纳入框架。 为了量化这一属性,我们采用了一个针对VFL的计量标准,衡量统计一致性,指导攻击效力和可探测性之间的权衡。广泛的实验表明,我们的攻击取得了很高的成功率,但仍然难以发现,暴露了VFL系统以前被忽视的安全弱点。",
