    "pdf": "papers/incremental_755ac0cc987a.pdf",
    "link": "https://doi.org/10.1109/tai.2026.3666170",
    "direction": "人工智能",
    "summary": "大型语言模型(LLM)使自然语言处理领域发生了革命性的变化. 然而,它们显示出一些局限性,包括缺乏可靠性和透明度:它们可能会产生幻觉,无法提供支持生成的产出的来源。采用了检索增强型生成(RAG),以解决有限责任公司中的这种限制。 一个受欢迎的实施工作,即RAG-as-a-Service(RaaS),存在阻碍其通过和获得的缺陷。 例如,RaaS的定价是基于提交的提示数,而不考虑提示是用相关的块来丰富,即从矢量数据库中检索到的文本片段,还是利用的块的质量(即相关性的程度)。 这导致支付模式不透明,成本效益较低。 我们提议以Chunk-as-a-Service(CaaS)作为透明和成本效益高的替代办法。CaaS包括两个变体:开放预算CaaS(OB-CaaS)和有限预算CaaS(LB-CaaS),这是由我们的“通用成本在线选择算法(UCOSA)”所允许的。UCOSA进一步扩展了OB-CaaS变式的成本效益和可获取性,通过在线方式,根据预算限制和公用事业成本权衡,丰富了所提交的提示的子集。 我们的实验表明,拟议的UCOSA与线下和相关性优异的选择基线相比,是有效的。 就业绩衡量标准而言,浓缩提示数乘以平均相关性(AR)-UCOSA,随机选择的成绩大约为52%,离线选择方法的成绩达到75%左右。 此外,就预算利用情况而言,与拉萨相比,LB-CaaS和OB-CaaS的绩效与预算比率分别为140%和86%,表明其效率较高。",
