    "direction": "信息安全",
    "summary": "车辆与路边单位之间经认证的关键协议(AKA)是保障车辆临时网络(VANET)安全的基本组成部分。 然而,大多数现有的AKA计划依赖于传统的密码原始,如离散对数和大整数因子化,使其易受新出现的量子攻击. 虽然有人提出了几个基于latice-hard问题的量子后解决方案,但它们严重依赖一个集中的可信赖的权威,使得它们面临单点失败的风险. 为了解决这些问题,我们建议根据环向错误学习(RLWE)和不同步小整数解决方案(ISIS)问题的安全假设,建立一个权力下放的认证关键协议计划。拟议的计划在维护通信实体隐私的同时,对量子对手实现了强烈的抵抗. 此外,还采用了基于门槛的投票机制,以减轻网络基础设施内固有的关键暴露问题。 通过在多个边缘服务器节点上分配认证权限,该计划大大提高了系统强性,防止单节点故障和串通攻击.综合安全分析和业绩评价表明,拟议办法满足了各种安全要求,并提供了可接受的计算和通信间接费用,从而证实在现实世界的VANET环境中部署该办法切实可行。",
