    "summary": "检索-增强生成(RAG)服务通过动态检索外部知识来源的相关信息,解决其在处理最新知识或特定领域知识方面的局限性,加强了LLMs. 在云内LLM服务范式的制约下,许多现有的RAG系统通常部署在云环境,依靠从用户或第三方知识提供者的本地数据集检索原始信息来增强生成能力. 然而,这些基于云的RAG服务往往忽视了知识库对隐私和知识产权的重大关切,在部署或推论期间可能泄露敏感信息。 为了应对这些风险,我们提议通过云为基础的RAG的代理知识建立隐私保护框架(PIRAG)。核心思想是用精心设计的隐私保护机制将检索信息的原始数据压缩为代用知识表示. 我们首先建议建立一个知识构建机制,使代理表述与LLMs的语义空间保持一致,以保持效用. 然后我们开发一种以查询为中心的知识表现方法,并采用有针对性的培训策略,有选择地排除无关内容,进一步减少隐私敏感内容的曝光. 我们进一步制定差异性隐私强化合作推论战略,以确保整个框架具有可认证的保障。 对7项公共基准和4项LLMs的广泛实验表明,PriRAG在公用事业和隐私之间实现了有利的平衡,在保持高质量生成的同时大大减少了隐私风险.",
