    "summary": "最近的研究根据出处图提出了APT检测方法. 然而,由于大规模图表,现有系统面临挑战,导致内存消耗量大,效率有限. 许多数据集只提供预处理数据,而不披露日志采集和属性映射,阻碍了可复制性. 一些方法依赖于商业的EDR或高质量的威胁情报,限制了真实世界的采纳.为解决这些局限性,本研究提出一个基于图表关注网络的APT检测框架,并进行光谱特征改进.框架使用Sysmon日志,并整合了MITRE ATT&CK技术与开源Sysmon过滤规则匹配,以构建Rule-Filtered Provenance Graphs(RFPGs),在保留与安全相关的语义的同时缩小了图表大小.文字属性和数字属性被编码为统一的节点和边缘表示,用于模型化的系统实体和相互作用. 然后采用光谱精细的GAT模型进行恶意节点检测,并采用Interval Bias机制,在可控精密比对下调整检测灵敏度.实验结果显示,拟议的系统实现98.25%的精度,90.58%的精度,以及0.36%的假正率.与基准模型相比,它将推论时间减少至10.8%,GPU内存消耗减少11.4%.模型推论需要0.82秒,而整个管道需要约5秒.",
