    "summary": "智能交通系统(ITS)使用先进技术,提高驾驶员,乘客,行人的安全性,机动性和交通效率.车辆专用网络(VANET)是信息技术系统的核心组成部分,使车辆之间能够进行实时通信。 然而,确保VANET安全仍然是一个关键的挑战,因为恶意行为会直接影响乘客的安全和系统可靠性. 最近的研究探索了基于机器学习(ML)的不良行为检测,主要依靠监督的方法,这些方法需要大量贴标签的数据,而这些数据在实际操作中成本高昂且难以获得.半监督学习通过利用标签数据和非标签数据,提供了一种实用的替代方法。 在这项工作中,提出了针对VANET不当行为检测的适应性半监督自我培训框架. 该方法包含适应性信心阈值机制和超参数优化,以提高不同数据条件下的学习稳定性. 对VeRemi数据集的评价表明,拟议方法,特别是XGBoost方法,在最初未贴标签的数据的不同比例上,不断提高准确性、精确性、召回率和F1-分数。研究结果进一步表明,在低标签情景中,业绩良好,在中高比例的无标签数据中观察到最显著的成绩。 这些调查结果突出表明,拟议的方法对于实际世界车辆安全应用来说是有力可行的。",
