    "summary": "分布式联邦学习(DFL)将单服务器地形学的联邦学习扩展到更广泛的基于图表的协调设置,其中可能包括多个相互作用的汇总节点,在一些部署中还包括外部分布的培训资源. 虽然这种更广泛的地形提高了可伸缩性和灵活性,但也扩大了参与者、聚合物、通信渠道和执行资源的中毒攻击表面。本文介绍SecurityDFL,是抗毒DFL的防御深度框架.SecurityDFL整合了经认证的通信,基于添加式同位素加密的受保护聚合,信任感管弦乐,多点验证,以及资源映射在统一系统设计下的强化-学习突变. 因此,这项工作的贡献在于综合安全架构及其以图表为基础的DFL的端到端执行,而不是引入独立的密码原始。 关于基准数据集的实验、七种威胁模型对齐的中毒情况、减速研究、以及一个原型库伯内特斯试验床显示,SecureDFL在攻击中保持了强大的模型性能,并大大改善了攻击相对于所评估基线的抗御能力,在报告环境中,攻击成功率减少了98.5%,只增加了少量的间接费用。 这些结果支持了拟议架构的实际可行性,而手稿则明确划定了目前关于全面串通分析、串通信任操纵、极其不同的非IID条件和充分适应性多阶段攻击的限度。",
