    "summary": "新兴的大型模型在自然语言处理和计算机视觉领域取得了显著进展. 然而,神经视频编码的大型模型仍未被探索. 在本文中,我们尝试探索如何构建大型神经视频编码模型. 基于一个小基线模型,我们逐渐扩大它不同编码部分的模型尺寸,包括运动编码器-解码器,运动py模型,上下文编码器-解码器,上下文 en模型,以及时间上下文挖掘模块,并分析模型大小对视频压缩性能的影响. 然后,我们探索使用不同的架构,包括CNN,混合的CNN-Transformer,以及变形器架构,来实施神经视频编码模型,并分析模型架构对视频压缩性能的影响. 根据我们的探索结果,我们设计了第一个具有超过10亿参数的神经视频编码模型——NVC-1B.实验结果显示,我国大型车型比近期最先进的神经视频压缩车型,实现了显著的视频压缩性能改进. 随着硬件的不断进步和大型模型在设备上的成功部署,我们预计我们提出的大型神经视频编码模型可以将视频编码技术带入下一个层次.",
