    "direction": "人工智能",
    "summary": "热摄影对军事和监视摄像头的其他使用者特别有价值。 一些基于神经辐射场(NERF)的近期方法被提出来从一组热和RGB图像中重建3D的热场景. 然而,与NERF不同的是,3D高斯电镀(3DGS)因其快速训练和实时渲染而占上风. 在这项工作中,我们提出热Gausian,这是第一个能以RGB和热模式渲染高质量图像的热3DGS方法. 我们首先对RGB相机和热相机进行校准,以确保两种方式都准确对齐. 随后,我们用注册的图像来学习多模式的3D高斯人.为防止任何单一模式的过度调整,我们引入了若干多式联运正规化的制约因素。 我们还根据热法的物理特性,发展出滑动的制约。 此外,我们贡献了一个名为RGBT-Scens的实世界数据集,它被手持的热红外相机捕获,促进了未来热场重建的研究. 基于热古西安,我们进一步引入热古西安++,以提高热古西安的对齐性和分辨率. 为了改进多式联运的协调统一,我们设计了一个多式联运组合优化模块。 这个模块能够直接处理不匹配的多模式图像配对,减少每次使用前的专业校准需求. 为了提高热分辨率,我们还提议采用多式联运联合超分辨率重建模块,以提高低分辨率热场的质量。 此外,我们提供一个新的数据集:RGBT-Scenses++,提供分辨率更高的热映像. 我们进行全面的实验,证明热Gausian++实现光现实化的热渲染,提高RGB渲染质量. 它大大加强了协调性和解决能力,使实际部署得以更好地进行。 此外,我们的多式联运规范化限制降低了该模式的储存要求。将发布代码和数据集。",
