    "summary": "智能合同中的累犯脆弱性(RVs)对区块链系统构成严重的财务风险. 虽然以学习为基础的深层检测方法显示有希望,但它们受到一些重大限制:(1) 易受对抗性实例的影响;(2) 跨功能性房车处理不当;(3) 依赖有限的培训数据。 为了应对这些挑战,我们提出了SCAEG,这是第一个专门为RV检测设计的对抗性实例生成框架.SCAEG引入了5个新颖的扰动动作,这些动作保留了代码功能,同时暴露了模型的弱点,包括对CFRV情景的定向修改. 我们的全面评价表明,SCAEG生成的例子严重降低了先进探测器的性能(例如,将AWDN的准确度降低27.51个百分点),使其易受对抗性攻击。 基于这些洞察力,我们提出了VoteRD,一种通过多模式投票机制,将语义,规则,位置特征相结合的综艺检测模型.实验结果表明,VoteRD取得了优越的稳健性,在召回率中比现有方法高3.7%,在F1-分数中比7.4%(与AWDNN比较),同时有效检测传统RV和CFRV。这项工作不仅提高了RV检测能力,而且还为评估智能合同安全分析中模型稳健性确定了新的基准.SCAEG和VoteRD形成一个协同框架:SCAEG系统评价模型稳健性,而VoteRD则利用对抗性的洞察力来提高检测的准确性. 我们的数据集和工具已公开发布,以支持今后在对抗性测试和脆弱性检测方面的研究。",
