    "direction": "信息安全",
    "summary": "网络安全在各组织中日益重要。 许多数据违反和成功的网络攻击发生在员工忽略,绕过,或者不一致地应用安全规则时. 虽然现有的研究侧重于个性特征来解释遵守信息系统安全政策(ISSP)的情况,但在很大程度上忽略了特定领域的行为动机调控. 然而,持续努力和有时不方便的安全做法不仅取决于稳定的个性特征,而且还取决于雇员如何积极调节他们在这一领域的行为,这突出表明在解释ISSP遵守意图时需要考虑这两个构思。 本研究报告通过使用人格和自决理论的五要素模型来研究特征和独特的动机性与国际空间站遵守意图之间的关系,解决了这一差距。 在一次跨部门在线调查中,来自中小企业的218名办公室雇员报告了他们的个性特征、与安全相关的工作动机以及ISSP合规意图。 我们利用确认因素分析,测试了经调整的动机措施的多层面结构,并通过潜在特征分析,确定了质的截然不同的动机特征。 为了审查结构特征、个性特征和动力特征对ISSP合规意图的增量贡献,我们进行了分级多重回归分析。 结果支持一个多层面的激励调节结构,并产生了三个特征,这些特征在追求内在化目标的自我调节行为范围上各不相同.结构特征(公司规模)和个性特征(同意性,自觉性)与ISSP遵守意图(R2 = 0.257)有很大关联.动机剖面图造成额外差异(XQR2 = 0.08;最后R2 = 0.333),自主剖面图(即具有内部化和自我认可的安全行为理由的剖面图)报告ISSP遵守意图高于动机剖面图。 基于这些研究结果,研究报告概述了基于特殊和差别待遇的干预措施如何能够支持雇员对自主性、能力和社会关联性的心理需求,从而促进更加内化和持久地遵守ISSP。",
