    "summary": "广义的学习系统(BLS)最近作为深神经网络的一种有希望的替代办法出现,通过随机加权分配和假反向培训,提供了可比较的预测准确性,并大幅降低了计算成本。常规的BLS尽管效率很高,但还是受到一个关键的限制:它平等对待所有训练样本,使其对外星高度敏感,标签噪声,以及阶级失衡,现实世界数据中普遍存在的挑战. 为了克服这些缺点,我们提出了一个新的框架,即基于类概率的钟形BLS(CPBS-BLS). 在CPBS-BLS中,每个样本通过以类概率和不平衡率为共同条件的钟形权重函数被分配到适应性会籍值. 这种机制自动强调密集区域的可靠样品,同时抑制稀疏区域外部和噪音点的影响,从而形成更坚固的决定边界。 虽然CPBS-BLS在单景环境中大大提高了稳健性,但其对单一视角的依赖限制了其捕捉复杂多面数据中存在的互补结构的能力. 为了解决这个问题,我们通过引入基于类概率的钟形多视图BLS(CPBS-MvBLS)来进一步推进框架.CPBS-MvBLS在保留适应性权重计划的同时整合了数据的多种观点,使模型能够利用跨越不同特征空间的互补信息. 这种对样本可靠性,类失衡,多视图一致性的联合处理,代表了BLS范式中一个新的进步. 我们提供严格的理论分析,确定CPBS-BLS和CPBS-MvBLS的通用界限,保证其可靠性. 对UCI、KEEL和AwA基准数据集的广泛实验表明,我们的模型在准确性、强力到噪音以及处理不平衡类别方面一直比最先进的基线要好,通过统计意义测试得到了验证。拟议的CPBS-BLS和CPBS-MvBLS模型的源代码可见于https://github.com/mtanveer1/CPBS-BLS.",
