    "summary": "电镀镁炉(EFMF)的工艺操作性能评估对于确保产品质量和追求最大的全面经济效益非常重要。 然而,新生产流程开始时的数据没有性能等级标签,往往包括新的性能等级.传统的多源域开放设置域适应(OSDA)方法将所有未知的类都归类为一个类,而无需进一步细分. 为了解决这个问题,研究一种基于多源域开放-设置深层转移对抗网络(MDODTAN)的方法,以解决EFMF的POPA问题,它侧重于将多个未知的类别细分为不同的未知性能等级. 这个网络为每个源域设计了一个任务分类器,已知性能等级的评估精度进一步提高. 然后,通过多源域对抗训练,缩小每个源目标域已知的性能成绩等级之间的域间差距. 通过构建已知和未知性能等级的相似性矩阵,给目标域数据分配了伪标签,通过迭代培训,提高了新冶炼工艺性能等级的评估精度.实验结果显示,与现有方法相比,我们的方法在开放式设定的情景中实现了更高的性能评估精度,同时也准确分类和分化了多个未知性能等级.",
