    "direction": "人工智能",
    "summary": "• 我们采用了一种心理物理学启发的方法来探究对多式联运大型语言模型的看法——我们利用即时心理测量函数来估计MLLMs的对比敏感功能——我们显示各模型的CSF形状和规模大不相同,与人类的愿景不同——我们揭示模型和CSF估计对迅速措辞非常敏感——我们展示模型的CSF在过滤和对抗噪声下预测分类稳健性,了解多式联运大型语言模型处理低水平视觉特征对评价其知觉能力如何至关重要,没有系统地定性。 在人类心理物理学的启发下,我们引入了一种行为方法,通过将MLLMs作为端到端观察者来估计对比感函数(CSF).以结构化的提示询问模型,同时在特定的空间频率上查看基于噪声的刺激。心理测量功能来源于二进制的口头响应. 因此,对比阈值(和CSF)是在不依赖内部激活或基于分类器的代词的情况下获得的,与之前关于人工网络的报告不同. 我们的结果显示,有些模型在形状或规模上与人类的CSF相似,但没有一种模型捕捉到两者. 我们还发现,CSF估计对即时措辞高度敏感,表明语言稳健性有限. 最后,我们显示CSFs预测在频率过滤和对抗条件下的模型性能. 这些调查结果突出表明了在对微额供资和微型企业的频率调整方面的系统差异,并将这种国别服务框架估算确定为可扩展的多模式感知诊断工具。",
