    "direction": "人工智能",
    "summary": "团队的悬殊奖励严重阻碍了在合作多剂强化学习(MARL)中学习最佳团队政策. 虽然用个人奖励来增加人数不多的团队奖励是一个共同的解决办法,但现有方法面临着三个关键的挑战:(1) 由于奖励职能的改变,学到的政策与最佳团队政策不一致;(2) 与不同的个人奖励环境不一致;(3) 个人和团队奖励政策优化之间没有最佳的平衡。 为了应对这些挑战,我们提议采用新的政策一致性限制多种代理政策优化办法,以奖励方式利用个人奖励。具体地说,我们首先提出一个有限的政策优化问题,其原因是团队对所学到的政策的回报与最佳团队政策的一致性制约。 然后,我们制定拉格朗日双重政策优化程序,以解决既定问题,为政策培训提出精确的优化目标。在整个过程中,提出了动态拉格朗日乘数更新机制,以自动平衡个人和团队以奖励为导向的政策优化.横跨StarCraft II多剂挑战方案、多剂粒子环境(MPE)和Google研究足球环境的广泛实验评价表明,我们的方法有效地应对了所有三项已查明的挑战,大大提高了合作多剂方案的业绩,使团队获得的回报很少。",
