    "summary": "无盒模型水印是保护深层学习模型的知识产权的一种新兴技术,特别是用于低级图像处理任务的模型.现有工作在几个方面核实并改进了效力。 然而,在本文中,我们系统调查了脆弱性,并表明无箱模式水标记容易被移除攻击,即使在现实世界的威胁模式下,保护模式和水标记提取器都装在黑匣子中. 在这一背景下,我们进行了三项研究。1)我们开发一种萃取器-梯度-导解(EGG)除尘器,并在萃取器只使用ReLU激活时显示其有效性.2) 更一般地说,对于一个未知的提取器,我们利用对抗攻击,并根据估计的梯度设计EGG清除器.3)在提取器无法进入的最严格条件下,我们根据一套私人代理模型设计了可转移的清除器.在所有情况下,拟议的去除器都可以成功地去除嵌入式的水印,同时保持处理过的图像的质量,我们也表明EGG去除器甚至可以取代水印.广泛的实验结果验证了拟议攻击的有效性和普遍性,揭示了现有无盒方法的弱点,并呼吁进一步研究。",
