    "summary": "空间填充曲线(SFC,简称SFC)被广泛应用于索引多维数据,它首先将数据映射到一个维度,然后是一维索引方法,如B树索引映射的数据.现有的SFC对整个数据空间采用单一的映射方案. 然而,单一的绘图方案往往不能在所有数据空间上发挥良好作用。 在本文中,我们提出一种叫做片式SFC的新型SFC,对不同的数据子空间采用不同的映射方案.具体地说,我们提出了一个名为Bit Merging树(BMTree)的数据结构,可以同时生成数据子空间及其SFC,并实现SFC对整个数据空间的可取属性. 此外,我们开发了一个基于强化学习的解决方案,以建设BMTree,目的是实现出色的查询性能. 为了在数据和(或)查询的分布发生变化时有效更新BMTree,我们开发了一种新机制,以快速检测数据和查询的分布变化,并使BMTree的部分再培训成为可能.重新培训机制有效地提高了业绩,因为它避免了从零开始对BMTree进行再培训。广泛的实验表明,BMTree采用拟议的以学习为基础的方法是有效的。",
