    "summary": "井木仪器持续测量井洞岩石的多个地球物理参数,为识别地下岩层提供了高分辨率观测数据. 最近,研究了基于半监督学习和转移学习的石英鉴定方法,以解决标签稀缺的广泛问题。 然而,这些方法只说明井(域)之间的分布差异,而忽略了井内的数据差异. 这可能导致井内错配的假标签不准确。 为了应付这些挑战,我们提出一种具有动态标签机制的双重对抗性适应方法,用于半监督的横井石英鉴定. 我们的方法利用域内对抗性学习,促进精细的类别对齐和域间对抗性学习,生成域无变量特征表示,从而减少井内和井间的数据差异. 此外,我们的方法引入了动态标签调整机制,以优化选择目标伪标签和源样本,从而增加可靠的监督信息,改进特征协调进程。实际井日志数据集的实验结果显示,当目标标签稀缺时,我们的方法可以实现有效的跨井液态识别.",
