    "summary": "在光谱图神经网络(GNNs)的设计中,聚诺图滤波器被广泛用作指导原则. 然而,它们依赖双向网络结构本身就限制了它们的能力。(1) 光谱GNNs往往会因多名顺序增加而出现过度流畅或过度挤压的问题.(2) 如果光谱过滤器背负培训图的一阶拉普拉西亚矩阵,而不是学习基本的高阶关系,则可能出现偏差。 为了解决这些问题,我们提议建立一个多飞行器聚合网络,在各种拉普拉西安事件矩阵上进行傅里叶扩展。特别是,MFFN将eigenvalue编码为具有简单复数的eigenvalue,以产生图中不同顺序之间的相互作用,超越常规对偶依赖. 随后,MFFN与傅里叶扩展和语义适应性面具的多个光谱滤波器相近,适应各种复杂的图示信号. 我们进行了广泛的实验,以证明MFFN能够学习任意的图谱滤波器,并在节点级和图级分类任务中实现优异的性能.编码和数据集见https://github.com/guoling327/MFNN。",
