    "summary": "强化学习(RL)在解决自主驾驶(AD)的决策和控制问题上表现出了出色的性能,这种性能越来越多地应用于各种驾驶情景中. 然而,驱动是一个多属性问题,导致在实现当前RL方法的多目标兼容性方面面临挑战,特别是在政策更新和政策执行方面.一方面,一个单一的价值评价网络限制了在复杂情况下的政策更新,同时限制了驱动目标。 另一方面,常见的单型动作空间结构限制了驱动灵活性,或者导致政策执行过程中的行为大起大落. 为此,我们提出一个多目标共解-批评(MoEC)RL方法,并配有多目标兼容AD的混合半缩写动作.具体来说,构建了先进的MORL架构,其中综艺-批评通过独立的奖励功能聚焦于不同的目标. 该架构融合了混合参数化的动作空间结构,生成的驱动动作既包含符合混合道路模式的抽象指导,也包含具体控制指令. 此外,还开发了一个支持混合行动的基于不确定性的探索机制,以更快地学习多种目标相容的政策。实验结果表明,在基于模拟器和基于HighD的数据集的多通道高速公路设想中,我们的方法在效率、行动一致性和安全性方面有效地学习了多目标兼容的AD。",
