    "direction": "数据工程",
    "summary": "在现实世界的信息检索设想中,处理数据不完全问题对于提供准确的相似性分数和确保下游任务的可靠结果至关重要。以往的类似矩阵补全方法旨在估计一个从不准确的半定值(PSD)中显示出正值的类似矩阵。 但是,如果最初的相似性矩阵为$S^{0}$exhibts私营部门司,这些方法是不够的。 在本文中,我们提出一个新的SMC框架,同时探索对称性,正半定性(PSD),低级属性,为相似性搜索任务提供准确有效的解决方案.具体地说,我们利用低级地产,在传统的SMC框架中引入一种高效的专门化的Cholesky指数化(CF)技术,通过规范化器实施. 它通过学习一个较小的因子化矩阵而不是整个相似性矩阵来提高计算效率. 此外,为了增强SMC的优化性保证,我们引入了一个新的低级矩阵属性,并设计了两个相应的规范器. 在这些精心设计的基础上,我们新的SMC框架首次在理论保障下确保效率和准确性。 因此,我们提出两个新的算法,即SMCFN/SMCRN,以实施SMC框架。理论分析验证SMCFN/SMCRN的效能和快速汇合速度.5个现实世界数据集的广泛实验验证了我们的理论分析: SMCFN/SMCRN实现高达42%的低RMSE(如0.34 vs.(见ImageNet的0.59)和比最新基线高15%的召回率,同时是所有基准方法中效率最高的。",
