    "summary": "在本篇文章中,我们对双向学习的非参数估计的通用性表现感到关切。现有作品大多要求假说空间为凸轮或VC级,损失为凸轮. 然而,这些限制性假设限制了结果在研究许多流行方法,特别是内核方法和神经网络中的应用性. 我们大大放松这些限制性假设,并用利普希茨连续双向损失的一般假设空间,确定经验最小化器的尖锐的预言不平等。举例来说,我们运用我们的一般结果来研究双向最小方回归,并得出一个超大的人口风险约束,与最小方回归的最小方程下方的最小方程匹配。关键的新颖之处在于构建一个结构化的深ReLU神经网络,以近似于真实的预测器,以及设计一个由具有这种结构和可控制的复杂性的网络组成的定向假说空间.实验验证了拟议方法的有效性。 这一例子表明,所取得的普遍结果确实有助于我们探讨对各种无法通过现有办法处理的问题的概括性表现。",
