    "summary": "本文介绍了自动选择软件保护的新办法,以减轻机器-At-End软件应用程序中关键资产的风险。 我们正式确定保护决策中的关键内容——包括密码文物,资产,安全要求,攻击,软件保护——并通过游戏理论启发的模型来设定保护过程. 在这个模式中,一名捍卫者从战略上对目标应用的各种密码文物适用保护,预期对手会一再试图攻击该应用的资产的保密性和完整性。选择最佳防御可以最大限度地抵抗攻击,同时通过限制防护措施引入的间接费用,确保应用程序仍然可以使用。游戏通过基于迷你最大深度第一探索策略的heuristic来解决,并辅之以动态编程优化以提高效率. 我们制定的核心是采用软件保护指数,这是通过使用软件衡量标准和专家评估来评估保护有效性,从而扩展现有能力和复原力概念的原始贡献。 我们通过实施概念证明和专家评价验证我们的方法,表明自动软件保护是减轻软件风险的一个实际有效的解决办法。",
