    "direction": "人工智能",
    "summary": "神经架构搜索(NAS)将神经网络设计自动化,比手动方法提高效率. 然而,有效发现同时优化多个目标的高性能神经网络架构仍然是NAS的一大挑战.现有方法往往因人口多样性有限和搜索空间探索不足而受到影响,特别是在具有极端复杂价值的区域。为应对这些挑战,我们提议采用一个多目标演化算法(MOEA)-BUS,这是一种基于两人口群的创新MOEA,对NAS进行统一的采样,旨在同时优化准确性和网络复杂性. 在MOEA-BUS中,提出了一种新的统一取样方法,以初始化人口,确保建筑在客观空间中统一分布. 此外,为了加强探索,我们部署了一个两个人口群框架,两个人口群在其中协同发展,促进搜索空间的全面覆盖。 在CIFAR-10和ImageNet上的实验显示MOEA-BUS的优越性,在CIFAR-10上达到98.39%的顶级速率,在ImageNet上达到80.03%的速率.值得注意的是,它在ImageNet上达到了78.28%的精度,只有446MAdds.差异研究证实,统一的抽样和人口两栖机制都提高了人口的多样性和业绩。 此外,在肯德尔的陶系数方面,SVM与其他三种常用的机器学习模型相比,实现了至少0.035的改进,统一的采样提供了约0.07的增强.",
