    "direction": "人工智能",
    "summary": "抽象方程式的发现传统上侧重于回归,目标是恢复模拟数字目标的分析表达. 在本文中,我们把这个范式扩展到二进制分类,并引入了分类的方程式发现(EDC),这个框架发现了简明的符号表达,明确定义了决定界限.EDC通过专门的数字程序搜索一个可配置的分析表达式语法,使用光束搜索和选择式方程式参数,生成一个单一的可解释方程式,其标志决定了类会籍. 我们设计了一种冗余意识的语法,它平衡了表达性和可牵引性,使得能够发现非线性决定边界,同时保持可解释性. 通过使用已知生成机制的人工数据集的实验,我们显示EDC可靠地重建了复杂的目标边界,包括XOR型和相互作用驱动结构,并在不断提高的噪音水平下有效适应.值得注意的是,在吵闹的环境下,EDC通过近似于隐含的,噪声变化的决定边界,可以超过原始生成方程. 在UCI基准数据集上,EDC一贯表现优于现有的象征性分类方法和其他可解释的基线,同时实现性能与最先进的黑盒模型的竞争力. 尽管在计算上比标准分类器要求更高,但我们表明,只要降低搜索深度和简化语法,在最小程度上减少预测性能损失,就可以实现实质性的加速.总的来说,电子数据交换提供了象征性回归与分类之间的原则性桥梁,为决定边界的解释性至关重要的应用提供了透明但具有表现力的替代黑箱模型。",
