    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tai.2026.3671218",
    "direction": "人工智能",
    "summary": "试管纤维化(AF)是最常见的持续心脏心律失常症,到2019年,全世界有近5900万人受到影响,中风风险大幅上升.这部作品呈现出一种新型混合式复杂进化网络,用于使用Gramian Angular Field(GAF)转换的心电图信号进行自动AF检测.拟议的方法通过格莱米安角聚变场(GASF)和格莱米安角差异场(GADF)的变换,将一维ECG片段转换成二维图像表示,在极坐标中保留时间依存关系作为几何关系. 我们提出的模型将GASF和GADF视为复杂价值投入中真实和想象的组成部分,通过将实际价值和复杂价值的演化层结合在一起的拟议混合结构,使相感特征提取成为可能。网络包含复杂的演化,修改的ReLU激活,以及剩余连接,以捕捉微妙的量相相互作用,对探测AF事件至关重要. 对包含1,436 ECG录音的PhysioNet AF数据集进行了评价,该模型以95.63%的测试精度,96.43%的精度,92.05%的回溯率,94.15%的F1-分数,以+1.52%的精度和+2.1%的F1-分数,取得了优异的性能.使用Grad-CAM和集成梯度(Integrative Grad-CAM)的可解释性分析揭示了类特异的注意模式,模型以GADF为主进行正常节奏检测,以GASF为主进行AF分类,展示了我们模型在临床上相关的模式识别能力. 为了便于复制和进一步研究,可在这一链接上公开实施拟议的C-AFNet以及相关的预处理和评价脚本。",
