    "direction": "人工智能",
    "summary": "学习网格代表对于许多3D任务都很重要. 由于每个顶点的邻居没有排列顺序,常规数据(即图像)的常规演化不能直接应用到 meshes上. 以前的方法使用异色滤波器或预定义的局部坐标系统或学习权重矩阵为每个模板顶点克服不规则性.学习权重矩阵,将顶点的邻居重新做成隐含的犬科顺序,是捕捉每个顶点的局部结构的最有效方法. 然而,每个顶点的学习加权矩阵会随着顶点数的线性增加模型大小. 因此,高分辨率的3D形状需要大参数,这对许多应用来说并不有利. 在本文中,我们为加权矩阵学习光谱词典(即基数),这样模型大小就独立于3D形状的分辨率.权重矩阵基数的系数以权重共享的方式从模板的光谱特征及其等级水平中学习. 此外,我们采用了一种适应性取样方法,直接学习分级绘图矩阵,以提高性能,同时又不增加推论阶段的模型大小。全面实验证明,我们的模型以更小的模型尺寸产生最先进的结果.",
