    "direction": "人工智能",
    "summary": "以图为基础的多视角深层群集最近成为突出的研究范式,其驱动力在于其对非线性特征关系的建模效果. 然而,现有方法中仍然存在两个关键限制:(1)它们非常容易引起噪音和冗余,这往往扭曲了图表构建过程;(2)过分强调跨视图特征的对齐无意中忽略了内在的跨视图异质性,从而有可能使各种观点的代表性趋同. 虽然遮掩机制可以缓解这些问题,但高遮掩比率对于在单一观点情景中产生歧视表述是必要的,但迫使基于图表的模型生成多样的视向特异性表述,而牺牲了显著的一致性损失,即对表达的表态的表态错位.为应对这些挑战,本文件提议采用双对角图-自动编码器学习(DCMGAL)进行多视角分组。DCMGAL包含了一个蒙面聚合模块,该模块通过随机化的边缘遮盖来放大视图间差异,同时抑制噪音和冗余. 它进一步设计了全球特征聚变机制,将双重关注网络与自我表达网络相结合,以获取各种观点的互补信息. 此外,还设计了一个双重对比性学习模块,通过交叉视图集群一致性学习加强集群层面的一致性,并通过本地地形保存学习维护本地地形结构,从而增强代表性的分离性。 最后,还纳入了一个辅助图重建部分,通过图解自动编码器架构保留必要的邻里信息,同时重建节点特征. 对基准数据集的广泛实验表明,DCMGAL的效绩大大超过最先进的集群方法.",
