    "direction": "人工智能",
    "summary": "早期抑郁症检测是公共卫生中的一项关键任务,使得自动抑郁症识别越来越重要.现有的多式联运方法面临着交叉模式情感不一致、微妙的情感提示提取和动态情感模型塑造的挑战。 为了解决这些问题,我们提议利用音频文本数据大力识别多式低压趋势网络(CEMTNet)。CEMTNet整合了三个模块:认知一致性推论机制(CCIM)根据估计的情感一致性动态调整聚变权重;情感调整结构化注意(EMSA)利用情感感知多头注意力增强精致的情感提示提取;以及对比情感趋势模型(CE-TM)将对比性学习与时间趋势模型结合. DAIC-WOZ和EATD-Corpus数据集的实验结果显示,CEMTNet的实验结果始终优于现有最先进的方法,达到了0.92的精度,F1分数为0.92,召回0.93.消化研究和案例分析进一步证实了拟议模块的有效性和稳健性。源代码可见于https://github.com/ghy-yhg/CEMTNet.",
