    "title": "Multistage PCA Whitening: A Robust Method to Dimensionality Reduction in Image Retrieval",
    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Neural Networks and Learning Systems",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "partial",
    "contentNote": "已完成本地开源模型英译中，六段式其余部分待人工全文核验",
    "doi": "10.1109/tnnls.2026.3669538",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tnnls.2026.3669538",
    "direction": "人工智能",
    "summary": "利用主要组成部分分析(PCA)生成紧凑和强健的特征表述对于图像检索任务至关重要。 然而,大多数现有方法都要求从辅助数据集中学习五氯苯甲醚参数,这不可避免地会增加计算成本并限制泛化. 为了解决这一问题,我们建议采用一种新的减少维度的学习方法,即多阶段的PCA白化(MSPW),用于图像检索。三个主要要点是:1)我们提议一种特征自学方法,以学习五氯苯甲醚白化参数。这种方法可以通过单值分解(SVD)和噪声扰动重建检索数据集的特征,从而消除对辅助数据集的依赖,缓解高维特征的性能退化; 2)与现有的单级维度降低方法不同,我们采用在线查询自学(QSL)方法,通过纳入查询特征来动态学习PCA参数,大大提高使用短维特征的检索性能; 3)我们通过使用维度权重来平衡各种不同特征的贡献,从而增强不同维度特征的强性.6个基准数据集的实验结果表明,我们的MSPW方法的绩效大大超过用于减少维度的现有最新方法。值得注意的是,我们使用4-D特性的MSPW方法在两个大型数据集的平均精度(mAP)方面可以比以往最佳方法实现10%以上的相对改进。",
