    "direction": "人工智能",
    "summary": "横向培训已被证明可有效增强网络抵御对抗性攻击的能力。 然而,常规AT依靠预先确定的固定扰动预算,在训练强力模型时受到一些限制. 第一,在不同能力不同的网络之间执行同样的扰动预算,导致自然和强力之间的强力差异程度不同,这偏离了强力网络的预期结果。 第二,由于扰动预算在整个训练中固定下来,因此攻击力无法适应模型不断发展的稳健性而适应规模. 这种不匹配往往导致对抗性强势性过度适应和进一步退化。 为了克服这些局限性,我们提议采用一种名为“强力辅助性辅助培训”的新技术。 在SAAT中,对手包含一种对抗-损失限制,以指导对抗性培训数据的生成。 这种制约使得扰动预算能够根据目前的训练状态进行动态的调整,这有效地缓解了强力的过度调整. 此外,通过通过对抗性损失明确调节攻击力,SAAT能够精确控制自然准确性和对抗性强度之间的强性差距.广泛的实验表明,SAAT大大改进了对抗力强于标准AT.",
