    "summary": "文本到图像(T2I)模型被广泛应用,生成跨越多个领域的高真实度图像. 然而,这些模型也可能被滥用,通过越狱攻击来制作不安全换工作的内容。现有的越狱方法主要操纵文字提示,使得基于图像的投入中的潜在弱点基本上没有得到探讨。 此外,基于文本的方法在绕过模型的安全过滤器方面面临挑战. 针对这些限制,我们提议采用Multimodule Decoupling attack (\\mathsf {MPDA}$), 即利用图像模式将原不安全的快报的有害语义成分分离出来. $\\mathsf {MPDA}$遵循三个核心步骤:第一,一个大型语言模型(LLM)将不安全的快报解为伪安全快报和有害的快报.前者似乎是可以绕过过滤器的看起来无害的子瞬间,而后者则是带有引发过滤器的不安全语义的子瞬间. 随后,LLM将有害的提示重写成自然对抗的提示以绕过安全过滤器,它引导T2I模型将底像修改为NSFW输出. 最后,为了确保生成的NSFW图像与原始的不安全提示之间的语义一致性,视觉语言模型生成图像标题,提供一条新的路径来指导LLM进行迭代重写,并精炼生成的内容.广泛的实验从经验上证明,$\\mathsf {MPDA}$在稳定扩散3.5和三种商业模型(CogView、Tongyiwanxiang和Midjourney)的两种攻击情景中,都超越了基线方法。具体地说,在以Midjourney为受害者模式的色情内容攻击情景中,我们的方法的绕行率比以前的方法高29%,从而提供了有力的经验证据,支持$\\mathsf {MPDA}$的有效性和通用性.免责:本文包含读者可能发现攻击性,令人痛苦,或令人不快的内容. 建议读者斟酌决定.",
