    "summary": "图表结构数据越来越多地生成并存储在分散化环境中,如社交平台,移动应用程序,以及边缘网络,用户在此保持对其本地图表数据的控制. 然而,为下游学习任务收集和分析这种分散的图表数据引起了重大的隐私问题,因为节点及其属性往往包含敏感的个人信息.本地差异隐私(LDP)已经出现,作为在不依赖信任的服务器的情况下进行隐私保存数据收集的有希望的解决方案. 尽管如此,现有的基于LDP的图表学习方法通常假设用户之间有统一的隐私要求,而忽略了现实世界系统中常见的多样化和个性化的隐私偏好. 这种统一处理导致数据收集阶段的噪音注入不灵活,导致图表数据严重失真,在随后的分析中实用性下降.为解决这一局限性,我们提议将PPGNN作为分散式图表数据的个性化差别私人框架。PPGNN 可以在本地扰动期间实现用户特定隐私预算,同时保留分析功能. 为了处理不同的隐私水平和噪声扭曲,我们设计了一个两阶段的解决方案,其中包括个性化的扰动机制(PPM)和加权校准策略(FlexProp). 对六个现实世界的图表数据集的广泛实验表明,PPGNN在分散的图表学习情景中有效地平衡了个性化的隐私保护和数据效用.",
