    "summary": "人类基因组中许多非蛋白质编码分数直接通过RNA发生作用,然而这些序列中编码的结构和功能作用仍然鲜为人知.应用深层学习受到缺乏的RNA结构数据的阻碍,目前还不清楚这些模型仅从丰富的RNA序列中直接恢复的生物制约因素是什么。 在这里,为了应对这些挑战,我们开发了NucleicBERT,这是一种自我监督的蒙面语言模型,从单个序列中学习没有进化信息的背景表现.解释性人工智能分析显示,模型将RNA序列组织在潜伏空间中,编码结构性质,表明生物上有意义的制约是仅从序列关联中得知的. 当对下游结构和功能任务进行微调时,NucleicBERT只需要单个序列,同时匹配或超过目前的RNA预测模型. 这个无对齐框架解决了附加注释的3D RNA数据的稀缺性,同时为实验技术提供了快速的计算补充. 通过将大量无标签的序列数据与稀缺的结构说明连接起来,NucleicBERT推进RNA结构预测,并告知大语言模型编码生物信息的程度.",
