    "summary": "多式联运遥感分类在资源探索和灾害监测等领域发挥着至关重要的作用。 然而,不同方式的噪音和冗余性往往阻碍有效特性聚变。现有方法主要依靠变形金刚和曼巴架构. 虽然基于变形器的模型受到高昂的计算成本和低效的远程依赖性模型的影响,但曼巴提高了效率,但仍然主要侧重于空间-时域模型,对频率域的探索有限. 这限制了组合表述的歧视性能力。 为了克服这些局限性,我们提议FA-Mamba,这是一个频率关注驱动的Mamba多式联运遥感分类网络。FA-Mamba以线性复杂性所确保的计算效率为重点,在有效抑制跨模式数据中的噪音和冗余的同时,以适应性的方式增强各模式之间的互补信息,使特性聚变更加稳健。 此外,为了有效获取全球背景信息,我们设计了一个协调聚变关注机制。 通过将空间提示沿不同方向进行整合,该方法纳入了不同模式之间的长距离关联。这有助于更全面地了解补充的多式联运信息。 在三个公共多模式遥感数据集上进行的广泛实验证明了我们的方法的有效性。与最先进的方法相比,FA-Mamba取得了优异的性能,总体平均精度达到95.84%. 我们的代码可在https://github.com/dnyee/FA-Mamba查阅。",
