    "summary": "超图神经网络(HGNN)擅长代表非欧几利得无限维空间内的复杂关系. 然而,传统的超图框架基于同源假设,在处理半监督分类任务中的异源问题时遇到挑战. 为了解决这个问题,本文首先分析了限制同源性超图的基本原因,并提出了异源性动态结构. 在此结构下,随后提议采用异构基动态HGN(HDHGN)进行半监督分类.HDHGN将高频图的三重模式迭代过程分解为两个因果相关的子程序,其中结合了关注机制,以促成动态互动. 为了评价HDHGN的效能,首先采用了相对的基于异氧的学位评价方法,随后对旋转翼和固定翼无人驾驶飞行器的两个现实世界飞行数据集进行了全面的断层分类实验,与11个最新方法进行了比较.",
