    "direction": "人工智能",
    "summary": "反向渲染是一个不合适的问题。先前的作品试图通过聚焦对象或场景形状或外观的前科来解决这个问题. 在这项工作中,我们侧重于自然照明的先验。 目前的方法依靠球形口琴照明或其他通用的表示,充其量在参数之前就是一个简单化的方法. 这导致在照明条件的表达性方面,特别是在考虑到光谱反射时,反向设置受到限制。 我们提出有条件的神经场代表,基于变异的自动解码器和变压器解码器. 我们把矢量神经元扩展到我们的建筑中, 直接建立等效性, 利用深度估计的洞察力 通过一个规模-不变量的丢失函数, 我们使高动态射程(HDR)图像得到准确的表达。 结果形成了一个紧凑,旋转-等效的HDR神经照明模型,能够捕捉自然环境图中复杂,高频的特征.将我们的模式培训为1.6 K HDR自然场景环境图的整理数据集,我们将其与传统表述作比较,显示其适用于反向渲染任务,并通过部分观测显示环境图的完成情况。",
