    "direction": "信息安全",
    "summary": "联邦学习(FL)是一种分布式机器学习方法,它允许多个客户在不分享本地原始数据的情况下合作训练一个全球模型. 尽管有这一优势,FL仍然容易受到会员推论攻击(MIAs)的伤害,这可能会损害联邦客户的会员隐私. 然而,当恶意客户不了解目标模式和良性客户的培训数据时,现有的多边审计机构表现出显著的性能退化。 在本文中,我们提出了一个新颖的计划,即毒性效应的瞬间演化(TEPE),在没有事先了解目标模型或良性客户培训数据的情况下,针对黑盒FL模型进行MIA.具体来说,我们设计了一个两阶段的推论方法:中毒过程和评分过程. 对于中毒过程,我们提出三个不同的审计要求的中毒策略. 对于评分过程,我们设计了一种新的量化方法和一个不受监督的推论模型,以提取中毒攻击影响范围内的成员特征.拟议的攻击利用了直觉,即如果FL良性客户使用样本,其预测可能不会被中毒攻击轻易改变. 最后,我们提出一个经过修改的随机响应算法(RR-Group)来检测我们的攻击,这可以保证FL模型的性能,并有效降低TEPE的攻击性能.广泛的实验表明,TEPE与大多数MIA相比,实现了竞争的推论精度和F1-分数,同时回避了两个具有代表性的防御,除了我们提议的检测方法RR-Group.",
