    "summary": "秘密泄漏和DC溢出是JPEG图像秘密图像共享(SIS)的两个关键挑战,后者也导致格式不兼容. 为了解决这两个问题,对JPEG图像的SIS进行了系统调查。本文的主要贡献是设计了DC秘密共享和AC秘密共享这两个基本组件,分别用于编码一个JPEG秘密图像的DC和AC系数. 在DC秘密共享中,DCA共享和后处理合并处理DC组件.值得注意的是,为防止DC溢出,设计了一个局部的影子可调节秘密共享机制以及一个样本重新计算战略。 在AC秘密共享中,采用AC交叉区块挤压和全局挤压来搅乱AC系数,使得AC块特征能够发生戏剧性的交替. 然后使用ACA共享编码过载的AC系数.广泛的实验和比较证实了拟议办法的有效性和优越性。与最近的方法相比,我们的方法成功地消除了秘密泄漏,避免DC溢出,从而确保与JPEG格式的完全兼容.",
