    "summary": "量子Dempster-Shafer理论(QDST)得到一个量子质量函数(QMF),一个基于量子干扰的多条信息来源获得的模糊度量衡.总体而言,质保机制有效代表并处理不确定信息,但管理多个质保机制之间的冲突仍然具有挑战性。 为了解决这一问题,我们提议在 \" QDST \" 框架内制定一个新的量子冲突指标。 这是第一个令人满意的、理想的冲突衡量特性,包括非消极性、对称性、约束性、极端一致性和对完善的不敏感。 基于QCI,引入了一种新的量子冲突聚变方法(QCI-Fusion),以熔化高度冲突的QMF. 此外,包括QCI-Fusion在内的传统方法一般会根据预测的标签构建量子框架(QFoD),这就很难覆盖隐形类. 因此,建议建立一个新的决策架构,即QCI-Decision,用于无监督的检测,拒绝分配外样本(OOD),同时保持分配内分类(ID).实验结果显示,QCI-decision的分类精度与原始模型预测的偏差最多为1.49%. 同时,与最新的OD检测方法相比,QCI-决定将接收器操作特征曲线(AUC)下的区域提高0.6%,并将真实负率(FPR)降低95%的假正率(FPR),最高为1.63%. 此外,与QCI-Fusion相比,QCI-Science实现了约三倍的更快的聚变速度,性能可忽略不计,为开放世界量子信息决定提供了一个有希望的解决方案.",
