    "direction": "信息安全",
    "summary": "决策树(DT)是一种高效和可解释的机器学习算法,已广泛用于众多工业应用. 随着对更高性能的需求增加,人们越来越关注使用垂直数据集培训DT的跨领域协作,不同所有者拥有不同的特征,但共享相同的一组样本. 由于对隐私的担忧,利用安全的多党计算(MPC)共同培训DT已经引起了极大的关注. 虽然有希望,但在大型纵向数据集中采用这些办法,对两个瓶颈(各司和比较)提出了艰巨的挑战。MPC对处理分区不友好,而DT训练算法则涉及分区来评价每个树节点的每个特性分割.贸易改革培训和推论也涉及许多比较,但现有的安全比较仍然不够有效。 我们提议采用FSS-DT,这是一个高效率的两方框架,用于安全的DT培训和对垂直分布数据集的推论。FSS-DT的效率是通过设计一种无分割的MPC友好DT算法来实现的. 此外,我们利用我们优化的分布式比较功能(DCF)提出一种轻量级安全比较协议,这是通过“0/1编码”和“早期终止”技术进行功能秘密共享的一个例子。 我们实施了FSS-DT的原型。广泛的实验表明,FSS-DT与接受过纯文本培训的模型具有同样的精准性,并且超过了最先进的Pivot和PriVDT。具体地说,在大型UCI数据集的局域网和广域网培训中,FSS-DT分别比Pivot快17.5×和51.1×,比Swan快约8.4×和8.8×.",
