    "direction": "信息安全",
    "summary": "智能手机摄影的广泛采用,导致用户越来越依赖云存储进行个人照片存档和共享,引发了关键的隐私关切.现有的深层基于学习的图像加密计划,通常建立在CNN或GANs上,往往依赖于传统的密码算法,缺乏固有的建筑可逆性,导致恢复质量有限,坚固性差.不可逆神经网络(INNs)已经出现,通过促成可逆变换来解决这个问题,然而第一个基于INN的加密方案仍然依赖于辅助参考图像和抛弃副产品信息后才能解密,导致恢复退化,实用性有限.为解决这些局限性,本文提出FlowCrypt,这是一种基于流的新型图像加密框架,同时实现近乎无损失的恢复,高安全度,轻量级模型设计.FlowCrypt开始于对输入图像应用一个按键条件的随机分割,增强前置过程的随机性和加密强度.由此产生的组件通过一个基于流加密/解密(FED)的模块进行处理,该模块由不可逆的块组成,它们共享跨加密和解密的参数.由于其可逆的架构和无参考设计,FlowCrypt确保了高真实度的图像恢复.广泛的实验显示,FlowCrypt在三个数据集上以100dB实现回收质量,生成统一分布的密码图像,并维持一个只有1M参数的紧凑架构,使其适合移动和边缘设备应用.",
