    "direction": "人工智能",
    "summary": "联邦学习(FL)已成为分布式机器学习(ML)的突出范例之一. 然而,众所周知,在非IID(非独立和相同分布的)数据在客户之间分布下,其性能会显著下降。 为了研究这一效应,现有作品主要通过在客户端之间强制使用标签分布来模拟数据异质性. 在本文中,我们显示标签分布skew未能在计算机视觉任务中完全捕捉到超越分类的数据异质性,暴露了文献中被忽略的空白. 通过利用预先训练的深神经网络来提取特定任务的数据嵌入,我们通过每个视觉任务的镜头定义了特定任务的数据异质性,并引入了一个新的数据异质性级别,称为嵌入式数据异质性. 我们的方法是在嵌入数据点的基础上对数据点进行分组,并利用Drichlet的分布在客户中分配。 通过广泛的实验,我们根据我们修改后的数据异质性概念,评价不同弹性交易方法的性能,在文献中引入新的基准性能衡量标准. 例如,在7项具有代表性的计算机视觉任务中,我们的嵌入式异质性配方导致在FedAvg下观测到的损失增加约60%,这表明它更准确地暴露了数据异质性造成的性能退化。 我们进一步揭示了一系列可以追求的开放研究方向。",
