    "summary": "要防范复杂的网络威胁,就必须在复杂的网络基础设施中战略性地分配有限的安全资源。 当捍卫者拥有有限的防御资源时,协调数百个节点的蜜壶放置的复杂性成倍增长。 在本文中,我们提出一个多攻击者巴耶斯·斯塔克尔贝格框架模型,用以模拟同时试图突破一个直接的系统组件网络的对手。 我们的方法通过不同的目标偏好、利用能力和相关成本,使每个对手都具有独特的特点,同时使维权者能够在关键的网络位置上战略性地部署蜜罐。 通过将多跟踪者Stackelberg配方与动态的贝叶斯信仰更新相结合,我们的框架允许维权者根据通过入侵探测系统(IDS)侦测到的行动不断完善他们对攻击者意图的理解.实验结果显示,拟议方法在几轮内防止攻击成功,并达到500个结点的网络,边缘超过1500个,保持可拉动的运行时间。",
