    "summary": "高分辨率遥感语义分解在土地利用监测,城市规划和救灾中发挥着关键作用. 然而,由于模式异质性、精细的物体结构以及目前深层学习模型的高计算成本,其部署仍然具有挑战性。 为了应对这些挑战,我们提议建立一个语义化的即时和图解结构提炼框架(SPGSNet-S ${}^{\\ast }$ $),这是一个紧凑而有效的结构,将提高多式联运特征与双向知识提炼结合起来。具体地说,我们设计了两个轻量级模块-辅助空间特征提取(ASFE)和红绿蓝(RGB)代表物-去甲龟化,并将吵闹的正态数字表面模型(nDSM)特征与RGB图像对齐,从而能够实现强性特征聚变. 此外,我们采用了一种双重蒸馏方案,包括以图解为基础的结构蒸馏,这种蒸馏可以捕捉和转移空间地形依赖,以及语义即时蒸馏(SPD),这种蒸馏在不受外部文本监督的情况下,能动态生成和注入有阶级意识的视觉提示。Vaihingen和Potsdam数据集的实验结果显示,SPGSNet-S ${}^{\\ast }$的成绩超过了几种最先进的方法,以8.89M参数和2.29G浮动点操作(FLOPs)实现了竞争性能.源代码和实验结果可在https://github.com/110-011/SPGSNet上公开查阅。",
