    "direction": "人工智能",
    "summary": "零射异常分类(AC)和分解(AS)方法旨在识别和概述缺陷,而无需使用任何标注样品。 在本文中,我们揭示了一个被现有方法忽略的关键属性: 工业产品之间的正常图像补丁通常会发现许多其他类似的补丁,不仅在2D外观中,而且在3D外形中,反常现象仍然多种多样和孤立. 为了明确发挥这种歧视性财产的杠杆作用,我们提议一个零镜头AC/AS的相互计分框架(MuSc-V2),灵活地支持单一2D/3D或多式联运。具体地说,我们的方法首先是通过惯性点组(IPG)改进三维表达,减少不连续表面的假阳性。将2D/3D的邻里提示融合到 更歧视性的多尺度补丁功能中,核心包括一种相互分数机制(MSM),让每种模式内的样本互相分配分数,以及将2D和3D分数引信以恢复特定模式缺失的异常的交叉模式异常增强(CAE)。 最后,与Constract Neigroborhood(RsCon)的重新评分,根据与更具代表性的标本的相似性,压制虚假的分类. 我们的框架灵活地处理整套数据集和性能一贯强劲的较小子集,确保各种产品线的无缝适应性。 在新颖框架的帮助下,MuSc-V2实现了显著的性能改进:MVTec 3D-AD数据集的$\\mathbf+23.7+23.7%的AP增益,Eyecandies数据集的$\\mathbf+19.3+19.3的增益,超过了之前的零射基准,甚至超过了最少数的射法.",
