    "direction": "数据工程",
    "summary": "本文介绍了HQT-TI,这是一种旨在提高空间关键词查询效率的新索引编制方法.HQT-TI由两个主要部分组成:一个Hilbert QuadTree(HQT)基于空间指数和一个Trie-Inverted Index(TI)综合文字指数.HQT将希尔伯特曲线与Quadtree融合,建立了两者的直接关系.TI将三重和反向索引结合起来,以尽量减少与长列表相关的交叉成本,从而提高关键词查询的速度. 基于HQT的空间查询算法(HQT-SQ)减少重叠检查,并通过使用查询钻入和深度第一次搜索,在空间查询中以有限的宽度扩展来限制不相关的对象检索. 同时,基于TI的SLI-KQ基于关键词查询算法(SLI-KQ)的段列表交互,高效地处理关键词查询的段列表交叉.HQT-SQ和SLI-KQ的结合导致HS-SK,是一种高度高效的空间关键词查询算法.广泛的实验结果显示,HS-SKQ的性能比SFC-Quad达到两个数量级,比现有最佳竞争对手达到5.46×的速度,使其成为大规模空间关键词查询处理的有希望的解决方案.",
