    "direction": "人工智能",
    "summary": "了解和复制现实世界是人工一般情报(AGI)研究中的一项关键挑战. 为了实现这一目标,世界模型等许多现有方法旨在捕捉指导物理世界的基本原则,从而能够进行更准确的模拟和有意义的互动。 然而,目前的方法往往将不同的模式,包括2D(影像),视频,3D,和4D的表示,作为独立的域,忽略了它们的相互依存关系. 此外,这些方法通常侧重于现实的孤立层面,而没有系统地整合它们之间的联系。 在这项调查中,我们提出了对调查数据维度在现实世界模拟中进展的多式联运基因模型的统一调查。具体来说,这次调查是从2D生成(出现)开始的,然后转向视频(出现+动力学)和3D生成(出现+几何),最后是融合所有维度的4D生成. 据我们所知,这是在单一框架内系统统一2D,视频,3D和4D一代研究的第一次尝试. 为了指导今后的研究,我们全面审查数据集、评价衡量标准和未来方向,以便为新来者培养洞察力。 这项调查是推动在统一框架内研究多式联运基因模型和现实世界模拟的桥梁。",
