    "link": "https://doi.org/10.1016/j.neunet.2026.108958",
    "direction": "人工智能",
    "summary": "图形神经网络(GNNs)已经确立了自身作为从图形结构数据学习的强大工具的地位. 然而,他们依赖当地的信息传递机制,导致将成指数增长的邻里信息压缩成固定大小的矢量,从而严重限制了远程依赖模型的建立。 我们引入了量子-启发图神经网络(QGNN),其新颖的量子连接丢失(QEL)功能通过一个与现有方法根本不同的机制来应对这一挑战.与光谱规范化(能强制平滑)或最大py法(能鼓励代表多样性)不同,QEL将节点嵌入相关性矩阵的von Neumannpy化最小化,从而将eigen值集中在维持全球结构规律的主导eigenmodes中. 这种entropy最小化在遥远但功能相关的节点之间创造了直接的信息路径,有效地绕过多跳瓶颈. 我们根据两个标准基准(Cora、Citeser、PPI、电子电路)和长程图基准套件(LRGB)对QGNN进行评估,该套件的图形平均直径可达56.99(Peptides)。 在LRGB数据集上,QGNN实现了实质性的改进:与GCN相比,Peptides-struct上的MAE相对减少37.6%,比GraphGPS(GraphGPS)的图形变形器(GraphGPS)改进4.0%,显著的是,在7+hops分隔的节点对上,97%的性能优于GCN. 尽管取得了这些收益,QGNN与标准的GCN相比,只需要20%-30%的额外计算间接费用,而5-6×比Graph Transformer方法更快. 我们的成果将基于肽的正规化确定为在图表中建立长期依赖性模型的原则性和高效方法。",
