    "pdf": "papers/incremental_ab1913d3ed91.pdf",
    "link": "https://doi.org/10.1109/tdsc.2026.3695553",
    "direction": "信息安全",
    "summary": "\"模式背景协议\"(MCP)作为一个通用标准出现,它使AI代理能够与外部工具无缝连接,大大增强了其功能. 然而,虽然MCP带来了显著的好处,但它也带来了显著的弱点,例如工具中毒袭击(TPA),其中隐藏的恶意指令利用LLMs的节制来操纵代理行为. 尽管存在这些风险,但目前关于MCP security的学术研究仍然有限,大多数研究侧重于狭隘或定性分析,未能抓住现实世界的各种威胁。 为了弥补这一差距,我们提出了MCP eXploit工具包(MCPXKIT),该工具包在四个关键分类下将28种不同的攻击方法分类和执行:直接工具注射,间接工具注射,恶意用户攻击,以及LLM内在攻击. 我们进一步评估了三个MCP客户环境和七个模型的这些攻击,以量化其攻击成功率。 我们的实验揭示了对MCP脆弱性的关键洞察力,包括代理商盲目依赖工具描述,对基于文件的攻击的敏感性,利用共享上下文的链式攻击,以及难以区分外部数据与可执行命令,这种情况在一些推理模型中甚至更糟. 这些通过攻击实验验证的洞察力,突出了强力防御战略的迫切性,并告知了MCP设计. 我们的贡献包括:(1) 构建一个全面的MCP攻击分类法;(2) 引入一个统一的MCPXKIT攻击框架;以及(3) 进行经验脆弱性分析,以加强MCP安全机制。这项工作提供了一个基础框架,支持多CP生态系统的安全演变。",
