    "direction": "人工智能",
    "summary": "传统特征选择方法注重减少维度,往往以丢弃宝贵但隐蔽的信息为代价.与此相对照,本文引入了特征扩展法,这是一种新颖的方法,可以自动识别和重建缺失的特征,意思是在初始特征提取过程中被忽略或未发现的属性,增强预测性能而无需额外数据收集. 我们提出半动态特性集(SDFS)网络,这是一个独特的机器学习框架,既学习特征值,也学习模型参数,从而提高复杂数据集的稳健性. 为了增强可解释性,我们整合了大语言模型(LLMs),为新发现的特性分配有意义的标签,将它们从黑盒变量转化为可操作的洞察力. 我们提议的特征扩展方法不断改进多个数据集的分类和回归性能。特别是,帕金森疾病检测的准确度从89%提高到95%,而Wine质量预测的准确度从82%提高到85%,并将空气质量预测中的平均平方差(MAE)从91.2降至85.04,这证明了其在发现缺失特征方面的有效性。 通过将我们的特性扩展与LLM驱动的可解释性结合起来,这种方法不仅提高了模型的性能,而且还揭示了医疗、金融和科学研究等关键领域的隐藏数据模式。全面实施可在GitHub[GitHub link]上获得,该型号可通过PyPI安装在软件包\"sdfs\"[PyPI link]下.",
