    "direction": "人工智能",
    "summary": "保留言论的面部表情操控(SPFEM)旨在修改面部情绪,同时严格保持与口语内容相关的口腔动画.当前的作品依赖于个人无法获取的配对培训样本,其中两个对齐的帧表现出相同的语音内容,但在情感表达上却有所不同,限制了SPFEM在现实世界情景中的应用. 在这部作品中,我们发现用不同情感传达相同内容的演讲者在空间和时间空间都表现出高度相关的局部面部动画,为SPFEM提供了宝贵的监督. 为了利用这种洞察力,我们提出了一个新的空间-时空一致性相关性学习算法(STCCL),该算法将上述相关性作为明确的衡量尺度进行模拟,并整合各种衡量尺度,以监督操纵面部表情,同时更好地保存口语内容的面部动画. 为此,它首先学习了空间一致的关联度量,确保了与特定情感相关联的图像中相邻的局部区域的视觉关联性与与与不同情感相关联的图像中相应区域的视觉相关性密切相似. 同时,它还开发了一个时间一致性相关性的衡量尺度,确保与一种情绪有关的相邻图像帧的特定区域的视觉相关性与与与另一种情绪有关的帧的相应区域类似。 我们认识到,所有区域的视觉相关性并不统一,我们还制订了一种具有关联意识的适应战略,将面临更大挑战的区域列为优先事项。 在SPFEM模型培训期间,我们构建了当地相应区域之间输入和输出图像框架的空间-时态一致性相关度测量值,作为监督生成过程的额外损失。 我们对各种数据集进行了广泛的实验,结果证明了拟议的STCCL算法的有效性.",
