    "direction": "人工智能",
    "summary": "由于双臂协调和高维行动空间的固有复杂性,双机器人操纵仍然是一个根本性的挑战.本文介绍扩展的YOTO++(英语:You Only Teach Once),这是直接从第三人称人类视频演示中教授双人技能的统一的一拍学习框架. 我们的方法用双视镜提取结构化的3D手动,并将其蒸馏成紧凑的,基于键框的轨迹,用于双臂执行. 我们制定了可扩展的示范扩散战略,将一弹一弹的演示合成不同的培训样本,从而能够有效学习定制的双人传播政策。广泛评价一系列广泛的长期双人任务,包括同步、同步、接触丰富和不全面的情况,显示出对新技能和新事物的强烈概括。 我们还在初始操纵阶段引入了闭路控制视觉对接机制,使系统能够及时适应执行过程中的扰动. 我们在一个看不见的双臂机器人平台上验证这一框架,以显示无缝的跨表现转移,而不进行额外的再培训。YOTO++在准确性,稳健性,可伸缩性等方面都取得了令人印象深刻的性能,推动了通用双人操纵系统的实际部署.",
