    "link": "https://doi.org/10.1016/j.neunet.2026.109560",
    "direction": "人工智能",
    "summary": "视觉强化学习(VRL)旨在从高维观测中提取有效的视觉信息,以优化决策政策. 虽然现有的VRL方法通过数据扩充和辅助任务,在各种控制任务上取得了显著进展,但物剂仍然容易被来自多余的信息和无关因素的分心,导致在隐形环境中的过度适应和退化的泛化. 为了应对这一挑战,我们提议对VRL进行类似的国家指导性关注。 在这个方法中,一个相似性指导模块(SGM)被设计来利用原观测中嵌入态与增殖观测中嵌入态之间的相似性,以引导编码器在原观测中专注于与任务相关的区域,从而产生相应的状态关注图. 同时,通过解码其状态嵌入,获得增强观测的状态注意力图. 此外,还引入了余弦相似度,以测量原始观测的状态注意力图和增殖观测的状态注意力图之间的全球相似度,在自我监督的学习目标中结合了二进制交叉视野损失,以鼓励状态注意力图在表示空间中的对齐.将SGM和基于宇宙相似性的状态关注图组合起来,有利于自我监督的学习,为下游强化学习获得更强健的状态表现,从而使代理人能够学习最佳政策,提高在无形环境中的通俗化能力. 关于DeepMind控制通用基准(DM Control-GB)的实验结果表明,与具有代表性的VRL基线相比,SSA实现了优越的稳健性和通用性能.",
