    "direction": "人工智能",
    "summary": "普遍时间序列的表示学习具有挑战性,但在诸如分类、异常检测和预测等现实世界应用中却很有价值。 最近,积极探索了对比性学习(CL),以解决时间序列代表性问题。 然而,一个关键挑战是CL中的数据增殖过程会扭曲季节规律或时间依赖性,不可避免地导致语义信息丢失. 为了应对这一挑战,我们提议时间序列的地形CL(TopoCL)。TopoCL通过纳入持久性同位素来减轻这种信息损失,它捕捉到在变换下仍然不常态的数据的地形特征. 在本条中,我们把时间序列数据的时间和地形特性视为不同的模式。具体地说,我们计算持续同位素,以构建时间序列数据的地形特征,在持久性图(PD)中代表它们. 然后我们设计了一个神经网络 来编码这些持久的图表。 我们的方法共同优化了时间模式和时间-地形学对应中的CL,促进了对时间序列的时间语义和地形特性的全面理解. 我们在四个下游任务分类、异常检测、预测和转移学习方面进行了广泛的实验。结果显示,TopoCL实现了最先进的性能.",
