    "summary": "最近,将因果发现作为持续优化问题的框架的计分方法取得了显著的性能收益. 然而,它们的性能往往在具有高度维度、样本有限和噪声不一的情景下退化。 据实证观察,以制约为基础的方法一般比以持续优化为基础的方法更能学习不同噪声下的因果结构,比以持续优化为基础的方法少,这促使我们通过引入和利用有条件的独立(CI)信息来改进基于持续优化的因果发现. 为了获得可靠的CI信息,我们使用低序(0令和1令)CI测试从观测到的数据中构造一个加权的上层结构. 然后,我们提出加权CI的限制因素,以持续优化,从加权上层结构中很容易得到这些限制因素。 从理论上讲,我们为我们受限制的优化框架提供了与CI限制的趋同性保证。 关于合成和现实世界数据集的广泛实验表明,我们的提案有效地改善了现有持续优化方法在因果发现中的性能,特别是在低样本制度中的性能.源代码和数据见https://github.com/Mjchen22/WIC。",
