    "summary": "常规神经网络对对偶连接的依赖限制了它们模拟生物神经系统固有的模块性高序相互作用的能力。将这些更高顺序的相互作用与分序动态和多次时间拖延结合起来的大型网络的稳定性分析和控制,由于分析的不可阻塞性,是一个重大挑战。 本研究为以模块化三聚体为特征的大规模分序神经网络模型建立了理论和计算框架.稳定的分析标准和Hopf的比富尔化是衍生出来的. 为了应对控制挑战,实施了一个强化学习框架,以适应性地调整更高顺序的耦合力,抑制破坏稳定的振荡。数字结果量化了系统参数对稳定性的深刻影响,同时展示了强化学习控制器在传统方法失败时维持稳定性的能力. 通过在不事先了解系统模型的情况下适应性地调整耦合强度,拟议的方法有效地抑制了振荡,显示了这种高维、分析难懂的系统相对于模型控制器的优势。",
