    "direction": "人工智能",
    "summary": "联邦学习(FL)促进了合作模式培训,保护了用户的隐私,引起了研究界的极大兴趣. 通过FL,参与者根据本地数据对其模型进行培训,并将相应的更新提交服务器进行汇总. 在隐瞒参与者身份的同时,FL可能会吸引对手,以阻碍基本模式. 在本文中,我们提出了一个FL框架,即FedDOT,以防御对手进行目标明确的攻击。FedDOT融合了两种强大的防御算法,即基于最大拓扑树的攻击者探测器(MSTAD)和基于Densest图的攻击者探测器(Density-AD),它们利用了重量更新和图表理论概念之间的关联,最大横跨树,以及最密集的图表. 我们的算法为帮助一个FL服务器提供了有力的解决方案,与相对应空间的理论界限一道,利用图像分类数据集进行了严格的实验分析,以验证FedDOT框架在非iid环境中的稳健性,通过使用各种度量衡来评价精度和攻击检测率,确定模型相对于最先进方法的优越性.FedDOT以单标签翻转、多标签翻转和后门等目标攻击成功率 < 10%,成功地防御了压倒性对手,其边际准确度下降不到2%。",
