    "direction": "信息安全",
    "summary": "文本图像是包含文本内容的图像. 通过光学字符识别(OCR)和未经授权的发布,它们容易受到内容盗版的伤害.仅以对抗性实例或数字水标记为基础的现有方法不足以有效处理这两种威胁。 在这项工作中,我们提议实行普遍横向水标记(UAW),这是一种双重保护,它误导OCR系统,并且能够同时进行水标记以进行可追踪性。具体来说,我们首先生成两个模板,用于在达到对抗OCR的能力的同时代表水印位. 然后,水印信息通过结构化的图板将比特模板编码成文本图像的下绘. 最后,嵌入式水印可以在水印块同步和多数表决机制的帮助下可靠地提取出来.实验结果表明,拟议方法在对抗能力和水标记功能方面是有效的。 我们还验证UAW在各种字体大小、颜色和语言上的可转让性,并通过现实世界的应用程序评价实际使用。 该代码可在https://github.com/yfjn/UAW上公开查阅.",
