    "summary": "刺激的拉曼散射(SRS)在光学通信、光纤感知和光谱分析等应用中发挥着关键作用。 然而,传统的建模方法如分步法(SSFM)在计算上要求很高.为应对这些挑战,我们提出了一个基于混合神经网络的新型深度学习框架,具体设计是为了捕捉非线性脉冲传播所固有的复杂的时空依赖性。 我们的模型对SSRS行为提供了快速而精确的预测,缓解了像SSFM这样的计算昂贵的模拟的需要. 为了验证该模型的性能,我们进行了实验,使用了Chalcogenide微结构光纤(MOF),这些光纤由于在红外红外线(MIR)中区拉曼增益系数高和光谱范围宽而引起人们的注意。具体地说,我们用一个2-$\\m$m的直插悬浮核心As2S3MOF来演示第一代成功的MIR SRS,它为模型验证提供了关键的真实世界数据集.结果显示,我们的混合神经网络在GPU上的速度是116倍,在SSFM上的速度是44倍,同时保持了准确性和概括性. 这种显著的加速为非线性光子系统的实时分析和反向设计铺平了道路,这些任务以前是传统方法所难以解决的。",
