    "summary": "医疗图像中准确划分病情地区对于疾病的早期诊断和准确治疗至关重要。现有的U形分割网络一般在编码器-解码器结构中采用同一等级层次特征之间的直接连接;然而,不同等级特征之间缺乏明确的相互作用限制了浅层结构信息和深层语义特征的有效融合,在划定复杂边界和细层结构时产生了挑战. 为了应对这些挑战,我们提议建立一个跨等级背景-了解网络(CC-Net)。 该模型由四个关键组成部分组成: 跨等级地物聚合(CFA)模块分别汇总浅深特征,明确模拟跨等级的语义关系. 全球地物聚合(GFA)模块整合了多层次的特征,构建统一的全球代表,在跨分支特征互动中提供多层次语义上下文.Cross-Branch语义补充(CSS)模块将从GFA获得的全球语义信息注入了CFA综合的浅深特征,提高了整体的结构意识.增强性能(EF)模块在有效抑制背景噪音的同时,加强了该模型对目标区域的歧视性能力. 对6个公共医疗图像数据集的广泛试验表明,CC-Net在所有评价指标中一贯优于最先进的分解方法。 该代码可在https://github.com/zz0226zz/CC-Net上查阅。",
