    "direction": "人工智能",
    "summary": "尖锐感知-最小化(SAM)通过最小化最大亮度(MaxS)来增强概括性. 尽管在实际上取得了成功,但我们实证地发现,SAM通化增强背后的MaxS面临\"膨胀指数问题\"(FIP),SAM只考虑梯度上升方向的平度. 这导致了深神经网络(DNN)的高黑森异能值,表明溶液区域的扁平度不足.较好的平坦性指标(FI)将降低这些黑森等值值,从而实现网络的平坦性最低,并改进通俗化。 因为SAM本质上是一种贪婪的搜索方法. 在本条中,我们建议利用培训损失与围绕当前重量的街区最低损失之间的差别,我们表示这种差别是微弱的(Mins)。 通过将MaxS和MinS合并,我们创建了更好的FI,在优化期间表示一个受宠若惊的方向.具体地说,我们把这个FI和SAM合并到拟议的双边SAM(BSAM)中,它发现比SAM更受宠若惊.理论分析表明,BSAM会汇合到当地的最低水平.广泛的实验表明,BSAM在各种任务中,即分类、转移学习、人类姿势估计、语义分类和网络量化方面,提供优于香草SAM的概括性能和稳健性。",
