    "summary": "在联邦学习(FL)中,不同和针对客户的数据分布造成域间转移问题,导致当地模式不同,全球业绩退化。 为了解决这一问题,本研究提出了一个班级和域意识的FL框架,这个框架可以脱钩,合作学习域-不变量和域特异性表述. 在客户端培训期间,采用了一个新颖的交叉特性分离(CGFS)模块,将域特性与类特性区分开来. 然后使用一个多样化的原型对比性学习模块来指导每个特征空间内具有良好区分性的类特征和域特征的学习. 最后,在服务器聚合过程中,采用了梯度加权分级聚合(GHA)策略,以有效汇总所有客户端的信息,并建立一个具有良好的强性的全球模型来进行域变异. 在两个具有域位转移的FL数据集上取得的实验结果显示,拟议方法的效绩始终高于最先进的方法.",
