    "summary": "空间时空数据对各种应用至关重要。传统的数据收集方法往往覆盖面有限,而利用移动设备的空间众包则提供更广泛的数据获取,但也在数据充斥方面带来挑战。 根据观测到的数据推断缺失的数据,现有数据完成技术往往需要详细的时空信息,从而引起对隐私的关切. 一些方法试图通过模糊位置来保护隐私;然而,这可能会破坏原始的空间-时空相关性,导致数据完成方面的错误增加. 为了解决这个问题,我们提出了一个基于隐私的差别模糊策略,在保持数据准确性的同时保障隐私. 我们的方法采用了一种预测模型,从历史数据中提取一个重要矩阵和一个关系矩阵。 这些矩阵用于将实际用户地点映射到更有利的地点,以便完成数据,然后进行价值调整,以保持可用性和保持时空关系。 我们表明,我们的机制满足了提供有效隐私保障的不同隐私。 对5个现实世界数据集的评价表明,我们的模糊机制在保护隐私的同等水平上比其他基线方法要好。",
