    "summary": "人群局部化旨在预测人类在拥挤场景的影像中的位置. 虽然现有方法已取得重大进展,但两个主要挑战依然存在:(一) 固定数量的均匀分布锚点在人群密度不一的图像中可能造成跨区域预测过度或不足;(二) 测试阶段与培训阶段预测的排名不一致,导致模型的推论不够理想。 为了解决这些问题,我们提议建立一个一致性-Aware Anchor Pyramid Network(CAAPN),由两个关键部分组成:一个适应性Anchor generator(AAG)和一个带有增强匹配(LAM)的本地化器.AAG模块根据估计的局部区域人群密度来适应性地生成锚点,以减轻锚点不足或过剩的问题.该系统还考虑到头前的空间分布,以提高性能。LAM模块旨在增加用于优化培训期间神经网络的预测,为此引入了一组额外的目标候选人,并将他们与地面真相正确匹配。 拟议方法在5个具有挑战性的数据集:上海科技A和B、UCF-QNRF、JHU-CROWD++和NWPU-Crowd上取得了较好的性能。",
