    "direction": "信息安全",
    "summary": "图表即时学习(GPL)是图表表达学习中的一种创新方法,它通过微调提示而能够根据具体任务进行调整,而不会改变基础的预先培训的模式。 尽管GPL的内在隐私风险日益突出,但仍然没有得到探讨。 在这项研究中,我们提供了对GPL在三种攻击者能力上的隐私渗漏的首次评价:GPL作为一种服务时的黑盒攻击,以及节点嵌入和迅速表达给第三方使用的各种情景. 我们通过属性推论攻击(AIAs)和链接推论攻击(LIAs)来评估GPL的隐私脆弱性,发现在任何能力下,攻击者可以有效推断敏感节点的属性和关系,一些数据集的推论成功率高达98%. 重要的是,虽然针对特定诱因(如GPF-plus)的定向推论攻击维持了较高的成功率,但我们的分析表明,与传统的GNN相比,GPL的迅速调整并没有显著提升隐私风险. 为了减轻这些风险,我们探索了几种典型的区别性隐私技术,包括DP-Aggregation、DP-SGD(即时梯度)和高斯嵌入噪声,为DP-GPL中的隐私-实用性权衡提供了指导。这项工作凸显了GPL中主要的隐私脆弱性,为图学中的未来隐私保护战略提供了新的见解和基础方向.",
