    "summary": "光谱图演化网络(SGCNs)是用图结构处理学习任务的主要工具之一.SGCNs利用图结构来定义图谱变换(即图傅里叶变换),在光谱域中追求良好的光谱滤波器. 出于效率原因,所追求的光谱滤波器通常与空间域中常态化的附位基团的多诺米相近,称为SGCN的多诺米传播. 在本文中,我们对SGCN所定义的传播矩阵进行了理论分析,并表明它实际上几乎总是发生非三角传播错误。 我们还得出一个明确的结论来应对这一错误。 为了缓解这一问题,我们提议通过学习更好的光谱转换来建立图谱投影网络,使普惠网有可能消除SGCN多元传播过程中遇到的错误。常用图表数据集的实验结果表明,普惠制网络可以学习超出理论上最优化的多名传播的传播矩阵,并比现有的SGCN模型产生有希望的结果。",
