    "direction": "数据工程",
    "summary": "检测对立的接近平衡的稠密子图是图和网络分析中社区搜索和冲突检测的关键问题,在社交媒体分析,商业,地缘政治等方面有着广泛的应用. 为了解决对对立局面缺乏统一定义的问题,我们提出\"antagonism measure\",将子图的质量按三个维度进行量化:极性,内部凝聚力,以及外部对峙的常态化密度.受小对抗平衡模式对对抗和平衡的贡献的启发,本文引入了一个高效的算法框架,用于矿山当地特有的图案密度最高的子图结构,以找到具有高对抗性的子图. 我们特别共同考虑hx$-pattern紧凑编号和L$hx$PDS,并设计了一个新的在署名图表(IPPV-s)中标注的迭代式建议-普鲁内和验证的管道,用于检测顶级的$L$hx$PDS。 主要贡献有: (1)对峙度量衡的定义,弥合了结构密度与平衡理论之间的差距.(2)提出一个将对流优化与最大流量核实相结合的高效算法管道,从而能够实现可伸缩和高效的对抗性近平衡密密子图的发现.(3)对真实签名的网络数据集进行的广泛实验,表明我们发现既能捕捉合作动力又能捕捉冲突动力的有意义的子图的方法是有效的.",
