    "direction": "人工智能",
    "summary": "联邦学习是现代机器学习的一个重要范例,它使私人和权力下放的模型培训成为学习敏感数据的关键。噪声标签学习是现代机器学习中另一个至关重要的范式,它用可能不正确的标签处理数据模型的培训问题. 他们的融合,即以吵闹的标签进行联邦学习(FLNL),是机器学习做法中出现的一个新出现的但具有挑战性的专题,然而,它的研究进展仍然缺乏审查。 本文件的目的是填补这一空白。 我们首先总结了对FLNL的四个核心挑战:本地化的标签噪声,标签噪声的跨客户异质性,本地化的过于适合标签噪声,以及不适当的基准. 然后,我们提出一个分类法,将目前的FLNL研究分类为四类,从而相应应对四种挑战:抽样方法、客户方法、模型方法和基准研究。这项工作为利比里亚民族阵线提供了第一次全面、简明扼要的审查;此外,我们还为这一迅速发展和实际重要的领域提供了未来的研究方向。",
