    "direction": "人工智能",
    "summary": "我们提出一种快速成像技术 来恢复小型场景的三维视线由于其复杂性,带有毫米大小物体的微型场景很难重建. 然而,微型设备在生活中很常见,其三维数字化是可取的。 我们设计了一个猫咪成像系统 单摄像头和多对平面镜 用于从娃娃屋的角度 对小型场景进行三维重建 我们首先对如何配置使用一对浮游镜的猫形成像系统进行了深入分析。 我们通过解决视角映射问题来得出镜像参数(如方向和位置),其目的是确定能够从期望的角度提供反射图像的可行的镜像配置. 通过应用设计原理,我们展示了一个全圆形的快照catadioptric成像系统,由八对平面镜组成.具体地说,我们把镜像对放在有不同角度的嵌入式金字塔表面,以便在一个镜头中捕捉周围的多视图图像. 这将允许3D重建动态场景. 我们的镜像设计可以根据场景的大小来定制,以进行优化的视图覆盖. 我们使用3D高斯白板(3DGS)的代表作来进行场景重建以及新颖的景观合成. 我们通过整合视觉船体衍生的深度限制,克服了我们有限的视野投入所构成的挑战。 我们对各种小型场景的合成图像和真实图像进行实验,这些场景被我们自定义的成像系统所捕获。实验结果显示,我们的方法优于最先进的零视和无校准的3DGS方法。 我们还在动态微型场景(如活的,移动的昆虫)上展示了新颖的视图合成结果.",
