    "summary": "分布式机器学习(DML)可以进行平行培训,但在确定模式所有权方面造成冲突,因为核实个别客户在体重更新过程中的具体贡献仍然是一个挑战。 为了解决所有权纠纷,防止恶意客户伪造数据,验证每个客户的独特培训史的完整性和有效性,可以公平地确定他们对最终DML模式的部分所有权. 在本文中,我们首次提出一个新的基于“矩阵承诺”的DML所有权核查计划,采用简明的证明,以确保在有限的计算成本范围内的计算完整性和正确性。与基于SNARK的计算密集方法形成对比的是,MAMMON构建了多线性树结构,通过规范化培训过程来降低验证更新成本,避免复杂的算术电路计算. 此外,我们使用客户身份的私人钥匙对重量证明进行水印,以保障承诺不被篡改或未经授权的获取。广泛的实验表明,MAMMON在维护DML培训的计算完整性方面表现优异,既包括理论分析,也包括与其他现有基线的比较.",
