    "summary": "基于Anchor的多视图群集在近似结构和缩放到大数据集方面的效率得到了越来越多的关注. 为了减轻人工超参数调试的负担,最近的研究引入了参数无扩展. 然而,现有方法仍然面临严峻的挑战:主锚通常在初始化后固定,限制了对不同数据的适应性;对不同观点执行一套共享主锚会抑制特定观点的多样性;高压或自我加权的聚变战略往往缺乏明确的交叉视图对接,导致结构不一致。 为了解决这些问题,我们提议建立一个参数自由多视图分组框架,其中包含大型数据的适应性控制器(FPMCAA)。与拆卸锚地构造和图聚化的现有方法不同,FPMCAA将适应性锚地学习,锚地图构造,以及清晰的交叉视野对齐整合在一个统一的优化模型中.锁定器被反复改进,以捕捉复杂的分布,而视距特定的图则在不牺牲固有多样性的情况下向共识结构靠拢.该框架避免了手动超参数调试,通过高效的交替优化实现线性计算的复杂性.有关基准数据集的广泛实验表明,林业和林业产品管制局在集群性能、稳健性和可扩展性方面一直比最先进的方法要好。FMPCAA的源代码见https://github.com/Xuchen2020/FPMCAA.",
