    "direction": "人工智能",
    "summary": "我们调查了一类相对探索不足的杂交神经连锁模型,这些模型将象征性的学习与神经推理结合起来,以构建符合正式正确性标准的数据生成器. 在符号神经生成器(SNGs)中,符号学习者从一小组实例中考察了可行数据的逻辑规格,有时只是一个实例.每种规格反过来会限制向神经基生成器提供的有条件信息,而神经基生成器拒绝任何违反符号规格的情况。与其他神经元学方法一样,SNG利用了符号学和神经学方法的互补优势.SNG的结果是一对美元(H,X),其中H$是用数据构建的可行实例的象征性描述,X$是一组能满足描述的新实例. 我们为这种系统引入一个语义学,其基础是搭建适当的基座和纤维部分排列的套装,合并为一个整体的部分顺序。 我们实施了一个SNG,将限制性的诱导逻辑编程(ILP)与大型语言模型(LLM)相结合,并在早期的药物设计上加以评价. 我们的主要兴趣是SNG产生的描述和一组潜在的抑制分子. 关于基准问题 -- -- 对药物目标有很好的了解 -- -- 可持续国民政府的业绩在统计学上与最先进的方法具有可比性。 关于目标不明的探索性问题,生成的分子显示出与主要临床候选人同等的亲和性。 专家们进一步发现,象征性的规格作为初步过滤器是有用的,若干生成的分子被确定为可用于合成和湿实验室测试。",
