    "summary": "文章研究了分布式聚合优化(DAO)问题,在这个问题上,每个代理人的本地目标功能不仅取决于其自身的决定变量,还取决于涉及所有代理人决定的集合词. 在这种情况下,代理人之间频繁的信息交流引起了严重的隐私问题,因为敏感信息可以从共享数据中推断出来。 为了解决这一问题,我们建议采用差别化的私人加速分布梯度跟踪算法,将分布式动态平均共识、重球动力法和差别隐私(DP)的技术结合起来。 具体而言,为了维护隐私,交流的信息受到独立的拉普拉斯噪音的干扰。 此外,我们的算法使用噪声扣减机制,防止在估计集合变量和局部梯度时,噪声导致的误差累积,从而确保算法的准确性.假设全球客观函数是强烈的对流,并且有利普希茨连续梯度,我们严格证明,拟议的算法在中方误差意义上实现了线性趋同. 此外,我们得出明显的次优化界限,并正式确定算法满足$\\epsilon $ -DP. 最后,还提供了数字模拟,以验证拟议方法的有效性。",
