    "summary": "多景无监督的特征和实例共选的目标是同时从多景无标签的数据中识别最具代表性的特征和样本,这有助于减轻维度的诅咒,减少实例大小以改善下游任务的绩效. 然而,现有方法将选择特征和实例选择视为两个独立的过程,未能利用特征和实例空间之间的潜在互动。 此外,以往多视图数据的共同选择方法要求调和不同的观点,而忽略了它们之间的一致信息。 在本文中,我们提议采用Consistency和DivErsity LearNing为基础的多视图无监督的地物和场景联选(CONDEN-FI)来解决上述问题.具体地说,CONDEN-FI从样本和特征空间重建多视图数据,以学习各种观点一致和具体针对每种观点的表述,从而能够同时选择最重要的特征和实例。 此外,CONDEN-FI还适应性地学习了视图共识的相似性图,以帮助在重建的数据空间中选择不同和相似的样本,从而导致更多样化的选例.开发了一个高效的算法,以解决由此产生的优化问题,关于现实世界数据集的全面实验结果显示,与最先进的方法相比,CONDEN-FI是有效的.",
