    "summary": "多观点学习方法往往注重提高决策的准确性,同时忽略决定的不确定性,这极大地限制了其在安全关键情景中的应用. 为了解决这个问题,可信赖的多视图学习方法通过学习每个实例的班级分布来估计预测不确定性. 然而,这些方法严重依赖高质量的地面真实标签。 这促使我们探索一个新问题:如何在吵闹标签的指导下开发可靠的多视图学习模式? 我们建议采用信任的多视图噪声精炼法(TMNR)来应对这一挑战,方法是对低质量数据特征和易于混淆的类别所产生的标签噪声进行模型化。TMNR使用证据深层神经网络构建能捕捉信仰和不确定性的视点特定观点. 然后通过噪声相关矩阵来改变这些观点,以配合吵闹的督导,其中矩阵元素受到样本不确定性的限制,以反映标签的可靠性. 此外,考虑到在吵闹的监督下共同优化证据网络和噪声相关矩阵的挑战,我们进一步提出 \" 多视噪声再探 \" (TMNR$ ^{\\mathbf{2}}$2}}$2),通过为不同的模块制定不同的培训目标,使这一复杂的共同培训问题脱钩。TMNR$^{\\mathbf{2}}$2通过证据标签一致性识别可能存在错误标签的样本,并从邻里的信息中生成伪标签. 通过指定干净的样本来优化证据网络和吵闹的样本来引导噪声相关矩阵,TMNR$^{\\mathbf{2}}$2$$2分别减少了映射干扰并实现了稳定的训练. 我们实证地根据7个多视图数据集的最新基线评估我们的方法。实验结果显示,TMNR$^{\\mathbf{2}}2$2$2$2$明显超过基准方法,标签噪声50%的数据集平均精度提高7%.",
