    "summary": "深层神经网络在图像分类任务中表现出令人印象深刻的表现,但仍易受对抗性实例的影响。标准对抗性训练可增强强度,但通常未能明确处理班际特征重叠问题,这是对抗性易感性的一个重要促成因素。 在这项工作中,我们引入了一个新的对抗性训练框架,通过在特色空间中从对抗性和清洁性样本中投射出阶级之间的依赖性,从而积极减轻阶级之间的距离。具体地说,我们的方法首先为每个对抗性样本确定最接近的班际邻居,然后将这些预测移到这些邻居身上,以强制加强特征分离。 从理论上讲,我们证明,我们提议的对数校正降低了Lipschitz神经网络的常数,从而降低了Rademacher的复杂性,这直接有助于提高通俗性和坚固性。跨越标准基准的广泛实验,包括CIFAR-10、CIFAR-100、SVHN和TinyImagenet,表明我们的方法表现出了强大的性能,与领先的对抗性训练技术具有竞争力,突出了在有力和干净准确性方面的重大成就。 我们的研究结果表明,必须明确解决阶级之间的邻近关系问题,以加强DNN的对抗性强势。 该代码载于补充材料中。",
