    "summary": "现有的脑瘤分化方法通常在脑瘤影像中采用多种磁共振成像(MRI)模式进行分化,可以实现更好的分化性能. 然而,在临床应用中,由于资源的限制,一些模式往往缺失,导致依赖完全模式分解的方法的性能严重退化. 在本文中,我们提议用Mamba-变形器混合网络(MMTSeg)进行多模式特性蒸馏,以便精确地进行脑瘤分解,并缺少模式。 我们首先使用一个多式联运特性稀释(MFD)模块,将特性层面的多式联运知识提炼成不同的单一模式,以提取完整的模式信息。 我们进一步开发一个UFE(UFE)功能增强模块,以模拟全球信息与本地信息之间的语义关系. 最后,我们建立了一个跨模组组合(CMF)模块,以明确协调不同模式之间的全球关联,即使缺少一些模式。Mamba-Transformer混合结构在UFE模块和CMF模块中改进了模式内部和模式之间的补充特征,动态地捕捉了长距离依赖性以及复杂空间背景下的全球语义信息。采用边界损失函数作为拟议的MMTSeg的分块损失,以尽量减少基于距离的度量的边界差异。 我们的消化研究显示,拟议中的特征增强和聚变模块和带有曼巴块的变形器对于改善脑瘤分化的性能和缺失模式十分重要。BratS 2018和BratS 2020数据集的广泛实验表明,在模式缺失时,拟议的MMTSeg框架超越了最先进的方法.",
