    "direction": "人工智能",
    "summary": "知识追踪旨在根据学生的历史学习互动来模拟学生的动态知识状态,并预测未来的学习业绩.现有的序列建模方法往往忽略了个体的差异,而且语义建模能力有限. 为了解决这些问题,本文件提出了一个知识追踪模型,将个性化的模型与知识蒸馏结合起来。 该模型引入了三个个性化模块:(1)一个个性化的问题理解模块,能够捕捉学生对同一问题的理解中的个人差异;(2)一个个性化的问题-知识关联模块,可以模拟问题与相关知识概念之间的关系;(3)一个个性化的知识状态忘却模块,可以模拟学生的记忆衰减规律. 这些模块可以更准确地模拟学生的动态知识状态。 此外,为了克服轻量级模型的语义限制,使用大型语言模型(LLM)作为教师,其语义模型能力通过知识衍射转移到基于LSTM的学生模型.实验显示,拟议方法在两个基准数据集上持续改进预测性能,显示出其在建立个性化学习模型和加强语义表现方面的有效性.",
