    "direction": "人工智能",
    "summary": "在机器学习领域,连续时间神经网络(CTNNs)因其强大的时间序列数据模型化能力而获得了极大的关注. 然而,传统的数值普通微分方程(ODE)解决方法受到计算效率低下的影响. 虽然闭式CTNNs(CfCs)通过闭式近似解决方案来缓解这个问题,但其基于分解常数输入的零序近似法在处理高分辨率或不规则抽样数据时仍然显示出错误. 本研究提出了基于拉格朗格内插法(NIALIM)的数值集成近似理论,引入时间间隔因子,线性近似于液态时常网络(LTCs)网络状态方程中的非线性整体函数,衍生出依赖于外部输入和采样间隔的闭式溶液,同时严格地证明近似和原始溶液之间的误差上限. 此外,我们还构建了两种新型的网络架构:动态特性累积闭式网络(DFA-CfN)用于一般序列任务,以及预先重建的DFA-CfN(PRDFA-CfN)用于可分解序列任务的优化,同时还有来自这两个家族的6个变种网络.涉及六个不同任务的广泛实验——物理动态模型、人类活动识别、物理网络挑战、互联网电影数据库(IMDb)情绪分析、XCO2遥感测序预测和综合能源系统(IES)的多能载荷预测——证明,我们提出的模型在所有基准方面都取得了最先进的性能,最高的度量改进达到69.2%,为连续的建模任务提供了一个崭新的高性能工具。用于支持本研究结论的代码见https://github.com/nuist-xf/DFA-CfNs。",
