    "summary": "断开动态搜索可对称加密(DDSSE)是一种很有前途的技术,它能够比加密数据更具表达性查询能力,同时确保动态更新情景中的数据安全. 虽然已提出若干方案以提高安全和搜索效率,但这些方案仍然受到重大限制,包括通信费用高以及更新和查询过程中出现更多的漏洞。 在这项工作中,我们通过完善其安全模型,包括精确的渗漏功能和隐私概念,开始对动态环境中的脱钩式可搜索对称加密进行正式研究. 基于这一经过改进的安全概念,我们提出了一个新的DSSE计划,称为D2SSE,它既实现前向隐私,又实现后向隐私,同时避免泄漏。具体地说,从静态的TWINSSE框架开始,这个框架将断开式关键字查询减少为连接式元键字查询,我们将其扩展为支持动态更新,同时保持正确性. 与此同时,我们同时减轻关键词对结果模式的泄露,并根据对称子集上游加密和可穿透加密的组合,提供强大的前向和后向隐私保障.维基媒体数据集的实验结果显示,与最先进的计划DIEX相比,D2SSE实现了0.25×降低搜索潜伏度. 此外,D2SSE只需要增加DIEX的客户端存储管理费,同时保持类似的服务器端存储成本. 0.06×.",
