    "direction": "信息安全",
    "summary": "基于API调用序列分析恶意软件是有效的,因为这些序列反映了恶意软件的动态执行行为.深入学习的最新进展促进了利用这些技术从API调用序列中挖掘有用的信息。 然而,现有方法主要侧重于从原始序列中提取特征,这些特征可能无法有效捕捉到关键信息,特别是在多流程恶意软件中,因为API调用出现互换问题. 最近的研究引入了一种基于图表的嵌入恶意软件检测API的方法.这种方法比现有的嵌入方法提供了两个主要优势:图模型不常见,可以更简明准确地捕捉进程内和进程间行为. 鉴于图神经网络(GNNs)内在容易受到对抗性攻击,这些模型容易受到这种威胁。 为了根据黑匣子设置下的API调用图评价现有恶意软件检测系统的安全风险,设计了一个Heuristic意图遮掩算法来改变捕捉精细恶意软件行为的意图. 这涉及根据节点之间的重要度量,迭代选择重要的节点,然后用休眠路径掩盖这些节点. 然后,恶意软件文件根据维持原文件语义的优化转换序列进行重建,坚持程序格式限制. 我们的方法在黑盒设置下,系统评价了四个最先进的基于图表的恶意软件检测系统.评价结果表明,它取得了较高的攻击成功率。 此外,生成的对抗性样本能够维持其原始功能。",
