    "summary": "尽管承认确保人工智能系统的可信赖性十分重要,但目前缺乏评价和认证其信任的既定方法和技术。 为了解决这一问题,我们提议由信托机构负责评估并证明人工智能系统的可信赖性,这是一种以专家为基础的新方法。 我们的方法基于一套高层次的要求,即信任的支柱,这些支柱被分解成一套低层次的标准,以AI专家评估的问题的形式表达. 它通过分级模式汇总专家判断,以提供特定AI系统信任程度(LOT)的量化表示,并在评价结果令人满意时生成证书.模糊的逻辑被用来模拟专家判断的不确定性和界定模型的参数。 拟议方法可高度可塑性,能够产生适合具体应用领域和监管框架的定制评价模式。 它通过两个实际人工智能系统的使用案例来说明,这两个系统利用基于最近发布的监管框架的方法所产生的模型进行评估。",
