    "direction": "人工智能",
    "summary": "RGB深度水下突出物体探测(USOD)带来了相当大的挑战,如照明不均匀,视觉干扰,图像模糊,限制了传统方法的有效性.以强分化能力著称的区段任意模型(SAM)提供了一个很有希望的替代方案。 然而,SAM依赖于即时标签(如点、盒和口罩)来发挥USOD数据集通常无法提供的有效资源。 为了解决这个问题,我们提议建立SAM-CLNet,这是一个快速、免费的SAM强化合作学习网络,由三个主要部分组成:1) SAM;2)一个面具快速生成器(MPG);和3)一个具有区域意识的合作学习损失(RCL)。 在我们的框架中,由MPG生成的伪mask提示被用作SAM的输入提示,帮助抵消由于缺乏手动标签导致的性能退化. 同时,RCL利用高质量的SAM预测来完善MPG,强化其特征提取,同时尽量减少低质量伪速率对SAM的影响. 这种循环反馈机制促进了探测准确性方面的相互改进。 此外,我们引入了一个U-Adapter模块,以适应水下图像的SAM,并在MPG中加入了一个频率跨心聚变模块,以整合RGB和深度信息.RCL中的区域意识关注通过将SAM的预测与MPG的伪面具进行比较,进一步针对挑战性区域. 对USOD10K和USOD数据集的实验表明,SAM-CLNet在5项公共显要物体探测基准上的表现优于现有方法并有效普遍。代码见https://github.com/BeibeiIsFreshman/SAM-USOD。",
