    "summary": "目标扬声器提取(TSE)的任务涉及将特定扬声器的声音从多种音频来源的混合体中分离出来。 大多数现有的TSE方法主要优化提取的波形的重建质量,同时俯瞰参考音频中包含的基本提示. 此外,传统的TSE网络缺乏交互学习机制,联合模拟混合和参考嵌入,往往导致扬声器混淆,特别是在参考与目标音频明显不匹配的情况下. 为了克服这些挑战,我们提议建立一个新的端对端双关注式的演讲者提取(DATSE)网络,明确处理演讲者混淆问题。DATSE使用注意加权的多尺度语音编码器,在不同的时间分辨率上适应性地强调特征. 此外,它还在辅助演讲者识别网络中引入了一个基于关注的演讲者汇总模块,该模块有效地整合了演讲者特有的信息,并利用混合音频提示来完善目标演讲者嵌入.WSJ0-2mix-exter数据集的实验结果显示,拟议方法不仅在多个度量衡中实现竞争性性能,而且在噪声和反响等各种扰动下也大大减少了扬声器的混乱,从而有效地降低了整体的混乱率.",
