    "link": "https://doi.org/10.1016/j.cose.2026.104930",
    "direction": "信息安全",
    "summary": "1. 联合国 本社会技术案例研究审查了各组织如何在复杂的商业环境中操作网络威胁情报。 鉴于网络威胁日益军事化的环境,网络威胁情报日益被视为各组织的关键决策支助职能。CTI承诺将网络防御从被动和无定向反应转变为主动、预期和定向能力。 因此,CTI使各组织能够预见到威胁行为者的意图和能力,从而促进制定防御性战略,以对抗预期的攻击模式。 尽管网络安全一直被排在企业最大风险的行列中,并且受到战略风险关注的驱动,但关于各组织如何在复杂的社会技术环境中实际实施和操作以情报为主导的方法的经验证据很少。 为了了解CTI如何在组织中运作,我们利用军事背景下的情报学说作为理论基础,因为这是以情报为主导的决策的最既定办法。 我们用情报循环作为理论视角 研究澳大利亚金融组织成熟的CTI实践 我们所收集的经验证据被描绘成一个利益攸关方-活动进程模型,用以解释CTI如何在领导、商业和技术团体中实践。 我们的调查结果揭示了既定情报学说的根本颠倒 — — 而不是从领导向下流动以推动情报行动的战略要求,我们的案例组织在技术业务仓中产生要求,将情报向上推向业务、战术和战略层面。 这改变了70年来在军方组织实践中建立的情报规范,揭示了现代民间组织在复杂的商业环境中实施CTI时所面临的独特挑战。 我们的研究揭示了一个矛盾现象,即各组织在CTI中投入大量资金,将网络威胁作为战略优先事项处理,同时制造障碍,阻止CTI提供战略价值。 这一悖论的根源在于CTI功能在组织结构的最底层的定位,企业与IT集团之间深厚的知识差距,以及缺乏战略相关性和分析刚性,创造决策价值的分析产品的盛行. 我们的利益攸关方活动过程模型为理论做出了贡献,为组织中的CTI实践提供了第一个系统的经验性解释,并将智能学说应用于网络背景. 从实践的角度来看,该模型是理解自下而上的CTI实践操作的诊断工具. 它使各组织能够绘制关键利益攸关方、进程和技术系统所产生的情报流动图,并重新设计这些流动,以提高战略一致性和相关性。 我们的调查结果对关于平民情况下以情报为主导的安全的基本假设提出质疑,并对在现代商业环境中实施CTI方案的组织有重大影响。",
