    "direction": "人工智能",
    "summary": "持续的传播模式是可行的,可以进行平稳的过渡,以便在一个持续的潜在空间中产生灵活的文本。持续传播的一个具有挑战性的问题是实施去名化过程,并操纵生成的符号,以在传播步骤中反映物理现象,从而形成一个符合具体情况和有实际意义的句子。基本上,高质量的文本生成可以通过简易的第一战略实现,它通过口罩语言模型优先在开头生成高频的简单或一般的代号,然后在结尾生成低频的复杂或特定代号.本文引入了面具噪声作为吸收状态,并在扩散模型中开发了新的连续-分散解吸过程. 每个扩散步骤都是通过生成一个连续的词嵌入或一个离散的遮罩符来完成的,其中潜在的过渡由高斯-迪拉克混合物的分布模拟. 然后通过对比性的损失来实施和加强容易的第一代文本生成,将这一代文本分散在简单和复杂的符号之间。 因此,通过最大限度地减少负对数可能性的变异约束,利用对比性混合物扩散模型,在每次扩散过渡中,根据大约Kullback-Leibler的偏差,将去诺化网络后置线与高斯-迪拉克后置线对齐,使这种可能性正规化。文本拓扑实验和其他任务的实验,通过使用拟议方法来说明生成行为中简单第一的策略,证明了句子生成的有效性和效率.",
