    "summary": "彩色旅行推销员问题(CTSP)及其扩展变体,即累积装配色的TSP(C2-CTSP),代表了古典多式TSP(MTSP)的重要概括. 通过纳入不同实体的色彩限制、能力限制和定制成本计算机制,这些配方表明与现实世界的应用密切相关。本文提出一个适应性增强关注(AEA)模型,以基于强化学习框架解决色彩限制的旅行推销员问题. 我们的方法引进了几种新颖的技巧。 首先,我们发展出动态的色彩意识解码机制,通过位元操作和适应状态过渡,系统地处理色彩限制. 然后,我们建立一个双目标优化方法,结合适应性惩罚机制,以平衡累计成本最小化和约束性满意度. 此外,我们设计了一个强化关注股,通过门式激活和分级特性传播,加快战略趋同,提高解决方案精度。 对CTSP和C2-CTSP基准的评价表明,AEA模型的性能超过了现有的神经组合优化(NCO)解析器和数个heuristic基线. 一般化实验显示,EAU模块有效加速了趋同,增强了解码稳健性,显示出对其它组合优化任务的有希望的适用性.",
