    "authors": "待补全（本轮目录抓取未请求作者字段）",
    "journal": "IEEE Transactions on Pattern Analysis and Machine Intelligence",
    "year": "2026",
    "published": "2026-09-01",
    "contentState": "partial",
    "contentNote": "已完成本地开源模型英译中，六段式其余部分待人工全文核验",
    "doi": "10.1109/tpami.2026.3688191",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tpami.2026.3688191",
    "direction": "人工智能",
    "summary": "理解幽默,特别是当它涉及需要比较推理能力的复杂和矛盾的叙事时,仍然是大型视觉语言模型(VLMs)的一大挑战. 这一限制阻碍了AI从事类似人类的推理和文化表达的能力. 在本文中,我们通过对漫画的深入分析来调查这项挑战,这些漫画是将板块并列,通过矛盾创造幽默. 我们介绍了YesBut,这是一个新的基准,包含来自多种语言和多文化背景的1 262幅漫画图像,其内容是综合说明,其中包含叙事理解的各个方面。 我们利用这一基准,通过从表面内容理解到深层叙事推理的四项互补任务,系统地评估了范围广泛的VLM,特别强调相互矛盾要素之间的比较推理。 我们广泛的实验表明,即使最先进的模型与人类相比也明显表现不佳,在视觉感知,关键元素识别,比较分析,以及幻觉等方面都存在常见的故障. 我们进一步调查基于文本的培训战略和社会知识的增强方法,以提高模型性能。 我们的研究结果不仅突出了虚拟语言对文化和创造性表达的理解中的关键弱点,而且还为发展能够通过比较推理加深叙事理解的背景意识模型提供了途径。",
    "question": "待人工补全。",
