    "direction": "人工智能",
    "summary": "神经场(NFs)将连续坐标映射到颜色或密度等信号,但从稀少的观测中快速进行高质量重建仍然很困难.经典神经通直内核(NTK)回归使闭合形式符合,然而它从根本上是线性的,不能累积可重复使用的任务前身. 我们开发了三种处理这些差距的算法。NTK-KIP学习了一套蒸馏支持的坐标(和可选标签),这样有限的NTK就可以从很少的观测数据中将大面积的缺失区域涂抹出来,产生紧凑的非线性表示而不是原始的内核解.MetaQuill meta-learns为一个INR共享初始化,这样新场景就可以通过仅更新一个小任务特定重量的偏移来适应,这提供了真实的特性学习和可重复使用的前置功能. 最后,MetaQuill-KIP将两种想法都融为一体:它以KIP风格的非线性温暖的开端为任务种子,然后在元获取初始化周围精炼出小的抵消.MetaQuill-KIP实现高PSNR重建,并在非常稀少的观测下进行精密的可视性涂装,同时只需要轻量级的每层调整,而扩散式基线通常取决于经过预先培训的大型基因前科和昂贵的每层图像调试。这表明NTK驱动的神经场既可以制成非线性,也可以制成元教育,缩小了分析内核与实际的几发重建之间的差距.",
