    "summary": "专家指导的 \" 因果关系结构学习 \" (CSL)纳入了先前的知识,以提高因果发现的准确性,但这种知识的获得往往受到人类专家的提供的限制。 虽然大语言模型(LLMs)提供了因果前科的替代来源,但是由于幻觉或上下文的误解,LLM衍生的知识可能与真实的因果结构不一致.本文引入了一个结构性制约衡量框架,该框架界定了制约强度和制约质量,以描述可靠性和有效性,从而能够对LLM衍生的制约进行系统评价。利用这一框架,我们评估了五类结构性制约因素:边缘存在(EEC)、边缘紫禁(EFC)、路径存在(PEC)、路径紫禁(PFC)和秩序限制(OC)。 我们的理论和经验分析表明,虽然欧共体具有很高的制约力,但从LLMs中得出的质量较低;反之,PFC和OC在搜索空间运行和可靠性之间提供了平衡的权衡。 基于这些洞察力,我们提出一个双层的CSL优化框架,通过节点顺序分割搜索空间,并利用全局路径限制来完善结构.结果表明,这一框架提供了一种有效途径,可以将吵闹的LLM产生的前科纳入CSL,特别是在专家知识有限的环境下。",
