    "summary": "班级不平衡和高维度数据对机器学习构成重大挑战,往往导致学习模式在少数群体班级上表现不佳,与维度的诅咒作斗争,这两个问题在本质上是相互关联的。本文通过多任务多目标特征选择方法,同时解决类不平衡和高维度两个问题.具体地说,拟议方法为一项特定任务确定了两个相关但不同的特征选择问题提法,每个提法侧重于总体和少数群体分类业绩的不同方面。 通过从原有的不平衡数据集中选择重要特征,拟议的方法避免了在培训期间人为地均衡班级分布的必要性. 此外,跨任务基因转移操作员能够重新利用从单独搜索中演化出来的宝贵特征子集,从而既提高少数群体阶层的准确性,又提高整体模型性能。17个类平衡数据集的实验结果显示,拟议方法在整体分类性能和少数民族类精度方面比比较先进的方法,特别是在高维度数据集方面,取得了更好的成果.",
