    "summary": "光谱嵌入法在统计学习和几何处理中被广泛使用.现有的深层神经网络(DNNs)从节点描述符构建非线性映射到嵌入坐标,缓解了传统eigendecomposition基图嵌入中的可伸缩性和泛化问题. 然而,为了培训深光谱嵌入模型,还需要额外的基于QR的正交化或亲缘转化. 在这项工作中,我们引入了一个不受监督的光谱基础学习(SBL)框架,用于图矩阵的泛异分解,从光谱嵌入的线性图解(LGCs)中受益. 我们设计了一个新的光谱嵌入标准,以类似于迭代电源通缩的方式学习光谱基础,避免了基于QR的额外正向化或光谱基础估计的转化. 然而,拟议的办法使图之间的光谱基座能够排成队列,从而缓解了egenvector切换,方便了图谱的匹配. 我们展示了拟议的SBL对通用图示异构的功效,其性能比最先进的深光谱嵌入方法高。源代码见https://github.com/DYS2108/SBL.",
