    "summary": "持续学习(CL)旨在增强机器学习(ML)模型的能力,以不断从新数据中学习,同时以以前获得的知识为基础,不忘过去. 随着模型从小型的预先训练的架构演变成大型的架构,以及从支持单式数据演变成多式联运数据,最近出现了多种式CL(MMCL)方法。MMCL的主要复杂性在于它超越了简单的单式CL方法堆叠. 这种直截了当的做法往往受到MM灾难性遗忘的影响,导致业绩不尽人意。 此外,MMCL引入了单式CL方法未能充分解决的新挑战,包括模式失衡,复杂的模式互动,高计算成本,以及MM骨干预加训练的零镜头能力退化. 在这项工作中,我们介绍了关于MMCL的第一次全面调查。 我们提供了基本的背景资料和MMCL设置,以及MMCL方法的结构化分类。 我们把MMCL方法分为四类,即基于规范化的,基于架构的,基于重播的,以及即时化的方法,解释其方法并突出其关键创新. 此外,为了推动这一领域的进一步研究,我们总结了开放的MMCL数据集和基准,提供了深入的讨论,并讨论了几个有希望的未来方向。 我们还建立了一个GitHub存储库,用于编制有关MMCL的文章索引和开放资源,可在https://github.com/LucyDyu/Awesome-Multimodule-Continual-Learning查阅。",
