    "direction": "信息安全",
    "summary": "最近的进步导致面向代码的大型语言模型(Code LLM)被广泛采用,用于编程任务. 尽管在部署方面取得成功,但他们的安全研究却远远落在后面。本文引入了一个新的攻击范式: (自动)外部快速注射对代码LLMS, 攻击者产生简洁,非功能引起的扰动,并在受害者代码背景中注入. 这些诱导的扰动可以通过常用的依赖关系(如软件包或RAG的知识库)传播,操纵代码LLM,在代码完成过程中实现恶意目标.与现有的攻击相比,这种方法并不需要控制模型的训练过程,与后门攻击不同,可以实现对对抗攻击具有挑战性的特定恶意目标. 此外,我们提议采用ShadowCode,这是一种简单而有效的方法,在代码模拟的基础上自动生成诱导扰动,以实现有效而隐蔽的外部即时注射. ShadowCode通过模拟受害人的代码上下文来设计其扰动优化目标,并采用了一种贪婪的优化方法,有两个增强模块:前向推理增强和基于关键词的扰动设计. 我们评价我们的方法涉及13个不同的恶意目标,产生31个威胁案件,涉及三种流行的编程语言。 我们的结果显示,ShadowCodessuccessly攻击了三个具有代表性的开源代码LLM(达到97.9%的攻击成功率)和两个主流商用代码LLM-集成应用(超过90%的攻击成功率),只使用12个不起作用的诱发扰动。 该代码可在https://github.com/LianPing-cyber/ShadowCodeEPI上查阅.",
