    "summary": "图快速学习(GPL)有效地弥合了图前培训和下游任务之间的差距,解决了知识转让中的瓶颈问题. 然而,在前期训练期间,它易受后门攻击的可能性基本上仍未加以探讨。这部作品系统地调查了GPL的后门风险,并引入了TrojanGPL-a跨文本的后门攻击,其嵌入触发方式完全通过操纵事先训练过的编码器,独立于下游知识. 我们的分析表明,与迅速机制共同优化触发图不仅缩小了上下游主要任务之间的差距,而且协调了主和后门学习目标,便利了从事先训练过的模型向各种下游应用的无缝后门转移。 为了对付这一威胁,我们提议建立 \" 探测器 \" 防御机制,通过在清除重要节点时发现歧视性嵌入移位,确定后门图样。具体地说,当清洁和后门图被预测为同一类时,清洁图显示出稳定的嵌入变化,而后门图则显示出与清洁图的重大偏差. 对5个基准数据集和3个GPL框架的广泛实验表明,TrojanGPLachie在不同跨文本情况下的攻击成功率超过90%,同时对主要任务的执行影响最小。 同时,ES-探测器在所有测试设置中将攻击成功率至少降低60%,验证其实际稳健性而不事先知道攻击模式.",
