    "direction": "信息安全",
    "summary": "多式联运大语言模型(MLLMs)通过对文本和视觉输入进行联合推理,成为广泛现实世界应用的组成部分. 然而,尽管最近在安全协调方面取得了进展,但MLLMs仍然容易受到越狱袭击,在越狱袭击中,精心设计的投入可以绕过安全机制,引起有害的反应。 在这项工作中,我们调查了MLLMs在文本视觉情景中的安全弱点,并提出了一个名为PolyJailbreak的新黑盒越狱框架。 我们首先确定一种现象,即称为多式联运安全不对称的现象,即视觉对接在各种模式中造成不均衡的安全限制,并削弱整体稳健性。 我们分析MLLMs中的注意力动态和潜在表达,揭示视觉输入会干扰跨模式信息流,并降低模型分离善意和恶意意图的能力. 基于这些调查结果,我们提议“多功能断裂”(PolyJailbreak),将已发现的弱点组织成一个结构化的可重复使用的原子战略原始资料库,以便逐步从有害意图转变为有效的断狱投入。 在这些原始物的指引下,一个基于强化学习的多剂优化过程会自动使攻击适应目标模型而不访问内部参数. 对多种MLLMs的广泛实验表明,PolyJailbreak的性能始终高于最新水平的越狱基线,在包括GPT-4o和双子座在内的商业黑盒模型上,攻击成功率平均提高18.15%,成功率超过95%.",
