    "direction": "人工智能",
    "summary": "超维计算(HDC)是一种计算和数据效率高的范式,起到连接器和象征性的人工智能方法(AI)之间的桥梁作用. 然而,HDC的简单化对编码复杂的组成结构提出了挑战,特别是在其约束性运作方面。 为了解决这一问题,我们提议采用通用全图减少代表制(GHRR),延长Fourier全图减少代表制(FHRR),这是HDC的具体实施.GHRR引入了一种灵活、非模拟的约束性操作,能够改进复杂数据结构的编码,同时保持HDC所期望的稳健性和透明度。 在这项工作中,我们引入了GHRR框架,证明了它的理论属性和对HDC属性的坚持,探索了它的内核和绑定特性,并进行了经验实验,展示了它的灵活非共性,提高了组成结构的解码精度. 我们还表明,在GHRR中,约束性比在其他HDC变体中更具表达性;特别是,我们表明,在GHR中约束性可以实施某种关注机制。 我们通过用其GHRR等效的变速器取代变速器中的注意机制,并在语言建模任务上进行测试来验证这一点,显示与香草变速器相比性能有所改善.",
