    "summary": "Visuo-haptic的相互作用由于与机器人和康复有关,对感知研究越来越感兴趣. 虽然融合同时结合的动能提示的好处有详细记载,但视觉和触觉之间竞争性互动的时间动态仍然不够了解。 根据单方面感官间切换的现成经验证据,我们询问,对视觉和触觉刺激的双边探测是否可以通过交叉感官竞争来解释,并通过多层次神经网络模型来探索基本的感官动态。 根据对单边和双边视觉、触觉和相对作用目标的反应时间任务速度加快的结果进行测试,该网络成功地预测了按顺序识别不同方式在同一只手上而不是跨手上的无感刺激的开关成本较高。 我们的网络还捕捉到刺激间距,试验类型(即.重复 vs.)和模式类型(即视觉、触觉或触觉。 此外,关于具体网络联系的敏感性分析区分了双边目标非感知处理和多感知处理的潜在机制。网络预测和行为数据都显示,由于反复提出同步相对活性目标,速度放缓,这表明交叉感官抑制可能助长视觉对双边触觉感知的离线影响。",
