    "summary": "基于知识的视觉问答(KB-VQA)通过要求外部知识超越所提供的视觉和文字投入,扩展了一般的视觉问答,方便了更复杂的现实世界应用.KB-VQA提出了独特的挑战,包括统一不同方式和来源的不同信息,从大规模和吵闹的储存库中检索相关知识,以及执行复杂的推理从综合上下文中推断答案。 随着大型语言模型的进步,KB-VQA系统经历了显著的转变,LLMs作为强大的知识库,检索增强的生成器和强大的理性器. 尽管取得了很大进展,但最近没有进行系统调查,以组织和审查现有KB-VQA方法的不断变化的情况。本次调查的目的是通过建立关于KB-VQA方法的结构化分类,并将主流系统分解为三个基本阶段:知识表述、知识检索和知识推理,来填补这一空白。 通过审查每个阶段采用的现有技术,本调查查明了持续存在的挑战,并概述了有希望的未来研究方向,为推进KB-VQA模型及其应用奠定了基础。",
