    "summary": "近期在半监督视频对象分割方面的进展很大程度上取决于基于内存的方法. 然而,当面对复杂场景中出现的日益严峻的挑战,如基本语义转换和严重的空间变形时,这些基于记忆的方法中通常采用的固定间隙内存更新机制不足以配合物体变化的关键时刻. 这种不灵活的机制激励我们针对目标物体的语义-空间变化设计适应性内存更新机制. 为此,我们提议建立一个新型的变革敏感网络(CSNet),以了解何时和如何更新内存,以有效应对复杂情况下的复杂挑战。具体来说,我们首先设计了一个适应感-Capture模块,具有等级对比性学习损失,通过测量对象变化的程度来确定何时更新内存瞬间,从而将整个视频分成不同的对象变化片段. 为了进一步提取和突出对象变化,帮助在变化发生后对帧进行分割,我们构建了动态内存更新模块,通过在剪辑中顺利保留对象原型,并动态扩展各个剪辑中的对象变化,重新定义如何更新内存.广泛的实验表明,我们提议的CSNet在八个数据集(包括常见、复杂和长视频数据集)的评价中显示出明显的优越性。",
