    "summary": "公平意识-联邦图神经网络(FedGNNs)需要同时考虑服务器和客户端. 然而,由于分布式学习框架,公平-意识方法在不牺牲效用的前提下,努力增强双视角(即服务器和客户端)的公平性. 因此,在联邦框架内,公平-认识图表学习方法的效用牺牲甚至更加严重。 在这项工作中,我们提出F3GL,一种双视角的公平联动图学方法,既能提高全球(为服务器),又能提高当地(为客户)的公平性,同时又能保持效用. 通过理论分析,我们划定了原始敏感特征与不同光谱下演化后的特征之间的相似性. 我们的调查结果表明,只有主要价值才有助于加强这种相似性。 此外,我们的理论分析普遍适用于客户和服务器。具体地说,采用专门的精品价值选择战略可以有效地优化当地和全球的公平性。 根据这些见解,我们通过光谱图理论的透镜来提高双视角的公平性,同时又不牺牲效用. 两个现实世界数据集的实验结果显示F3GL优于现有基线.",
