    "direction": "人工智能",
    "summary": "演化算法(EAs)的迭代搜索过程囊括了历史人口和健身评价中的优化知识.有效利用这种知识对于促进知识转让和在线适应至关重要。 然而,目前的研究通常孤立地处理这些目标,并面临明显的限制:进化相继转移优化往往因对先前知识的不完全利用而受到影响,而利用实时知识的适应性战略则仅限于调整特定的进化操作者。 为了同时实现这两个能力,我们引入了优化知识适应进化模型(OKAEM),这是一个统一的可学习的进化框架,能够在现有优化知识的基础上适应性地更新参数. 通过关注机制对演化操作者进行参数化,OKAEM使可学习的更新规则能够通过两个阶段促进优化知识的利用:预先培训以整合广泛的先前的知识,以便高效的转让;以及适应性优化以动态更新基于实时知识的参数.实验结果证实,OKAEM通过预训大大超越了12个转移情景中最先进的顺序转移方法,并且完全通过其在前自由环境下的自我调节机制,超越了先进的可学习的EA. 除了在即时调试视觉语言模型中表现出实用性外,衰减研究还验证了可学习组件的必要性,而可视化分析则揭示了模型自主发现可解释的演化原理的能力.",
