    "direction": "数据工程",
    "summary": "在地理社会网络中,半径为$k$-core的查询(RB-$k$-core查询)旨在识别所有包含特定查询顶点的$k$-core查询,其中每个$k$-core中的所有顶点都属于指定查询半径为$r$定义的圆圈. 这些查询被广泛用于团队组建和事件组织等应用中. 然而,对没有域名专长的用户来说,指定查询参数$k$和$r$can具有挑战性,往往导致查询结果不一致.具体来说,一些预期的顶点可能缺失,而结果中可能会出现意想不到的顶点. 为了解决这一问题,我们调查了对预期进行优化参数(EOPE)和意外(EOPU)结果进行RB-美元核心查询的问题。目标是探索最佳参数,确保预期的顶点$\\omega$(或意想不到的顶点$\\psi$),并在同一RB-k$-core中查询顶点$q$的出现(或不出现). 对于EOPE问题,我们首先提出两个基线算法:PriorityRandHybridR. 为了提高效率,我们开发了两个更先进的算法:Priority KandHybridK. 此外,我们还根据顶点和R-Tree的分级核心性,引入了名为HCR-Tree的新指数,以提高勘探效率. 对于EOPU问题,我们首先从一个基本解决方案(BS)开始,然后设计分块算法SA,它包含了有效的推算和终止策略. 我们对五个现实世界的地球社会网络数据集进行了广泛的实验.结果显示,我们提议的算法有效地探索了最佳参数。 其中,HybridKproves对EOPE最为有效,而SAperforms对EOPU最为有效. 此外,HCR-Treeoutperers还针对EOPE和EOPU两个问题提出了R-Tree.",
