    "direction": "人工智能",
    "summary": "现代视觉模型取得了显著的准确性,但解释了证据在哪里出现,模型编码是什么,内部计算如何组装这些证据仍然支离破碎. 我们采用一个以iERF为中心的框架,围绕一个单一分析单元统一本地、全球和机械的可解释性:指向特征矢量(PFV)与其特异性的有效受体场(iERF)对齐。在当地方面,共享比率分解(SRD)通过共享比率将每个PFV表达为上游PFV的混合物,并传播iERF,以构建阶级区别的显要地图.SRD产生高分辨率,激活-忠实的解释,强于定向操纵和噪音,在常见的非线性上仍然具有激活-不可知性. 就全球而言,我们采用了概念-安乔雷德特征解释(CAFE),将iERF用作语义标签,将抽象的潜在矢量置于可核查的像素级证据中。 通过CAFE,我们应对非本地化的稀疏自动编码器潜伏的挑战,特别是在变形器中,早期的自我关注将遥远的背景混为一谈. 为了回答代表是如何通过深度构成的,我们提出带有跨层概念分配(ICAT)的跨层概念图(Interlayer Constitution Graph),该图在孤立层对的同时量化概念到概念的影响;一个跨层插入/删除协议将集成梯度确定为最忠实的即时. 从经验上讲,跨越ResNet50、VGG16和ViTs,我们的框架在忠诚和稳健性两方面都超过了基线,成功地诠释了分散的SAE特征,并揭示了主导概念路线正确、错误分类和对抗性案例。 我们的方法以iERFs为基础,提供了从像素到概念到决定的连贯的,有证据支持的地图.",
