    "summary": "安装在机上边缘计算设备的低地球轨道星座的部署日益增加,使卫星边缘计算(SEC)能够进行机上处理,以完成对耐久性敏感的任务,从而使其变得日益实用。 在此情况下,不同的机载计算能力、带宽限制的连通性以及资源争议使得任务调度对于协调任务定位和多跳转发是不可或缺的。常规排程器往往首先优化耐久性和能量(紧凑的最后期限、有限的机载能量和可计量的成本),而隐私则更难量化,因而不够模型化,有可能通过快速多跳转发、不信任的执行选择、任务合用地点等,导致更高的曝光率。 为了实现这些相互冲突的目标,本文件制定了统一的优化框架,并提出了两个相辅相成的时间安排方案。 我们首先引入了任务排程优化器(TS-OPT),这是一种集中的混合整数编程方法,为拟议的模型提供了最佳的参考. 为了克服集中解析器的可扩展性限制,我们随后开发了\"隐私-智能潜在游戏调度器\"(PAPGS),这是一种分散化的算法,将问题定位为精确的潜在游戏,并汇集在数量有限的最佳反应更新中,以达到纯战略的纳什均衡.模拟结果显示,PAPGS在小规模情景中实现了对TS-OPT的0.35%的优化性差距,并持续实现了较低的统一系统成本,在更大的规模上满足了较高的最后期限。",
