    "summary": "量化,或称流行性估计,是预测每个类别在未知的例子包内流行性的任务.文献中大多数现有的定量方法都依赖于之前的概率移位假设,以创建一个定量模型,利用基础分类器的预测来作出最佳的流行率估计. 在这部作品中,我们呈现了一个端到端神经网络,利用潜伏空间中的高斯分布来获得无变异的示例袋的表示.这种方法通过深入学习解决量化问题,使与问题相关的特定损失功能得到优化,避免了中间分类器的需求,将量化问题作为直接优化问题处理. 我们的方法取得最先进的结果,既可以采用传统的量化方法,也可以采用其他深入学习的方法进行量化。复制我们所有实验所需的代码可在https://github.com/AICGijon/gmnet上公开查阅。",
