    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tdsc.2026.3699719",
    "direction": "信息安全",
    "summary": "Beamforming反馈信息(BFI)感知正逐渐成为基于CSI的频道状态信息(WiFi感知)的有希望的后继者,这得益于它在商品硬件上的可访问性而不使用驱动程序黑客. 然而,对其安全影响的研究却很少。与CSI不同的是,BFI以简写的形式播出,为对手提供一个更广泛的攻击表面. 我们提出幻影束,这是对基于BFI的感知进行反射攻击的第一个实际框架。 通过注射精心设计的BFI帧,对手可以发动非目标攻击和焦油攻击,造成行为识别系统中的错分类.核心挑战是尽量扩大错误分类,同时保持与正常行为样本无法区分. 我们提出了一个优化问题,共同选择伪造的BFI振幅和注射时间,以隐蔽控制接收器观察到的BFI序列. 此外,真实世界的注射面临挑战,即因无法预测的注射延误而攻击同步性。 我们引入了一个延迟-BFI注入窗口,并将优化改编成一个加权配方而不是延迟单元,从而能够无缝地适应各种延迟。 在商品WiFi硬件上实施,覆盖三个室内环境,幻影束取得了81%以上的成功,同时将探测率保持在30%以下,揭示了现有BFI感知系统的关键弱点。最终将概述可采取行动的反措施,以保障今后对英国金融情报机构的遥感部署。",
