    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tpami.2026.3688816",
    "direction": "人工智能",
    "summary": "近年来,开发了多种散列技术,以促进高效的跨模式检索。 一旦一个检索模型被部署,散列码长度就会固定,以实现最佳性能. 为了处理不同的检索情况,同时保持检索的准确性,一个共同的做法是重新设计和重新训练具有不同散列码长度的原始模型。 然而,这种再培训过程会增加培训负担,并可能导致更糟糕的结果。 为了应付这些挑战,我们提出 \" 重生的跨摩尔海兴 \" (RCMH),这是一个新型的跨模式散列框架,旨在提高现有散列码的质量,并以高效率将其转换为任意长度。 首先,我们在扩大标签信息生成的相似性矩阵的监督下,将现有的散列码剪辑或贴上,以便以目标长度初始化。 第二,我们采用了线性-非线性竞争性重建方法,以减少语义上的空白,并进一步从线性图像特征和非线性文本特征中捕捉更深层的关系. 这样,对每对样本进行对比和选择,以获得可以保留模式特定属性的重建二进制代码. 最后,为了降低变量迭代引起的培训费用,使用了再生散列词,用重建的二进制代码重新生成最终散列代码,同时从现有的散列代码中保存信息而无需迭代优化.值得注意的是,RCMH可以以稳健性与现有的最先进(SOTA)方法结合,帮助他们调整散列码长度,实现更好的检索性能.",
