    "summary": "协作推论(CI)通过将中间特性传输到云模型,提高了边缘设备的计算效率. 然而,这一过程不可避免地暴露出特征表达方式对模型反演攻击(MIAs)的曝光,使得未经授权的数据重建成为可能. 尽管进行了广泛的研究,但对于评估执行MIA的困难没有既定的标准,留下一个根本问题没有得到回答:哪些因素真正和可核查地决定了袭击在CI中的成功? 此外,现有的辩护缺乏上述理论基础,因此很难在确保隐私和尽量减少计算间接费用的同时,对特征信息进行有效的管理。 这些缺陷提出了三大挑战:理论差距、方法限制和实际限制。 为了克服这些挑战,我们提出第一个理论标准,以评估MIA在CI中的难度,确定相互信息、py和有效信息量为关键影响因素。 我们利用相互信息神经估计器对相互信息进行量化,这是评估防御的隐私保护效果的关键衡量标准,并验证拟议的标准。 基于这一见解,我们提出SiftFunnel,一个保护隐私的框架,在保持可用性的同时抵制MIA.具体地说,我们结合了线性和非线性相关限制,加上标签平滑来抑制冗余的信息传输,有效地平衡了隐私和可用性. 为增强可部署性,边缘模型采用漏斗形结构,并配有注意机制,加强隐私,同时减少计算和存储负担.实验显示,与最先进的防守相比,SiftFunnel将重建错误增加%-30%,将相互有效的信息衡量标准降低50%,将边缘负担降低近20×,同时保持可比的可用性.",
