    "summary": "Malware对Tthings(Iot)的互联网系统构成重大威胁,导致未经授权的访问和数据违反.不断发展的恶意软件继续对IOT系统构成严重威胁,需要能够适应性学习和实时战略决策的防御机制. 为此,我们提出了基于差异游戏和边缘智能(EI)带动的IoT系统中的尖端神经网络的新型IoT恶意软件传播和补丁模型.具体来说,基于最佳控制理论,我们揭示了感染的IOT设备与关联的边缘节点之间的动态演化过程,这些节点是基于在EI激活的IOT系统中恶意传播下的差别游戏.动态状态过渡用微分方程来描述,然后引入攻击/防御意图,从理论上实现最佳IoT恶意软件补丁策略. 此外,我们设计了一个小的IOT恶意软件传播-patching方法,命名为基于差分游戏的深溢Q网络(DGDSQ),用于EI启用的IOT系统中的实用补丁优化决定. 此外,我们进行实验模拟,以了解DGDSQ辅助的边缘节点比双深Q网络和双深Q网络对抗IOT恶意软件传播更有效.",
