    "summary": "多维群集(MVC)因其在各种观点中利用补充信息的能力而获得极大关注. 然而,现有的深层MVC方法在交叉视聚时往往与视差分配缠绕相搏,这妨碍了共享潜在空间的质量,导致集群性能不理想. 为了解决这一问题,我们提议采用通用多视图自动编码器(GMAE),这个框架旨在通过分散的表述学习来保持跨视图互补。具体地说,GMAE使用双路径自动编码器将源特征解析为视点专用和视点通用嵌入,便于发现更清晰的集群结构. 我们进一步构建交叉视角对抗性歧视者,以指导特定视角编码者捕捉更多歧视特征.GMAE通过战略调节相互信息,有效协调分布,防止代表崩溃,确保生成稳健,非三角嵌入.13个基准数据集的综合实验表明,全球海洋环境状况评估在完整和不完整的MVC任务中,其业绩始终高于最先进的方法。",
