    "summary": "作为最有吸引力的贝叶斯网络分类器(BNCs)之一,K-依赖贝叶斯网络分类器(KDB)可以通过允许每个属性在类上附加条件,最多还有K其他属性,从而有效捕捉属性之间的依赖性. 然而,随着K变大,其结构复杂性大大增加,这不可避免地导致一定的适应过度的风险. 此外,当K被赋予时,其结构是不可改变的,这极大地限制了最终模型的表达能力. 为了解决这两个问题,在本研究中,我们提出了K-免依赖贝叶斯语(KFDB)分类法,它可以为每个属性学习一个适应性数量的母节点. 为了搜索其最佳结构,我们依次评估候选子模型,要么尽量减少平均方形错误(MSE),要么尽量提高分类精度(ACC),结果有两个版本分别表示为KFDBMSE和KFDBACC.60个基准数据集的实验结果表明,KFDB显著优于古典KDB和其他最先进的模型.",
