    "summary": "医学超声波(US)图像分解由于标注的数据和特征成像文物有限,包括光谱噪声和低孔隙边界,面临重大挑战. 虽然为解决数据稀缺问题出现了半监督的学习方法,但现有方法在数据利用方面缺乏最佳的无标签,缺乏强有力的特征表述机制。 在本篇文章中,我们提议Switch,一个具有两个关键创新的新式SSL框架:1)采用分级补丁混合的多尺度Switch(MSS)策略,以实现统一的空间覆盖;2)一个频率域切换(FDS),具有对比性学习,在傅里叶空间进行振幅切换,以进行强壮的特性表达. 我们的框架将这些组件整合到师生结构中,以有效地利用有标签和无标签的数据。 对美国六个不同的数据集(淋巴结、乳房损伤、甲状腺结核和前列腺)的综合评价显示,它们始终优于最先进的方法。 在5%的标签率上,Switch取得了显著的改进:在LN-INT上为80.04%,在DDTI上为85.52%,在前列腺数据集上为83.48%,我们的半监督方法甚至超过了完全监督的基线。 该方法在提供优异性能的同时保持参数效率(1.8M参数),验证其对资源紧张的医疗成像应用的有效性.源代码在https://github.com/jinggqu/Switch上公开.",
