    "summary": "基于Anchor的多视图集成因其准确性和计算效率而显著进步. 然而,它依赖于一个假设,即各种观点的数据是完全对齐的,而由于同步收集数据,在实践中往往违反了这一假设。 这妨碍了捕捉互见一致性和互补性的能力。很少有研究通过双方图对齐来解决这个问题,但是,由于未铺设和不平衡锚点造成的双方图体之间能量不和谐和损失的挑战仍未得到探讨。为应对这一挑战,本研究开发了一个名为\"节能转移双面图学习\"(ESBGL)的新框架,用于无保值的大型多视角集聚,以确保能量的和谐与保存.具体地说,ESBGL同时提出锚定对接学习和双方图学习技术,使锚定和双方图在观点上一致,这可以避免双方图之间的能量不协调. 随后,设计了一个转变的双方图学习范式,以保存集群信息和最终共识双方图的巨大能量.广泛的实验和评价证明了我们的ESBGL的有效性和优越性.",
