    "link": "https://doi.org/10.1109/tdsc.2026.3697662",
    "direction": "信息安全",
    "summary": "车辆排是车辆临时网络(VANET)中日益重要的技术,有效地减少了能源消耗和环境污染,缓解了交通拥堵,增强了道路能力和交通安全. 各排之间可以进行协作交流,以提高数据传播的可靠性,改善驾驶战略,并进一步加强交通效率。 尽管如此,目前安全进行多平台数据传播的努力仍然面临下列问题:(一) 在不同系统工作的排缺乏直接授权战略;(二) 在排通信期间没有保护车辆隐私的有效机制;(三) 跨系统密码转换缺乏实际的核查办法。本文为缓解上述问题,构建了隐私保护和可核查的跨系统授权(PVCA)计划.具体来说,我们首先提出了优化的匿名广播加密(IBBE)和政策隐藏属性加密(ABE)协议,以在保护身份和属性隐私的同时调整排通信. 在此之后,将拟议的协议连接起来的经授权的令牌旨在使IBBE格式的密码文本能够转换成ABE格式的新密码文本,从而能够灵活授权. 此外,在藤崎-小本的转变的启发下,我们设计了知识协议的有效零知识证明,使我们的PVCA实现可核查和公平.严格的安全证据和分析表明,我们的PVCA不仅能够防止所选择的简单攻击和串通攻击,而且能够满足必要的安全要求。 我们采用了PVCA的原型(在一台台式计算机和Raspberry Pi上),并提供利用NS-2的模拟,以验证其在VANETs中排通信的可行性。结果显示,与最先进的密码变换解决方案相比,PVCA将原始密码生成,变换,解密的运行时间分别减少至少91.57%,49.87%和50%,同时将原始密码和授权令牌大小压缩78.07%以上和15.20%以上.",
