    "summary": "随着IOT设备的迅速扩散,生成的数据量以前所未有的速度增长. 由于边缘设备的资源有限,此数据有相当一部分必须传送到云中进行深度处理,大规模分析,长期存储,以及存档目的. 因此,业绩已成为一个重大关切问题。 虽然查明这一领域的现有挑战和研究差距需要系统审查,但现有调查文献中仍然基本上没有这种努力。本条通过对近期优化办法进行有条理的审查,弥补了这一差距。 它首先将文献分类为三大策略:无损失传输,无损失传输,以及混合方式. 在无损传输的背景下,我们分析数据压缩算法和增量与全同步机制等技术. 对于损失策略,我们分析包括损失压缩和预测方法在内的方法. 此外,我们调查了混合战略,这些战略结合了无损失和无损失技术,以利用其互补优势。 最后,我们讨论现有研究的局限性,并强调未来研究在优化边缘至云层数据传输方面有希望的方向。",
