    "summary": "据我们所知,本文最早将分形信号处理与视觉图神经网络整合,建立了符合分形动力学的新图表现式学习范式. 在这个基础上,我们提出一个分形域视野图神经网络(FD-ViG).具体来说,FD-ViG包括:(一)一个分形-域学习模块,利用当地的Hölder指数和Singularity Power Spectrum(SPS)将图像映射到分形-域内,使分形-空间特征聚变成为可能;(二)一个分形图形构建模块,通过将语义注意力与分形特征空间中的分形相似性结合起来,以适应性地生成一个地形学;(三)一个图形传播模块,用电法多尺度传播,实现跨尺度的传播和聚合,使文字结构学习成为可能。 在UCMerced、RSSCN7和SIRI-WHU的实验中,总体加速率分别为91.75%、89.52%和92.78%。与ViG,WiGNet,和ViHGNN等具有代表性的视觉图模型相比,我们的方法在所有三个数据集中都比以前的方法取得了一致的改进,同时保持了轻量级(2.6 M参数). 此外,尽管我们的模型比ResNet-18的参数要少得多,但在两个数据集上,我们的模型能产生竞争性或更好的性能,并进一步表明在合成孔径雷达图像的跨数据集评价中具有强大的通用能力。这项工作为分形理论和图深学习提供了一个原则性和有效桥梁,有利于在复杂的纹理和结构下对可解释的遥感场景的理解。",
