    "summary": "缺乏贴有标签的数据,对使用深层学习模型进行医学图像分解提出了重大挑战,这些模型的\"黑盒\"性质本质上限制了它们在临床部署过程中的可解释性. 为了解决这些问题,我们提议采用基因可适应分解演化(GASE),在极端数据稀缺的情况下,为强健和可解释的医学图像分解建立一个端到端的、基于风格的分解对抗性框架。接受有限单序列磁共振(MR)数据培训,通过扫描协议、成像序列和病人人口统计学的差异,GASE自适应无形的获取级图像变化,同时通过自动输入有效性评估和输出可靠性估计,提高可解释性。 在对抗性训练中,风格学习生成器捕捉到对有效输入解释的输入样式特征的多样代表,并通过样式插图将标注的训练对子进行拓扑,以模拟获取级别的图像变异. 基于分化的歧义者,接受过这些多样化样本的培训,进一步改善了对隐形风格的适应,并通过信心学习自动估计了预测口罩的可靠性. 对膝盖和骨盆MR图像数据集的广泛实验表明,GASE在评估正在检查的多个组织时实现了高度分化的精度,对看不见的获取级图像变化有强烈的适应性,以及内在的可解释性,突出了其可靠的临床部署潜力.",
