    "summary": "分散式联合学习(DFL)作为分析分布在多个站点的大规模数据的框架,得到了极大的关注,在多个站点之间的交流受到分散式图表结构的限制. 由于隐私问题和通信费用高昂,DFL中通信回合的减少已成为一个重要的研究领域. 本文章调查了分散图的地形学对DFL算法的趋同率的影响,并引入了一种基于新颖的拉诺语的多声道步法(T-MGS)方法,从地形学角度优化通信效率.这种方法的核心理念是使用八卦百合器来指导站点之间的信息流,并且可以在不增加其音量的情况下,在每一个通信步骤上对传输的内容进行动态调整. 拟议方法将等效八卦矩阵的第二大绝对值最小化,这是影响趋同速度的关键因素.模拟和真实数据集的实验结果表明,拟议的T-MGS在通信效率方面超过了现有的战略,在不损害模型准确性的情况下减少了通信回合的数量.",
