    "direction": "信息安全",
    "summary": "现有的基于属性的可搜索加密方案提高了对加密数据进行精细关键词检索的能力;然而,它们仍然受到两个基本限制。 首先,大多数现有建筑都依赖于一个单一的可信赖的权威,这不仅导致中央实体的计算负担过重,而且限制了在分布环境中密钥管理的可扩展性. 其次,许多方案在密码文本或搜索符中揭示了敏感的属性或政策信息,导致隐私泄露,并使得无法信任的服务器能够进行推断攻击. 这些缺点突出表明,需要有一个分散的、保护隐私的可搜索加密框架,能够支持表达式查询,而不暴露访问结构或用户属性。 为了克服这些局限性,我们首先设计了一个匿名的多授权密钥政策属性加密(MA-KPABE)方案。 我们的构造隐藏了嵌入在用户密钥中的访问政策,以及嵌入在密码文本中的属性,从而限制了密钥生成过程中的信息泄漏. 在这个基础上,我们进一步将MA-KPABE扩展为基于多授权属性的可搜索加密(MA-ASE)方案,在保留关键词隐私的同时,整合表达关键词搜索能力.由此形成的系统使分散式钥匙管理、隐私保护访问控制以及在统一的密码框架内进行安全表达式搜索成为可能。 我们正式证明,拟议的计划满足了IND-CPA、匿名和IND-CKA的安全要求。全面的绩效评价表明,分布式架构大大降低了权威侧计算负荷,实现了大规模加密检索情景的实际效率.",
