    "direction": "信息安全",
    "summary": "信息技术举措的两个关键方面是安全和资源消耗。物理无克隆函数(PUFs)是利用集成电路内在制造变体生成独特识别器的硬件安全原始体. 由于它们的独特性和对克隆的阻力,它们被广泛用于IOT设备认证. 在这项工作中,采用了一种新颖的办法,提高补偿性计量的可识别性。这种方法涉及在进行比较以确定输出位数之前,先对从聚苯乙烯乙烯来源提取的参数使用特定重量罩。 这一技术已在使用公共数据集建造的几种福林中进行了试验。 因此,人们观察到,平均误差率(EER)可以大大提高,最高可达到两个数量级. 这一技术的主要优点是它不会修改补偿测量PUF的架构(这对IOT设备来说是有趣的,因为它不需要额外的资源),同时它也被证明是通用的,即最优的口罩参数可以使用一小组设备找到,然后被泛化到另一组更大的设备. 这样,这一提议有助于开发IOT设备的新认证计划,既解决安全和资源效率问题,又解决IOT环境中的关键问题. • 一种新的优化技术,以提高补偿性计量的可识别性及其理论依据。 • 优化仅需要一小部分设备作为培训数据集,从而能够向更多的设备群进行通用。· 利用利用公共数据库建造的不同类型的福林,实施这一技术和测试。· 采用一种技术,这种技术不需要以初始化计数器为基础而增加硬件资源。",
