    "summary": "随着区块链技术的进步,链式拜占庭断层推力(BFT)协议在实用系统中越来越多地被采用,使得其性能成为研究的一个关键方面. 在本文中,我们采用了一个统一的框架,利用Markov决策程序(MDP)来模拟和评估三个突出的连锁BFT协议的性能. 我们的框架有效地抓住了复杂的对抗行为,侧重于两个关键的业绩衡量标准:链式增长和承诺率。 我们实施从MDP分析中获得的关于连锁BFT协议的现有评价平台的最佳攻击战略,并在各种环境下进行广泛的试验,以验证我们的理论结果。 通过严格的理论分析和彻底的实践实验,我们对不同攻击情景下的连锁BFT协议进行深入评价,发现最佳攻击策略.与传统的信念相反,我们的调查结果表明,虽然反应能力可以提高业绩,但并非所有情况都普遍受益。这项工作不仅加深了我们对连锁BFT协议的理解,而且提供了宝贵的见解和分析工具,可以为设计更有力和更有效的协议提供信息。",
