    "summary": "在敌对环境中部署无人驾驶飞行器用于森林火灾探测(FFD),对分散的学习系统构成严重依赖性挑战,在这种系统中,无人驾驶飞行器容易受到极端热量、动荡的气流和浓烟的破坏。 这种损害可能导致数据损失,并损害发展筹资特派团的效力。 为了应对这些挑战,我们提议建立一个强力八卦学习框架(RGLF),这是一个容错和分散的学习框架,可加强无人驾驶飞行器群型FFD任务的强性和适应性。RGLF引入了重力集群方法,将无人机组织成分散的集群,分散数据冗余的八卦备份方法,以及动态指定具有代表性的无人机进行模型训练的适应性八卦杂交器选择方法,防止由于八卦杂交器的失能导致任务失败. 通过消除对中央协调员的依赖,RGLF通过分散的八卦学习,使容错模型得以更新,确保在无人驾驶航空器丧失能力的情况下继续学习。实验结果表明,即使一些无人驾驶飞行器丧失能力,RGLF也能大大提高任务性能.RGLF通过加强无人驾驶飞行器群稳性,为基于无人驾驶飞行器群的FFD任务提供了更可靠和可扩展的解决方案.",
