    "summary": "随着大数据时代资源的积累和深层次学习中预训模型的兴起,优化各种任务的神经网络往往涉及从零开始精细调整预训模型与培训的不同策略. 然而,现有的优化者主要注重通过更新模型参数来减少损失功能,而没有完全满足这两个主要范式的独特需求. 在本文中,我们提出了DualOpt,一种新颖的方法,专门针对这些不同的培训情景,使优化技术脱钩。 对于从零开始的训练,我们引入了实时的图层式重量衰减,旨在通过与重量更新和网络架构的特征相适应,增强趋同性和概括性. 为了进行更重要的微调,我们把重量回滚与优化器结合,将一个回滚术语纳入每个重量更新步骤中. 这确保了上下游模型之间权重分布的一致性,有效缓解了知识遗忘,提高了精细化性能. 此外,我们把分层的重量衰减扩大到动态地调整各层的回滚水平,以适应不同下游任务的不同需求。跨不同任务的广泛实验,包括图像分类,物体检测,语义分化,实例分化,都显示了DualOpt的广泛适用性和最新性能.",
