    "summary": "本条为基于公用钥匙基础结构(PKI)的电子身份系统开发了一个提供者-不可知的安全框架,并将其应用于瑞典的两个成熟的部署,即BankID和Freja eID。 我们正式将Conononical用户行程——相同设备、交叉设备认证和签名——作为紧凑的国机模型,包括中间软件的变体。 从这些模型中,我们得出了三种协议层面的变动因素,它们指导着完全正确的执行:挑战与结果的新鲜度,严格的会话/原产地约束,以及用户批准的授权内容的动态连接。 然后,我们评价平台特征和依赖政党的一体化如何执行这些变化因素,并通过同一视角分析记录的事件。结果表明,两种生态系统都依赖坚实的公用钥匙基础结构基础,并提供满足变化者的技术手段;现实世界的危害主要来自意图欺骗、生命周期滥用、一体化薄弱环节和不完全的核查方执法,而不是密码故障。拟议的框架解释了这些模式,澄清了哪些控制至关重要,并提供了一个可重复使用的分析工具,在瑞典语背景之外适用于其他公用钥匙基础结构电子身份系统。 • 使用国家机器正式建立提供者-不可知电子ID操作模式。 • 三种安全变量来自结构化的攻击者分类法。· 统一的威胁-变化无常的-控制绘图澄清了端到端的电子ID风险。 • 真实事件通过协议变化性和治理性来解释,而不是通过密码破解。 • 框架将公用钥匙基础结构国家电子ID系统概括起来,并支持今后的设计评价。",
