    "summary": "在现实世界的情景中,多式联运联合学习(mFL)中随机模式缺失是一个重大挑战,削弱了全球模型推论的性能. 然而,现有的mFL方法主要限于一般涉及参与客户的简单设想,这些设想仅限于单一模式或具有完整模式的多式联运客户。 它们在每个客户端上使用特定模式的编码器,在服务器上培训模式聚变模块,导致客户端和服务器之间发生严重的任务漂移,并努力在复杂的模式缺失情景中有效概括. 为此,我们提出了一个新的mFL框架,以减轻因培训和推论期间模式缺失而造成的任务漂移和性能退化。受原型学的启发,利用高度普遍化的具体信息代词,我们精心构建了一个原型库,以加强基于FedAvg的联邦学习(FL).自然,我们利用原型作为代表缺失模式的面具,以弥补模式信息缺失,制定任务校准培训损失,并制定模式不可知模式-不完全推论战略。 此外,还构建了一个基于原型对比性学习的近名词,将客户间全球信息纳入每个客户,从而加强当地培训。 我们进行广泛的实验来评价我们的mFL框架,展示它在一系列缺失设置中的最新性能.具体地说,与现有的mFL方法相比,我们的mFL框架在培训期间提高了不同模式缺失率下的推论性能,在模式不完全推论时提高了23.8%.",
