    "summary": "神经科学的一大挑战是阐明大脑如何处理感官输入来产生行为,特别是考虑到整个大脑的神经活性难以测量.为解决这一局限性,之前的研究在大脑中使用了人工神经网络(ANNs)和模型化的决策电路. 在这里,我们利用小鼠的神经活动记录,作为对储油层计算机(RC)的额外投入,以及与任务有关的投入,使RC能够在生物上的基础操作。 我们把具有这种混合输入条件的驻地协调员称为混合输入驻地协调员(HRC),把没有神经活动输入的驻地协调员称为人工输入驻地协调员(ARC)。利用来自皮质或亚科地区的尖锐投入,人权事务委员会预测头部固定小鼠在任务期间的身体运动情况比ARC好。 这一改进不仅来自增加的老鼠神经活动,也来自人权理事会内产生的活动。生成的活性可能包括小鼠的未记录神经活性,这对ARC来说是困难的. 我们建议人权理事会可以产生类似未经记录的神经活动的活动模式,这可能有助于预测动物的运动。",
