    "summary": "间接飞行时间(iToF)成像通过主动照明调制和降级将光传输延迟编码成相关测量,从而提供绝对深度. 这一技术在物体探测和场景理解方面发挥着至关重要的作用,并被广泛应用于机器人,汽车驾驶,增强现实等应用中. 然而,iToF系统经常受到低信号对噪声比(SNR)的影响,特别是在强烈的环境照明下.信号衰减和噪音引起的相位错误严重降低深度精确度,而可靠的深度不连续和边缘重建仍然具有挑战性。 在本文中,我们引入了最佳视觉ToF成像方案,通过端到端学习iToF编码功能和深度重建来优化,以歧视性的Fisher信息监督为指导. 通过整合来自RGB图像的视觉信息,我们促进iToF编码功能优化的趋同,并在吵闹输入下增强稳健性. 此外,我们设计了一个双分支视觉ToF重建网络,从iToF的测量中估算深度,同时利用从视觉信息中衍生出来的边缘导线来保存精细的几何细节.合成数据集和实际世界数据集的广泛实验验证了拟议办法的有效性,特别是在具有挑战性的低国家自然资源保护条件下。",
