    "summary": "图像欺凌对提高图像能见度和减缓气候退化至关重要。 然而,大多数现有方法都依赖于配对的模糊和干净的图像,这些图像在现实世界的情景中很难获得。 为此,我们提出了一个面向巴伊西亚 -- -- 正规化的一致最佳运输(OBCOT)框架,该框架将未发光的图像解析任务定为最佳运输(OT)问题。具体地说,我们引入了结构保留运输成本,纳入了结构相似性(SSIM)的制约,以最大限度地缩小原始配体和双重配体之间的双重性差距,同时保留重建图像的结构细节. 此外,我们得出巴耶西亚频域规范化(BFR),以平衡光谱一致性与干净的参考文献和来自模糊图案的反感。 此外,我们采用预先训练的单步稳定扩散模型作为恢复网络,使用低档适应器(LORA)适配器和零进化层进行微调,同时整合特定域的文字提示,既要退化,又要清洁的图像来指导生成过程.广泛的实验表明,我们的方法超越了现有的表现良好的不成熟的学习方法,在忠诚和光现实主义两方面都取得了显著的改进。",
