    "direction": "人工智能",
    "summary": "本文调查了Graph Continual Test-Time Training的一个新问题和关键问题,其目的是使一个被冻结的预培训的图表模型能够在不受监督的情况下不断适应不断演变的分流(OOD)图表.现有的测试时间培训方法主要侧重于一步步的适应,忽略了长期的知识保留,而传统的持续学习方法则依赖于标注的数据和静态内存重播. 因此,它们无法有效处理连续的OD域,往往在动态图表环境中受到严重的遗忘和效率限制。 为了应对这些挑战,我们提议采用基于动态即时连续图学习(DPCGL)这一以数据为中心的框架,通过适应性即时优化进行持续的测试时间培训。DPCGL冻结了预先训练的骨干,并维持一个动态的快速池,其中对每个进入的图表域的提示进行适应性选择和更新. 这种设计通过在速率内而不是在模型权重内组织可转让的知识,使参数高效的适应和减轻遗忘。 此外,DPCGL联合优化了三个目标:代表性的相似性协调;知识保存的KL差异化规范化;概括化的多样化制约,在持续适应期间既提供稳定性,又提供适应性。 对多种不断演变的OOD图表基准的广泛试验表明,DPCGL实现了最先进的性能,有效地缓解了灾难性的遗忘,并使各领域能够不断进行强有力的适应。",
