    "direction": "人工智能",
    "summary": "感知是自主车辆和机器人中最重要的组成部分. 基于LiDAR的3D天体探测(3D-OD)为精确对象定位提供了准确的空间信息.传统的基于图像的3D-OD方法与深度估计相抗衡,使其对3D场景理解的可靠性降低.现有的基于LiDAR的模型使用单级或双级的演化网络来完成3D-OD任务.现有的模型在计算上与复杂的骨干相当昂贵. 我们提议加强主干,多尺度地物提取和空间关注,以改善基于LiDAR的3D-OD。 我们的骨干在计算上是有效的,因为我们已经减少了近40%的现有骨干参数,并实现了与现有模型相比的竞争性准确性. 多尺度特性提取在不同的分辨率上捕捉对象细节,以提供细而粗的特性.空间注意力集中于重要区域,压制背景噪声,以产生更准确的空间探测. 我国骨干整合多尺度特征集成和空间关注机制,提高检测精度. 我们的模型使用标准的单级和基于网格的3DOD输油管,并配有我们拟议的主干线. 我们进行了广泛的消化试验,以验证我们拟议的骨干效率。 我们的模型通过轻量级来超越现有的模型,这使得它非常适合实时应用. 我们用KITTI基准评估了我们的模型。 我们的结果在KITTI的官方领导板上作了介绍。",
