    "method": "从不同类别的真实实例中取边界对进行变形，通过两个度量 tsMIST_Avg 与 tsMIST_Std 总结分类器预测沿变形路径切换类别的点；形式化证明 tsMIST_Avg 估计边界位置的条件，指出其常见的参考值 0.5 反映的是源-目标对称假设而非普适目标；对比线性插值与路径插值（PathI，通过动态时间规整对应关系在时间上滑动匹配特征，而非混合幅度）。",
