    "contribution": "- 贡献一：带指数衰减项的模态依赖事件触发机制，解决切换+时滞下稳定判据与 Zeno 排除问题，并给出事件间隔下界。\n- 贡献二：把结果推广到 SNN 指数同步并以 LMI 表达设计条件，图像加密实验验证实用性。\n- 局限：未考虑脉冲信号本身的采样/传输时延；未来拟发展事件触发延迟脉冲控制并纳入外部扰动。\n---\nDOI: 10.1016/j.neunet.2026.109525",
