    "question": "信息系统已成为关键基础设施的底座，但传统基于边界、静态配置且依赖内部默认信任的被动防御模型，难以应对高度动态、大规模环境下的复杂与不断演化的威胁；从“外部防护+被动响应”转向“由内向外”的整体安全评估与动态防御体系是核心挑战。",
